// Package nativemirror manages the per-(repo group, cluster) native-mirror
// placements of native repos (ADR 20260720-native-mirroring). A row is
// both the placement record and the durable cross-jurisdiction creation
// intent: the primary jurisdiction's core writes it, and the target
// jurisdiction's lifecycle reconciler claims and executes it through the
// stage machine (pending → provisioned → registered → seeded → announced)
// or, when desired_state flips to 'deleted', through the teardown leg.
//
// Concurrency model: CockroachDB has no advisory locks, so exclusivity is a
// row lease — Claim is a single UPDATE ... RETURNING that stamps
// claimed_by/claimed_at and bumps attempts (the mirror_author_backfills
// pattern), and every subsequent transition is fenced on claimed_by AND
// CAS'd on the fields it advances, so an executor whose lease expired and
// was reclaimed cannot rewrite the new owner's row. A failed CAS is a
// signal to re-read: teardown is intended only when desired_state says so;
// an active row whose stage moved means another executor won.
package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"entire.io/core/model"
	"entire.io/core/repodeletion"
	"entire.io/postgres"
)

// Creation stages. Ordered; StagesServing lists the suffix from which a
// placement is serving-eligible (replication fan-out, resync sweep,
// completion-status writes).
const (
	StagePending     = "pending"
	StageProvisioned = "provisioned"
	StageRegistered  = "registered"
	StageSeeded      = "seeded"
	StageAnnounced   = "announced"
)

// Clone-lifecycle status, mirroring mirrorrepo's vocabulary so placement
// views render both kinds with one legend. StatusFailed doubles as the
// permanently-failed-creation marker (next_retry_at NULL).
const (
	StatusProcessing = "processing"
	StatusReady      = "ready"
	StatusFailed     = "failed"
	StatusSuspended  = "suspended"
)

// Deletion intent. DELETE flips desired_state and stamps suspended_at; the
// reconciler's teardown leg does the actual work.
const (
	DesiredActive  = "active"
	DesiredDeleted = "deleted"
)

// servingStages is the SQL fragment for "stage >= registered". The stage
// set is fixed; enumerating beats encoding an ordinal.
const servingStages = `('registered', 'seeded', 'announced')`

// completionEligible is the intent gate a worker completion must clear: a
// serving-eligible, active, unsuspended placement whose creation has not
// permanently failed. Shared by BOTH arms of ApplyCompletionStatus so the
// 'ready' and 'failed' paths can never drift on eligibility — a new lifecycle
// column added to one arm only would honor a completion for a placement the
// other arm refuses.
//
// Parenthesised so it stays safe by construction rather than by call-site
// convention: it is a bare AND chain, so splicing it unparenthesised into a
// predicate that has a same-level OR would silently regroup and WIDEN which
// placements accept a completion — the over-claim direction.
const completionEligible = `(stage IN ` + servingStages + `
		   AND desired_state = 'active' AND suspended_at IS NULL
		   AND creation_failed_at IS NULL)`

// ErrNotFound is returned by point reads when no row matches.
var ErrNotFound = errors.New("nativemirror: not found")

// ErrBeingDeleted is returned by Create when the (group, cluster) placement
// exists but is marked for deletion: the returned id would be reaped by the
// teardown leg moments later, so "resume the existing intent" is a lie for
// this state. Callers surface it as a retry-later conflict; re-creating
// becomes possible once teardown removes the row.
var ErrBeingDeleted = errors.New("nativemirror: placement is being deleted")

// ErrCellOccupied is returned when another cluster already holds a placement in the target cell.
var ErrCellOccupied = errors.New("nativemirror: target cell is occupied")

// ErrCellVacating is returned when only placements marked for deletion hold
// the target cell. The cell frees when teardown removes their rows, so a
// caller can retry.
var ErrCellVacating = errors.New("nativemirror: target cell is being vacated")

// ErrPlacementCellUnknown is returned when registry data cannot establish cell occupancy.
var ErrPlacementCellUnknown = errors.New("nativemirror: placement cell unavailable")

// ErrGroupBeingDeleted is returned when creation loses the serialization race
// with deletion of the primary repo. Both paths lock the repo_group row, and
// the standing delete_pending_at tombstone remains set until primary teardown
// completes, so a create can never land behind an accepted primary delete.
var ErrGroupBeingDeleted = errors.New("nativemirror: primary repo is being deleted")

// ErrPrimaryHasNativeMirrors is returned when an interactive/admin primary
// delete finds LIVE placement rows (desired_state='active'). Those callers must
// delete the mirrors first; account erasure uses BeginPrimaryErasure to mark
// them and converge in passes.
var ErrPrimaryHasNativeMirrors = errors.New("nativemirror: primary repo still has native mirrors")

// ErrPrimaryNativeMirrorsDraining is returned when an interactive/admin primary
// delete finds only placements already marked for teardown. No user action is
// left: the mirrors ARE deleted, and DELETE on one is idempotent. So the
// caller must report progress, not the conflict above, whose advice cannot be
// followed (COR-1626).
var ErrPrimaryNativeMirrorsDraining = errors.New("nativemirror: primary repo's native mirrors are still draining")

// NativeMirror is one native_mirrors row.
type NativeMirror struct {
	ID            model.RepoID
	RepoGroupID   model.RepoGroupID
	ClusterSlug   string
	Stage         string
	Status        string
	DesiredState  string
	SuspendedAt   *time.Time
	ObjectFormat  string
	URL           string
	DefaultBranch string
	ClaimedBy     string
	ClaimedAt     *time.Time
	// Attempts counts real executions (Claim bumps it) of the CURRENT phase. It
	// resets to 0 on the active→deleted transition (so a teardown's
	// StuckThreshold escalation reflects teardown struggle, not inherited
	// creation retries) and on ResetForRetry (so a repeated POST grants a fresh
	// creation budget under MaxCreationAttempts). The idempotent re-writes of an
	// already-deleted row do NOT reset it.
	Attempts    int64
	LastError   string
	NextRetryAt *time.Time
	// CreationFailedAt marks a PERMANENT creation failure (attempts
	// exhausted or a validation-class error) — distinct from Status, which
	// carries sync health. Set by MarkFailedPermanent, cleared by
	// ResetForRetry; the reconciler does not claim rows carrying it.
	CreationFailedAt *time.Time
	CreatedAt        time.Time
	// AppliedPosition is the placement's applied write watermark: the highest
	// primary write-position ordinal a completed sync provably covers,
	// advanced monotonically by ApplyCompletionStatus from the worker's
	// pre-fetch snapshot (ADR 20260818-native-mirror-resync-sweep). 0 is the
	// pre-watermark state. Comparable only against the same repo's primary
	// position, never across repos or against time.
	AppliedPosition int64
	// CreatedByAccountID is the account that recorded the creation intent. It
	// is empty for rows that predate the column and for operator-CLI creates.
	CreatedByAccountID string
}

// Service is the native_mirrors store.
type Service struct {
	pool               *pgxpool.Pool
	repoDeletionOutbox *repodeletion.Outbox
	registry           RegistryPublisher
	// reads selects the follower-read clause; see postgres.FollowerReads.
	reads postgres.FollowerReads
}

// RegistryPublisher writes a placement's repo_registry row in the caller's transaction.
type RegistryPublisher interface {
	PublishRepoInTx(ctx context.Context, tx pgx.Tx, r model.RepoRegistration) (string, error)
}

type Option func(*Service)

// WithRepoDeletionOutbox atomically preserves projection cleanup when the
// teardown executor removes its final native-mirror intent.
func WithRepoDeletionOutbox(outbox *repodeletion.Outbox) Option {
	return func(s *Service) { s.repoDeletionOutbox = outbox }
}

// WithRegistryPublisher is required wherever the creation executor runs.
func WithRegistryPublisher(registry RegistryPublisher) Option {
	return func(s *Service) { s.registry = registry }
}

func New(pool *pgxpool.Pool, opts ...Option) *Service {
	s := &Service{pool: pool}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// NewForTest is New with follower reads served fresh; see
// postgres.FreshFollowerReadsForTest. A test of the follower clause itself
// adds WithFollowerReadsForTest.
func NewForTest(pool *pgxpool.Pool, opts ...Option) *Service {
	return New(pool, append([]Option{func(s *Service) { s.reads = postgres.FreshFollowerReadsForTest() }}, opts...)...)
}

// WithFollowerReadsForTest restores the production follower-read clause
// under NewForTest.
func WithFollowerReadsForTest() Option {
	return func(s *Service) { s.reads = postgres.FollowerReads{} }
}

// CanRecordPlacementRemoval reports whether this service holds the outbox that
// makes a placement removal durable. A caller that runs its own cleanup before
// ForceReapPlacement must ask FIRST: the service's own guard refuses, but only
// after that cleanup has already happened.
func (s *Service) CanRecordPlacementRemoval() bool { return s.repoDeletionOutbox != nil }

// CanPublishRegistrations reports whether Register can publish. NewExecutor refuses a Service without one.
func (s *Service) CanPublishRegistrations() bool { return s.registry != nil }

// nativeMirrorColumns is the shared SELECT list scanNativeMirror consumes.
const nativeMirrorColumns = `id, repo_group_id, cluster_slug, stage, status, desired_state,
       suspended_at, object_format, url, default_branch,
       COALESCE(claimed_by, ''), claimed_at, attempts, COALESCE(last_error, ''),
       next_retry_at, creation_failed_at, created_at, applied_position,
       COALESCE(created_by_account_id, '')`

type rowScanner interface{ Scan(dest ...any) error }

func scanNativeMirror(s rowScanner) (NativeMirror, error) {
	var r NativeMirror
	// scanTargets (inventory.go) is the single destination list, so the
	// inventory read — which appends a trailing joined column — cannot drift
	// from this one.
	if err := s.Scan(scanTargets(&r)...); err != nil {
		// %w keeps pgx.ErrNoRows reachable for the point-read callers that
		// convert it to ErrNotFound.
		return NativeMirror{}, fmt.Errorf("scan native mirror: %w", err)
	}
	return r, nil
}

// CreateParams are the immutable creation parameters snapshotted from the
// primary at intent time.
type CreateParams struct {
	// ID is the placement id a native-mirror request reserved. The zero value
	// mints a new one. A create that resumes an existing row returns that
	// row's id, which can differ from ID.
	ID            model.RepoID
	RepoGroupID   model.RepoGroupID
	ClusterSlug   string
	ObjectFormat  string
	URL           string
	DefaultBranch string
	// CreatedBy is the account that asked for the placement. The zero value
	// stores NULL, which the operator CLI uses because it acts as no account.
	// A create that resumes an existing row keeps that row's creator.
	CreatedBy model.AccountID

	// AllowRootedExpansion lets a guarded create add a placement to an
	// already-rooted repo (ADR 20260817) instead of returning ErrRepoRooted. The
	// caller sets it only after the placement-acceptance capability check has
	// passed. When set, ExpansionOperationID and Jurisdiction are required: the
	// placement, the revision bump, and the recorded rooted transition intent
	// commit atomically under the group lock.
	AllowRootedExpansion bool
	ExpansionOperationID string
	Jurisdiction         string
}

// Create idempotently records a native-mirror intent, minting the placement ULID.
// Idempotent on (repo_group_id, cluster_slug): a repeated call returns the
// existing row's id with created=false rather than failing — the same
// contract as mirrorrepo.Create, so a retried POST resumes instead of
// conflicting. The caller runs this inside the group-lock transaction via
// CreateTx when serializing against the deletion tombstone.
func (s *Service) Create(ctx context.Context, p CreateParams) (model.RepoID, bool, error) {
	return s.createIn(ctx, s.pool, p)
}

// CreateTx is Create inside a caller-held transaction (the group FOR UPDATE
// lock that serializes intent-writes against the deletion tombstone).
func (s *Service) CreateTx(ctx context.Context, tx pgx.Tx, p CreateParams) (model.RepoID, bool, error) {
	return s.createIn(ctx, tx, p)
}

// CreateWithGroupLock serializes placement creation against primary deletion
// AND against a pending trust publication. The primary-deletion path sets
// repo_group.delete_pending_at while holding the same row lock; a standing
// tombstone rejects creation until teardown removes the group. The
// single-placement trust fence (ADR 20260724-rsl-root-of-trust-mvp) rejects
// creation while an active trust_intents row exists for the primary, so a root
// can never be published against a placement set that expands underneath it. A
// placement that is actually added bumps repo_group.placement_revision; this
// write-side fence is what protects the single-placement invariant. The
// snapshot the intent records is retained for observability and a future
// check-side drift comparison, which the reconciler does not perform today. The
// check, insert, and revision bump commit atomically.
func (s *Service) CreateWithGroupLock(ctx context.Context, p CreateParams) (model.RepoID, bool, error) {
	tx, err := s.pool.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return model.RepoID{}, false, fmt.Errorf("nativemirror: begin guarded create: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // rollback after commit is a no-op

	var (
		deletePendingAt *time.Time
		primaryRepoID   string
	)
	err = tx.QueryRow(ctx,
		`SELECT delete_pending_at, data_primary_repo_id FROM repo_group WHERE id = $1 FOR UPDATE`,
		p.RepoGroupID,
	).Scan(&deletePendingAt, &primaryRepoID)
	if errors.Is(err, pgx.ErrNoRows) {
		return model.RepoID{}, false, ErrNotFound
	}
	if err != nil {
		return model.RepoID{}, false, fmt.Errorf("nativemirror: lock repo group %s: %w", p.RepoGroupID, err)
	}
	if deletePendingAt != nil {
		return model.RepoID{}, false, ErrGroupBeingDeleted
	}

	// Placement-mutation fence: a native group's data_primary_repo_id is its primary
	// repo id. An active trust intent for that primary means a root is in flight,
	// so expansion must wait; a published intent means the repo is already
	// rooted, so expansion is refused unless the caller opts into A->B expansion
	// (CreateParams.AllowRootedExpansion, set after the placement-acceptance
	// capability check, ADR 20260817), in which case the placement and the rooted
	// transition intent commit atomically below. Both checks run
	// under the group lock, so they close the window where a create passed the
	// caller's pre-lock rooted read while the intent was still active but landed
	// here after the reconciler rooted the repo and published the intent (which
	// roots the data plane BEFORE it clears the active intent). Non-native groups
	// (forge != 'entire') never carry trust intents, so a lookup keyed on the
	// stored data_primary_repo_id is harmless there — it simply finds nothing.
	//
	// paused counts as active: it is a report-only, resumable publication (an
	// oversized baseline the operator resolves), and ResumeTrustIntent replays
	// the SAME single-placement publication without rechecking the placement set.
	// If paused did not block, a placement added while paused would let the
	// resumed root publish against an expanded set, breaking the single-placement
	// fence.
	//
	// A restore hold blocks too. The hold retired the published intents, so
	// without this check the repo would read as never rooted and admit a
	// placement that the restored root does not authorize.
	var activeIntents, publishedIntents, activeThisOp, restoreHolds int
	if err := tx.QueryRow(ctx,
		`SELECT
		    count(*) FILTER (WHERE state IN ('pending', 'publishing', 'paused')),
		    count(*) FILTER (WHERE state = 'published'),
		    count(*) FILTER (WHERE state IN ('pending', 'publishing', 'paused') AND operation_id = $2),
		    count(*) FILTER (WHERE state = 'restoring')
		 FROM trust_intents WHERE repo_id = $1`,
		primaryRepoID, p.ExpansionOperationID).Scan(&activeIntents, &publishedIntents, &activeThisOp, &restoreHolds); err != nil {
		return model.RepoID{}, false, fmt.Errorf("nativemirror: check trust intent for group %s: %w", p.RepoGroupID, err)
	}
	if restoreHolds > 0 {
		return model.RepoID{}, false, ErrTrustRestoreHold
	}
	if activeIntents > 0 {
		// An idempotent repeat of THIS expansion must resume the existing
		// placement, not trip the pending fence. The first expansion create records
		// a rooted intent under this deterministic operation id (atomically with the
		// placement), so a retried POST finds that same intent active. Recognizing
		// it (this operation is the SOLE active intent) lets the retry fall through
		// to the created=false resume path below. Any OTHER active intent (a
		// bootstrap, or an expansion for a different target) still blocks: a root is
		// in flight against a set this create would move.
		replay := p.AllowRootedExpansion && p.ExpansionOperationID != "" &&
			activeThisOp == 1 && activeIntents == 1
		if !replay {
			return model.RepoID{}, false, ErrTrustPublicationPending
		}
	}
	if publishedIntents > 0 {
		// A published intent is the durable rooted marker. Adding a placement to a
		// rooted repo is refused unless the caller opts into A->B expansion (ADR
		// 20260817) after the placement-acceptance capability check, in which case
		// the placement and the transition intent commit atomically below.
		if !p.AllowRootedExpansion {
			return model.RepoID{}, false, ErrRepoRooted
		}
		if p.ExpansionOperationID == "" || p.Jurisdiction == "" {
			return model.RepoID{}, false, errors.New("nativemirror: rooted expansion requires an operation id and jurisdiction")
		}
	}

	if err := checkCellAvailability(ctx, tx, p); err != nil {
		return model.RepoID{}, false, err
	}

	id, created, err := s.CreateTx(ctx, tx, p)
	if err != nil {
		return model.RepoID{}, false, err
	}
	// Bump placement_revision only when a row was actually added: a repeated
	// POST that resumes an existing intent (created=false) did not change the
	// placement set, so bumping would spuriously signal membership drift.
	if created {
		if _, err := tx.Exec(ctx,
			`UPDATE repo_group SET placement_revision = placement_revision + 1 WHERE id = $1`,
			p.RepoGroupID); err != nil {
			return model.RepoID{}, false, fmt.Errorf("nativemirror: bump placement revision for group %s: %w", p.RepoGroupID, err)
		}
	}

	// Rooted expansion records the transition intent in the SAME tx so the
	// placement, the revision bump, and the intent commit atomically. The group
	// FOR UPDATE lock is held, and above we verified that the only active intent
	// (if any) is this operation's own idempotent replay, so no other writer can
	// create a conflicting active intent: insertIntentRowTx can only make a fresh
	// insert or an idempotent DO NOTHING replay (same repo_id, operation_id),
	// never errActiveIntentConflict. The intent snapshots the CURRENT placement
	// revision, which already includes this placement's bump.
	//
	// root_profile_version is stamped provisionally as 0 here: the create path
	// does not read the fleet fixture, and the reconciler overwrites the stamp
	// with the version it actually authors at publish time
	// (MarkTrustIntentPublished), which is the value the procedure-7 rotation
	// sweep converges on. A provisional 0 reads as below-target and is harmlessly

package coreapi

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"net/url"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/core/cluster"
	"entire.io/core/model"
	"entire.io/core/nativemirror"
	"entire.io/core/repoadmin"
	"entire.io/core/resource"
	"entire.io/slogutil"
)

// nativeMirrorClusterLookup resolves a native-mirror target or primary
// cluster, and enumerates the registry for the target endpoints.
//
// List returns the stored rows, not api.ClusterInfo. Enumeration needs
// NativeMirrorHosting, and ClusterInfo must not start to carry it: publishing
// that field on the shared topology surface is the approach
// ADR 20260926-scoped-native-mirror-targets rejects. List also returns hidden
// and decommissioned rows, which admitNativeMirrorTarget drops.
type nativeMirrorClusterLookup interface {
	GetBySlugGlobal(ctx context.Context, slug string) (*cluster.Cluster, error)
	List(ctx context.Context) ([]*cluster.Cluster, error)
}

// nativeMirrorIntents records and reads native-mirror lifecycle intent.
type nativeMirrorIntents interface {
	CreateWithGroupLock(ctx context.Context, params nativemirror.CreateParams) (model.RepoID, bool, error)
	ResetForRetry(ctx context.Context, id model.RepoID) error
	Get(ctx context.Context, id model.RepoID) (nativemirror.NativeMirror, error)
	ListByGroup(ctx context.Context, groupID model.RepoGroupID) ([]nativemirror.NativeMirror, error)
	MarkDesiredDeletedReturning(ctx context.Context, groupID model.RepoGroupID, clusterSlug string) (nativemirror.NativeMirror, error)
	PlacementJurisdiction(ctx context.Context, id model.RepoID) (string, bool, error)
}

// nativeMirrorRequestStore stores, reads, and clears the native-mirror regions
// that have no intent yet.
type nativeMirrorRequestStore interface {
	SubmitRequest(ctx context.Context, p nativemirror.SubmitRequestParams) (nativemirror.Request, error)
	PublishRequest(ctx context.Context, req nativemirror.Request, publisher nativemirror.RequestPublisher) error
	ListRequests(ctx context.Context, repoID model.RepoID) ([]nativemirror.Request, error)
	CancelRequest(ctx context.Context, repoID model.RepoID, clusterSlug string, cancelledBy model.AccountID) (nativemirror.Request, bool, error)
}

type nativeMirrorAuditWriter func(context.Context, model.AccountID, string, string, string, map[string]any)

// NativeMirrorService backs the config-gated public native-mirror lifecycle
// surface. It records durable creation/deletion intent; the target
// jurisdiction's row-leased executor performs the asynchronous work.
type NativeMirrorService struct {
	Server *api.Server
	// ManageAuthority selects customer grants or the resolved admin tier. The zero value requires customer grants.
	ManageAuthority authority
	clusters        nativeMirrorClusterLookup
	intents         nativeMirrorIntents
	// requests is nil when native mirroring is not wired.
	requests nativeMirrorRequestStore
	// publisher queues native_mirror_create jobs; nil when no queue is wired.
	publisher   nativemirror.RequestPublisher
	auditWriter nativeMirrorAuditWriter
	// createPlacementOp replaces the project placement resolution in focused
	// handler tests. Production resolves it from the cluster registry through
	// resolveCreatePlacement.
	createPlacementOp func(context.Context, *model.Project, string) (slug, host, jurisdiction string, err error)
}

func newNativeMirrorService(srv *api.Server) *NativeMirrorService {
	service := &NativeMirrorService{Server: srv}
	if intents := srv.NativeMirrors(); intents != nil {
		service.intents = intents
		service.requests = intents
	}
	if caps := srv.JurisdictionCaps(); caps != nil && caps.Cluster != nil {
		service.clusters = caps.Cluster
	}
	service.publisher = srv.NativeMirrorRequestPublisher()
	return service
}

type nativeMirrorPrimary struct {
	repo      *model.Repo
	placement *resource.RepoRegistrationWithURL
}

// CreateNativeMirror stores a request for the target region and queues its
// native_mirror_create job, then answers 202 with the reserved placement id.
// Repeated calls for an active intent return the same placement ULID.
func (s *NativeMirrorService) CreateNativeMirror(ctx context.Context, in *corev1.CreateNativeMirrorInput) (*corev1.CreateNativeMirrorOutput, error) {
	primaryID, authorityPlacement, err := s.ManageAuthority.requireRepoAuthorityPlacement(ctx, s.Server, in.RepoID, repoAuthorityMutation, false, "manage")
	if err != nil {
		return nil, err
	}
	// The queued job loads the primary fresh before it creates the intent, so
	// the request can reuse the placement the authority check read.
	primary, err := s.loadPrimaryWith(ctx, primaryID, authorityPlacement)
	if err != nil {
		return nil, err
	}
	body, err := s.submitRequest(ctx, primaryID, primary, in.Body.ClusterSlug, api.ClaimsFromContext(ctx).AccountID)
	if err != nil {
		return nil, err
	}
	return &corev1.CreateNativeMirrorOutput{Status: http.StatusAccepted, Body: body}, nil
}

// submitRequest runs the creation checks that need only the database, then
// stores a request and queues its native_mirror_create job. The job runs
// createIntent with the placement id reserved here. An existing intent for
// the region is returned instead.
func (s *NativeMirrorService) submitRequest(ctx context.Context, primaryID model.RepoID, primary nativeMirrorPrimary, clusterSlug string, actor model.AccountID) (corev1.NativeMirrorPlacement, error) {
	if err := s.admitCreate(primary); err != nil {
		return corev1.NativeMirrorPlacement{}, err
	}
	if s.clusters == nil || s.intents == nil || s.requests == nil || s.publisher == nil {
		return corev1.NativeMirrorPlacement{}, unavailable("native mirroring is not configured")
	}
	target, err := checkNativeMirrorTarget(ctx, s.clusters, clusterSlug, primary.placement.ClusterSlug, primary.placement.Jurisdiction)
	if err != nil {
		return corev1.NativeMirrorPlacement{}, err
	}
	row, found, err := s.intentForCluster(ctx, primaryID, target.Slug)
	if err != nil {
		return corev1.NativeMirrorPlacement{}, err
	}
	if found {
		if row.DesiredState == nativemirror.DesiredDeleted {
			return corev1.NativeMirrorPlacement{}, conflict("native mirror is being deleted; retry later")
		}
		if row, err = s.reloadIntent(ctx, row.ID, true); err != nil {
			return corev1.NativeMirrorPlacement{}, err
		}
		return nativeMirrorToWire(row), nil
	}
	if err := s.checkCellForRequest(ctx, primaryID, target); err != nil {
		return corev1.NativeMirrorPlacement{}, err
	}
	req, err := s.requests.SubmitRequest(ctx, nativemirror.SubmitRequestParams{
		RepoID:       primaryID,
		ClusterSlug:  target.Slug,
		Jurisdiction: s.Server.Jurisdiction(),
		CreatedBy:    actor,
	})
	if err != nil {
		slogutil.Error(ctx, "native-mirror request submit failed", slog.Any("error", err))
		return corev1.NativeMirrorPlacement{}, unavailable("could not store the native mirror request; retry")
	}
	// The request is stored, so a failed publish is only delayed: the sweep
	// publishes it within a minute.
	if err := s.requests.PublishRequest(ctx, req, s.publisher); err != nil {
		slogutil.Warn(ctx, "native-mirror request publish failed; the sweep retries it",
			slog.String("repo_id", primaryID.String()), slog.String("cluster_slug", target.Slug), slog.Any("error", err))
	}
	return nativeMirrorRequestToWire(req, nativemirror.DesiredActive), nil
}

// checkCellForRequest refuses a request that its job could never fulfil,
// because a live placement already holds the target's cell. A cell that is
// only being vacated is accepted: the job retries until teardown frees it.
// The job repeats the check under the group lock, so a request that races
// another placement still fails there.
func (s *NativeMirrorService) checkCellForRequest(ctx context.Context, primaryID model.RepoID, target *cluster.Cluster) error {
	if target.Cell == "" {
		return cellUnknown()
	}
	registry, err := s.clusters.List(ctx)
	if err != nil {
		slogutil.Error(ctx, "native-mirror request: registry read failed", slog.Any("error", err))
		return unavailable("cluster registry unavailable")
	}
	occupied, err := s.occupiedCells(ctx, primaryID, registry)
	if err != nil {
		return err
	}
	if occupied[target.Cell] == cellHeld {
		return cellOccupied()
	}
	return nil
}

// intentForCluster returns the primary's intent on clusterSlug, if any.
func (s *NativeMirrorService) intentForCluster(ctx context.Context, primaryID model.RepoID, clusterSlug string) (nativemirror.NativeMirror, bool, error) {
	groupID, found, err := s.Server.Resource().GetRepoGroup(ctx, resource.ForgeEntire, primaryID.String())
	if err != nil {
		slogutil.Error(ctx, "native-mirror group lookup failed", slog.Any("error", err))
		return nativemirror.NativeMirror{}, false, internalErr()
	}
	if !found {
		return nativemirror.NativeMirror{}, false, nil
	}
	rows, err := s.intents.ListByGroup(ctx, groupID)
	if err != nil {
		slogutil.Error(ctx, "native-mirror status list failed", slog.Any("error", err))
		return nativemirror.NativeMirror{}, false, internalErr()
	}
	for _, row := range rows {
		if row.ClusterSlug == clusterSlug {
			return row, true, nil
		}
	}
	return nativemirror.NativeMirror{}, false, nil
}

// createIntent runs every creation check and records the placement intent for
// a primary loaded by loadPrimary. actor is who asked for the placement, and
// placementID is the id the request reserved. The native_mirror_create runner
// calls it once per job.
func (s *NativeMirrorService) createIntent(ctx context.Context, primaryID model.RepoID, primary nativeMirrorPrimary, clusterSlug string, actor model.AccountID, placementID model.RepoID) (nativemirror.NativeMirror, error) {
	if err := s.admitCreate(primary); err != nil {
		return nativemirror.NativeMirror{}, err
	}

	caps := s.Server.JurisdictionCaps()
	if caps == nil || s.clusters == nil || s.intents == nil {
		return nativemirror.NativeMirror{}, unavailable("native mirroring is not configured")
	}

	// Rooted-expansion capability fence (ADR 20260724-rsl-root-of-trust-mvp).
	// Once a repo is rooted, adding a placement means publishing that placement
	// into the existing root of trust, which requires the placement-acceptance
	// capability (slice 4). This is the capability check, not a lifecycle state or
	// a path allowlist: it reads the primary's trust state and, if rooted, probes
	// the target for mixed-version safety. It is only the outer gate; the actual
	// A->B expansion create is still fenced deeper in CreateWithGroupLock until a
	// later slice 4 PR wires it (rot-implementation-plan, slice 4, PR 12).
	rootedExpansion, err := s.enforceRootedExpansionCapability(ctx, primaryID, primary.placement.ClusterSlug, clusterSlug)
	if err != nil {
		return nativemirror.NativeMirror{}, err
	}

	// Decision 9a: every target check is read-only and precedes group minting
	// and the native_mirrors insert.
	target, err := checkNativeMirrorTarget(ctx, s.clusters, clusterSlug, primary.placement.ClusterSlug, primary.placement.Jurisdiction)
	if err != nil {
		return nativemirror.NativeMirror{}, err
	}

	home, err := s.clusters.GetBySlugGlobal(ctx, primary.placement.ClusterSlug)
	if err != nil {
		slogutil.Error(ctx, "native-mirror primary cluster lookup failed",
			slog.String("cluster_slug", primary.placement.ClusterSlug), slog.Any("error", err))
		return nativemirror.NativeMirror{}, internalErr()
	}
	primaryURL, err := joinPublicRepoURL(home.PublicURL, primary.placement.URL)
	if err != nil {
		slogutil.Error(ctx, "native-mirror primary URL is unusable",
			slog.String("repo_id", primaryID.String()), slog.Any("error", err))
		return nativemirror.NativeMirror{}, internalErr()
	}

	// Step 0: activate the native group on the primary data plane. Both calls
	// are idempotent, so a retry after either half succeeds converges safely.
	project, err := caps.Resource.GetProject(ctx, primary.placement.OwningProjectID)
	if err != nil {
		slogutil.Error(ctx, "native-mirror primary project lookup failed", slog.Any("error", err))
		return nativemirror.NativeMirror{}, internalErr()
	}
	groupID, err := caps.Resource.GetOrCreateRepoGroup(ctx, resource.EntireForgeRepo{ID: primaryID}, &primaryID,
		model.NativeGroupFullName(project.Name, primary.placement.Name), project.Name, primary.placement.OwningProjectID)
	if err != nil {
		if errors.Is(err, resource.ErrRepoGroupBeingDeleted) {
			return nativemirror.NativeMirror{}, conflict("primary repo is being deleted")
		}
		slogutil.Error(ctx, "native-mirror group activation failed", slog.Any("error", err))
		return nativemirror.NativeMirror{}, internalErr()
	}

	createParams := nativemirror.CreateParams{
		ID:            placementID,
		RepoGroupID:   groupID,
		ClusterSlug:   target.Slug,
		ObjectFormat:  primary.repo.ObjectFormat,
		URL:           primaryURL,
		DefaultBranch: "",
		CreatedBy:     actor,
	}
	if rootedExpansion {
		// The primary is rooted and the destination is capability-verified: record
		// the A->B expansion transition intent atomically with the placement (ADR
		// 20260817). The reconciler then authors a policy that also authorizes the
		// new placement's signer, and the destination becomes rooted only on its
		// own acceptance receipt.
		createParams.AllowRootedExpansion = true
		createParams.ExpansionOperationID = nativemirror.ExpansionOperationID(primaryID, target.Slug)
		createParams.Jurisdiction = primary.placement.Jurisdiction
	}
	createdID, created, err := s.intents.CreateWithGroupLock(ctx, createParams)
	if err != nil {
		switch {
		case errors.Is(err, nativemirror.ErrCellOccupied):
			return nativemirror.NativeMirror{}, cellOccupied()
		case errors.Is(err, nativemirror.ErrCellVacating):
			return nativemirror.NativeMirror{}, withType(problemTypeNativeMirrorCellVacating,
				conflict("target cell is still releasing a removed native mirror; retry later"))
		case errors.Is(err, nativemirror.ErrPlacementCellUnknown):
			return nativemirror.NativeMirror{}, cellUnknown()
		case errors.Is(err, nativemirror.ErrBeingDeleted):
			return nativemirror.NativeMirror{}, conflict("native mirror is being deleted; retry later")
		case errors.Is(err, nativemirror.ErrGroupBeingDeleted):
			return nativemirror.NativeMirror{}, conflict("primary repo is being deleted")
		case errors.Is(err, nativemirror.ErrTrustPublicationPending):
			return nativemirror.NativeMirror{}, conflict("a trust publication is pending for this repo; retry after it settles")
		case errors.Is(err, nativemirror.ErrTrustRestoreHold):
			return nativemirror.NativeMirror{}, conflict("the repo's trust state is being restored; retry after the restore completes")
		case errors.Is(err, nativemirror.ErrRepoRooted):
			// Core's own trust_intents shows this repo rooted (a published intent),
			// but enforceRootedExpansionCapability did not set AllowRootedExpansion,
			// so the guarded create refused. A destination-capability failure is NOT
			// the cause: requireTargetAcceptanceCapability returns its own 412 before
			// the create runs. What remains is a source-side mismatch: the primary's
			// data-plane trust state is not reporting rooted (a transient window
			// during trust convergence, or a bridge that could not answer), so the
			// gate read the repo as not-yet-rooted while Core's control-plane record
			// already is. Report that honestly and let the caller retry once the
			// primary's trust state converges.
			return nativemirror.NativeMirror{}, preconditionFailed("repo is rooted in the control plane, but its primary is not yet reporting rooted from the data plane, so the placement cannot be published into the existing root; retry once the primary's trust state converges")
		default:
			slogutil.Error(ctx, "native-mirror intent create failed", slog.Any("error", err))
			return nativemirror.NativeMirror{}, internalErr()
		}

content.content:
330			}
331		}
332		row, err := s.reloadIntent(ctx, createdID, !created)
333		if err != nil {
334			return nativemirror.NativeMirror{}, err
335		}
336		// Record accepted intent, not completion of the asynchronous placement work.
337		s.auditIntent(ctx, actor, "native_mirror_create_requested", primaryID, row, primary.placement.Jurisdiction, target.Jurisdiction)
338		return row, nil
339	}
