341	// admitCreate refuses a create while admission is paused or the primary is
342	// not active. Admission is separate from lifecycle availability: an operator
343	// can pause new intents while status, delete, and the reconciler continue
344	// driving already-accepted work to a terminal state. Callers check it only
345	// after loadPrimary has redirected foreign primaries, so the authoritative
346	// jurisdiction's admission setting decides whether creation is open.
347	func (s *NativeMirrorService) admitCreate(primary nativeMirrorPrimary) error {
348		if err := requireNativeMirrorCreation(s.Server); err != nil {
349			return err
350		}
351		return requireActiveNativeMirrorPrimary(primary.repo)
352	}
