354	// reloadIntent reads an intent back, first resetting it when reset is set.
355	// Repeating a create is the narrow recovery control for an intent marked
356	// permanently failed; the reset is a no-op for ordinary rows and cannot
357	// resurrect a deletion intent, which is answered with a conflict.
358	func (s *NativeMirrorService) reloadIntent(ctx context.Context, id model.RepoID, reset bool) (nativemirror.NativeMirror, error) {
359		if reset {
360			if err := s.intents.ResetForRetry(ctx, id); err != nil {
361				slogutil.Error(ctx, "native-mirror intent reset failed", slog.Any("error", err))
362				return nativemirror.NativeMirror{}, internalErr()
363			}
364		}
365		row, err := s.intents.Get(ctx, id)
366		if err != nil {
367			slogutil.Error(ctx, "native-mirror intent read-back failed", slog.Any("error", err))
368			return nativemirror.NativeMirror{}, internalErr()
369		}
370		if row.DesiredState == nativemirror.DesiredDeleted {
371			return nativemirror.NativeMirror{}, conflict("native mirror is being deleted; retry later")
372		}
373		return row, nil
374	}
