449	// DeleteNativeMirror marks one placement for asynchronous teardown. The row
450	// remains visible through ListNativeMirrors until the target executor removes
451	// the data plane, registry/authz state, and finally the intent itself.
452	func (s *NativeMirrorService) DeleteNativeMirror(ctx context.Context, in *corev1.DeleteNativeMirrorInput) (*corev1.DeleteNativeMirrorOutput, error) {
453		primaryID, authorityPlacement, err := s.ManageAuthority.requireRepoAuthorityPlacement(ctx, s.Server, in.RepoID, repoAuthorityMutation, false, "manage")
454		if err != nil {
455			return nil, err
456		}
457		// The delete writes through primaryID's group, so the placement only
458		// gates the request and names the audit's jurisdiction.
459		primary, err := s.loadPrimaryWith(ctx, primaryID, authorityPlacement)
460		if err != nil {
461			return nil, err
462		}
463		if s.intents == nil {
464			return nil, unavailable("native mirroring is not configured")
465		}
466		// The read comes before any write, so a failed lookup leaves nothing half
467		// done behind a 500.
468		groupID, found, err := s.Server.Resource().GetRepoGroup(ctx, resource.ForgeEntire, primaryID.String())
469		if err != nil {
470			slogutil.Error(ctx, "native-mirror group lookup failed", slog.Any("error", err))
471			return nil, internalErr()
472		}
473		// Cancel the request before marking the intent. A request job that
474		// creates the intent after this point sees the cancellation and deletes it.
475		var (
476			request      nativemirror.Request
477			requestFound bool
478		)
479		if s.requests != nil {
480			request, requestFound, err = s.requests.CancelRequest(ctx, primaryID, in.ClusterSlug, api.ClaimsFromContext(ctx).AccountID)
481			if err != nil {
482				slogutil.Error(ctx, "native-mirror request cancel failed", slog.Any("error", err))
483				return nil, internalErr()
484			}
485			if requestFound {
486				s.auditRequestCancelled(ctx, primaryID, request, primary.placement.Jurisdiction)
487			}
488		}
489		if !found {
490			return requestDeletedOrNotFound(request, requestFound)
491		}
492		row, err := s.intents.MarkDesiredDeletedReturning(ctx, groupID, in.ClusterSlug)
493		if err != nil {
494			if errors.Is(err, nativemirror.ErrNotFound) {
495				return requestDeletedOrNotFound(request, requestFound)
496			}
497			slogutil.Error(ctx, "native-mirror delete intent failed", slog.Any("error", err))
498			return nil, internalErr()
499		}
500		s.auditIntent(ctx, api.ClaimsFromContext(ctx).AccountID, "native_mirror_delete_requested", primaryID, row, primary.placement.Jurisdiction, s.placementJurisdiction(ctx, row))
501		return &corev1.DeleteNativeMirrorOutput{
502			Status: http.StatusAccepted,
503			Body:   nativeMirrorToWire(row),
504		}, nil
505	}
