579	// trustLifecycleRooted is the data-plane trust lifecycle value that marks a
580	// repo as rooted. Named here so coreapi does not import the data-plane store
581	// for one string; the data plane is the authority for the value.
582	const trustLifecycleRooted = "rooted"
583	
584	// rootedExpansionCapabilityAvailable reports whether the control plane ships the
585	// placement-acceptance capability that publishes a new placement into an
586	// existing root of trust (ADR 20260724-rsl-root-of-trust-mvp, slice 4). It does
587	// now, so expanding a rooted repo is permitted subject to the per-target
588	// mixed-version probe below. It is a function rather than a constant so the
589	// slice-4 seam stays explicit and a rollback that regresses this file re-fences
590	// rooted expansion.
591	func rootedExpansionCapabilityAvailable() bool { return true }
592	
593	// enforceRootedExpansionCapability governs native-mirror creation for a repo
594	// that has already rooted (ADR 20260724-rsl-root-of-trust-mvp). It reads the
595	// primary's trust state; a non-rooted repo expands freely. For a rooted repo it
596	// requires the placement-acceptance capability on both source and destination:
597	// the source is rooted, hence trust-capable by definition, and the destination
598	// is probed for mixed-version safety. A data plane that cannot answer for the
599	// primary (unconfigured bridge) leaves expansion unblocked: the fence is
600	// specific to the rooted state, and a missing trust answer is not evidence of
601	// rooting.
602	//
603	// It returns rootedExpansion=true only when the primary is rooted and the
604	// destination is capability-verified, which is the caller's signal to record the
605	// A->B expansion transition intent as part of the guarded create. A non-rooted
606	// repo returns false: the ordinary single-placement create path applies.
607	func (s *NativeMirrorService) enforceRootedExpansionCapability(ctx context.Context, primaryID model.RepoID, primaryClusterSlug, targetClusterSlug string) (bool, error) {
608		caps := s.Server.JurisdictionCaps()
609		if caps == nil || caps.Bridge == nil {
610			return false, nil
611		}
612		st, err := caps.Bridge.GetTrustState(ctx, primaryID, primaryClusterSlug)
613		if err != nil {
614			if errors.Is(err, repoadmin.ErrNotFound) || errors.Is(err, repoadmin.ErrNotConfigured) {
615				return false, nil
616			}
617			slogutil.Error(ctx, "native-mirror rooted-expansion trust-state read failed",
618				slog.String("repo_id", primaryID.String()), slog.Any("error", err))
619			return false, unavailable("trust state unavailable")
620		}
621		if st.Lifecycle != trustLifecycleRooted {
622			return false, nil
623		}
624		if !rootedExpansionCapabilityAvailable() {
625			return false, preconditionFailed("repo is rooted; this build lacks the placement-acceptance capability required to expand a rooted repo")
626		}
627		if err := s.requireTargetAcceptanceCapability(ctx, primaryID, targetClusterSlug); err != nil {
628			return false, err
629		}
630		return true, nil
631	}
632	
633	// requireTargetAcceptanceCapability refuses expansion of a rooted repo into a
634	// destination cluster whose data plane predates the placement-acceptance RPC
635	// (a mixed-version target), so Core never publishes a placement it cannot get a
636	// destination-issued acceptance for. It probes the target with the read-only
637	// GetTrustState RPC keyed on the primary's id (which the target does not host):
638	// a target that understands the trust RPCs answers NOT_FOUND, while a pre-trust
639	// target surfaces as ErrTrustUnsupported. When the target is not reachable
640	// through this core's bridge (a cross-jurisdiction cluster absent from the local
641	// router) the probe cannot run, and expansion is allowed: a genuinely incapable
642	// destination then surfaces as a perpetually behind placement in the acceptance
643	// matrix (safe and visible), never a falsely rooted one.
644	func (s *NativeMirrorService) requireTargetAcceptanceCapability(ctx context.Context, primaryID model.RepoID, targetClusterSlug string) error {
645		caps := s.Server.JurisdictionCaps()
646		if caps == nil || caps.Bridge == nil {
647			return nil
648		}
649		_, err := caps.Bridge.GetTrustState(ctx, primaryID, targetClusterSlug)
650		switch {
651		case err == nil, errors.Is(err, repoadmin.ErrNotFound):
652			// The target understood the trust RPC (the repo is simply absent there):
653			// it is trust-capable, so it can accept the published placement.
654			return nil
655		case errors.Is(err, repoadmin.ErrTrustUnsupported):
656			return preconditionFailed("target cluster does not advertise the placement-acceptance capability yet (mixed-version); cannot expand a rooted repo into it")
657		case errors.Is(err, repoadmin.ErrUnknownCluster), errors.Is(err, repoadmin.ErrNotConfigured):
658			// The target is not reachable through this core's bridge, so its
659			// capability cannot be probed here. Allow: incapability surfaces safely as
660			// a behind placement rather than blocking a legitimate cross-region expand.
661			return nil
662		default:
663			slogutil.Error(ctx, "native-mirror target acceptance-capability probe failed",
664				slog.String("repo_id", primaryID.String()),
