670	// loadPrimary resolves the local native primary and rejects GitHub-mirror
671	// groups. Foreign primaries redirect only after requireRepoAuthority has
672	// authorized the caller, preserving the repo-topology enumeration guard.
673	func (s *NativeMirrorService) loadPrimary(ctx context.Context, primaryID model.RepoID) (nativeMirrorPrimary, error) {
674		return s.loadPrimaryWith(ctx, primaryID, nil)
