677	// loadPrimaryWith is loadPrimary reusing a placement row the caller already
678	// holds for primaryID, such as the one requireRepoAuthorityPlacement read.
679	// A nil row is read fresh.
680	func (s *NativeMirrorService) loadPrimaryWith(ctx context.Context, primaryID model.RepoID, known *resource.RepoRegistrationWithURL) (nativeMirrorPrimary, error) {
681		repo, _, foreign, err := s.Server.LookupRepoLocalOrGlobal(ctx, primaryID)
682		if err != nil {
683			if errors.Is(err, resource.ErrNotFound) {
684				return nativeMirrorPrimary{}, notFound("repo not found")
685			}
686			slogutil.Error(ctx, "native-mirror primary repo lookup failed", slog.Any("error", err))
687			return nativeMirrorPrimary{}, internalErr()
688		}
689		// A known row comes from RepoAuthorityPlacement, which keeps a stale read
690		// only for a data primary and re-reads every other answer fresh. The fresh
691		// read joins tables that live in the primary region, so outside it the
692		// read takes about 700ms. Intent creation still loads the primary fresh.
693		p := known
694		if p == nil || p.ID != primaryID {
695			placements, err := s.Server.Resource().ListRepoPlacementsByIDs(ctx, []model.RepoID{primaryID})
696			if err != nil {
697				slogutil.Error(ctx, "native-mirror primary registration lookup failed", slog.Any("error", err))
698				return nativeMirrorPrimary{}, internalErr()
699			}
700			if len(placements) != 1 {
701				return nativeMirrorPrimary{}, internalErr()
702			}
703			p = placements[0]
704		}
705		if foreign {
706			if oe := s.Server.JurisdictionRedirect(p.Jurisdiction); oe != nil {
707				return nativeMirrorPrimary{}, mapOpError(oe)
708			}
709		}
710		if err := validateNativeMirrorPrimary(ctx, primaryID, p); err != nil {
711			return nativeMirrorPrimary{}, err
712		}
713		return nativeMirrorPrimary{repo: repo, placement: p}, nil
714	}
