753	func joinPublicRepoURL(base, repoPath string) (string, error) {
754		repoURL, err := url.Parse(repoPath)
755		if err != nil {
756			return "", fmt.Errorf("parse repo URL: %w", err)
757		}
758		if repoURL.IsAbs() {
759			if repoURL.Host == "" || repoURL.Path == "" {
760				return "", errors.New("absolute repo URL requires a host and path")
761			}
762			return repoURL.String(), nil
763		}
764		baseURL, err := url.Parse(strings.TrimSuffix(base, "/") + "/")
765		if err != nil {
766			return "", fmt.Errorf("parse cluster public URL: %w", err)
767		}
768		if !baseURL.IsAbs() || baseURL.Host == "" || repoURL.Path == "" {
769			return "", errors.New("cluster public URL and repo path are required")
770		}
771		repoURL.Path = strings.TrimPrefix(repoURL.Path, "/")
772		return baseURL.ResolveReference(repoURL).String(), nil
773	}
