// admitCreate refuses a create while admission is paused or the primary is
// not active. Admission is separate from lifecycle availability: an operator
// can pause new intents while status, delete, and the reconciler continue
// driving already-accepted work to a terminal state. Callers check it only
// after loadPrimary has redirected foreign primaries, so the authoritative
// jurisdiction's admission setting decides whether creation is open.
func (s *NativeMirrorService) admitCreate(primary nativeMirrorPrimary) error {
	if err := requireNativeMirrorCreation(s.Server); err != nil {
		return err
	}
	return requireActiveNativeMirrorPrimary(primary.repo)
}

// reloadIntent reads an intent back, first resetting it when reset is set.
// Repeating a create is the narrow recovery control for an intent marked
// permanently failed; the reset is a no-op for ordinary rows and cannot
// resurrect a deletion intent, which is answered with a conflict.
func (s *NativeMirrorService) reloadIntent(ctx context.Context, id model.RepoID, reset bool) (nativemirror.NativeMirror, error) {
	if reset {
		if err := s.intents.ResetForRetry(ctx, id); err != nil {
			slogutil.Error(ctx, "native-mirror intent reset failed", slog.Any("error", err))
			return nativemirror.NativeMirror{}, internalErr()
		}
	}
	row, err := s.intents.Get(ctx, id)
	if err != nil {
		slogutil.Error(ctx, "native-mirror intent read-back failed", slog.Any("error", err))
		return nativemirror.NativeMirror{}, internalErr()
	}
	if row.DesiredState == nativemirror.DesiredDeleted {
		return nativemirror.NativeMirror{}, conflict("native mirror is being deleted; retry later")
	}
	return row, nil
}

// checkNativeMirrorTarget refuses a target cluster that cannot hold a native
// mirror of a primary on primaryCluster in primaryJurisdiction.
func checkNativeMirrorTarget(ctx context.Context, clusters nativeMirrorClusterLookup, clusterSlug, primaryCluster, primaryJurisdiction string) (*cluster.Cluster, error) {
	target, err := clusters.GetBySlugGlobal(ctx, clusterSlug)
	if err != nil {
		if errors.Is(err, cluster.ErrNotFound) {
			return nil, badRequest("target cluster not found or decommissioned")
		}
		slogutil.Error(ctx, "native-mirror target lookup failed", slog.Any("error", err))
		return nil, internalErr()
	}
	// One rule, shared with the target endpoints: a rule added here is live on
	// all three surfaces in the same change. Create passes the row it already
	// fetched, so the predicate owns the liveness arms too.
	if reason := admitNativeMirrorTarget(target, nativeMirrorScope{
		PrimaryClusterSlug:  primaryCluster,
		PrimaryJurisdiction: primaryJurisdiction,
	}); reason != nil {
		return nil, badRequest(reason.Error())
	}
	return target, nil
}

// ListNativeMirrors returns every durable placement row, including pending,
// failed, and deleting rows. A native-mirror ULID is inspection-retargeted to
// the primary only after the caller is authorized on that primary.
func (s *NativeMirrorService) ListNativeMirrors(ctx context.Context, in *corev1.ListNativeMirrorsInput) (*corev1.ListNativeMirrorsOutput, error) {
	primaryID, authorityPlacement, err := s.ManageAuthority.requireRepoAuthorityPlacement(ctx, s.Server, in.RepoID, repoAuthorityInspection, false, "pull")
	if err != nil {
		return nil, err
	}
	if _, err := s.loadPrimaryWith(ctx, primaryID, authorityPlacement); err != nil {
		return nil, err
	}
	if s.intents == nil {
		return nil, unavailable("native mirroring is not configured")
	}
	groupID, found, err := s.Server.Resource().GetRepoGroup(ctx, resource.ForgeEntire, primaryID.String())
	if err != nil {
		slogutil.Error(ctx, "native-mirror group lookup failed", slog.Any("error", err))
		return nil, internalErr()
	}
	out := &corev1.ListNativeMirrorsOutput{}
	out.Body.NativeMirrors = []corev1.NativeMirrorPlacement{}
	var rows []nativemirror.NativeMirror
	if found {
		rows, err = s.intents.ListByGroup(ctx, groupID)
		if err != nil {
			slogutil.Error(ctx, "native-mirror status list failed", slog.Any("error", err))
			return nil, internalErr()
		}
	}
	listed := make(map[string]bool, len(rows))
	for _, row := range rows {
		listed[row.ClusterSlug] = true
		out.Body.NativeMirrors = append(out.Body.NativeMirrors, nativeMirrorToWire(row))
	}
	if s.requests == nil {
		return out, nil
	}
	requests, err := s.requests.ListRequests(ctx, primaryID)
	if err != nil {
		slogutil.Error(ctx, "native-mirror request list failed", slog.Any("error", err))
		return nil, internalErr()
	}
	for _, req := range requests {
		if !listed[req.ClusterSlug] {
			out.Body.NativeMirrors = append(out.Body.NativeMirrors, nativeMirrorRequestToWire(req, nativemirror.DesiredActive))
		}
	}
	return out, nil
}

// DeleteNativeMirror marks one placement for asynchronous teardown. The row
// remains visible through ListNativeMirrors until the target executor removes
// the data plane, registry/authz state, and finally the intent itself.
func (s *NativeMirrorService) DeleteNativeMirror(ctx context.Context, in *corev1.DeleteNativeMirrorInput) (*corev1.DeleteNativeMirrorOutput, error) {
	primaryID, authorityPlacement, err := s.ManageAuthority.requireRepoAuthorityPlacement(ctx, s.Server, in.RepoID, repoAuthorityMutation, false, "manage")
	if err != nil {
		return nil, err
	}
	// The delete writes through primaryID's group, so the placement only
	// gates the request and names the audit's jurisdiction.
	primary, err := s.loadPrimaryWith(ctx, primaryID, authorityPlacement)
	if err != nil {
		return nil, err
	}
	if s.intents == nil {
		return nil, unavailable("native mirroring is not configured")
	}
	// The read comes before any write, so a failed lookup leaves nothing half
	// done behind a 500.
	groupID, found, err := s.Server.Resource().GetRepoGroup(ctx, resource.ForgeEntire, primaryID.String())
	if err != nil {
		slogutil.Error(ctx, "native-mirror group lookup failed", slog.Any("error", err))
		return nil, internalErr()
	}
	// Cancel the request before marking the intent. A request job that
	// creates the intent after this point sees the cancellation and deletes it.
	var (
		request      nativemirror.Request
		requestFound bool
	)
	if s.requests != nil {
		request, requestFound, err = s.requests.CancelRequest(ctx, primaryID, in.ClusterSlug, api.ClaimsFromContext(ctx).AccountID)
		if err != nil {
			slogutil.Error(ctx, "native-mirror request cancel failed", slog.Any("error", err))
			return nil, internalErr()
		}
		if requestFound {
			s.auditRequestCancelled(ctx, primaryID, request, primary.placement.Jurisdiction)
		}
	}
	if !found {
		return requestDeletedOrNotFound(request, requestFound)
	}
	row, err := s.intents.MarkDesiredDeletedReturning(ctx, groupID, in.ClusterSlug)
	if err != nil {
		if errors.Is(err, nativemirror.ErrNotFound) {
			return requestDeletedOrNotFound(request, requestFound)
		}
		slogutil.Error(ctx, "native-mirror delete intent failed", slog.Any("error", err))
		return nil, internalErr()
	}
	s.auditIntent(ctx, api.ClaimsFromContext(ctx).AccountID, "native_mirror_delete_requested", primaryID, row, primary.placement.Jurisdiction, s.placementJurisdiction(ctx, row))
	return &corev1.DeleteNativeMirrorOutput{
		Status: http.StatusAccepted,
		Body:   nativeMirrorToWire(row),
	}, nil
}

// auditRequestCancelled records a user removing a region that repo create
// asked for, before its intent existed.
func (s *NativeMirrorService) auditRequestCancelled(ctx context.Context, primaryID model.RepoID, request nativemirror.Request, primaryJurisdiction string) {
	metadata := map[string]any{"cluster_slug": request.ClusterSlug}
	if primaryJurisdiction != "" {
		metadata["primary_jurisdiction"] = primaryJurisdiction
	}
	if request.CreatedByAccountID != "" {
		metadata["created_by_account_id"] = request.CreatedByAccountID
	}
	s.writeAudit(ctx, api.ClaimsFromContext(ctx).AccountID, "native_mirror_request_cancelled", primaryID, metadata)
}

// requestDeletedOrNotFound answers a delete that found no intent. A removed
// request is an accepted delete of a region that had no placement yet.
func requestDeletedOrNotFound(request nativemirror.Request, found bool) (*corev1.DeleteNativeMirrorOutput, error) {
	if !found {
		return nil, notFound("native mirror not found")
	}
	return &corev1.DeleteNativeMirrorOutput{
		Status: http.StatusAccepted,
		Body:   nativeMirrorRequestToWire(request, nativemirror.DesiredDeleted),
	}, nil
}

// auditIntent records who asked for a placement and where its copy goes. The
// target jurisdiction answers "whose infrastructure held this source". The
// creator is repeated on the delete event because teardown deletes the row
// that holds it. An unknown value is omitted, not recorded as empty.
func (s *NativeMirrorService) auditIntent(ctx context.Context, actor model.AccountID, event string, primaryID model.RepoID, row nativemirror.NativeMirror, primaryJurisdiction, targetJurisdiction string) {
	metadata := map[string]any{
		"placement_id":  row.ID.String(),
		"cluster_slug":  row.ClusterSlug,
		"repo_group_id": row.RepoGroupID.String(),
	}
	if primaryJurisdiction != "" {
		metadata["primary_jurisdiction"] = primaryJurisdiction
	}
	if targetJurisdiction != "" {
		metadata["target_jurisdiction"] = targetJurisdiction
	}
	if row.CreatedByAccountID != "" {
		metadata["created_by_account_id"] = row.CreatedByAccountID
	}
	s.writeAudit(ctx, actor, event, primaryID, metadata)
}

// writeAudit records a domain audit event on the primary repo, through
// auditWriter when a test set one.
func (s *NativeMirrorService) writeAudit(ctx context.Context, actor model.AccountID, event string, primaryID model.RepoID, metadata map[string]any) {
	if s.auditWriter != nil {
		s.auditWriter(ctx, actor, event, "repo", primaryID.String(), metadata)
		return
	}
	s.Server.DomainAuditLog(ctx, actor, event, "repo", primaryID.String(), metadata)
}

// placementJurisdiction resolves a placement's jurisdiction for the delete
// audit event. It reads decommissioned clusters too, because a decommissioned
// cell is a likely reason to remove a mirror. The lookup is best-effort: the
// delete intent is already durable, so a failed read must not fail it.
func (s *NativeMirrorService) placementJurisdiction(ctx context.Context, row nativemirror.NativeMirror) string {
	jurisdiction, found, err := s.intents.PlacementJurisdiction(ctx, row.ID)
	if err != nil || !found {
		slogutil.Warn(ctx, "native-mirror delete audit: placement jurisdiction unresolved",
			slog.String("placement_id", row.ID.String()), slog.String("cluster_slug", row.ClusterSlug),
			slog.Bool("found", found), slog.Any("error", err))
		return ""
	}
	return jurisdiction
}

// trustLifecycleRooted is the data-plane trust lifecycle value that marks a
// repo as rooted. Named here so coreapi does not import the data-plane store
// for one string; the data plane is the authority for the value.
const trustLifecycleRooted = "rooted"

// rootedExpansionCapabilityAvailable reports whether the control plane ships the
// placement-acceptance capability that publishes a new placement into an
// existing root of trust (ADR 20260724-rsl-root-of-trust-mvp, slice 4). It does
// now, so expanding a rooted repo is permitted subject to the per-target
// mixed-version probe below. It is a function rather than a constant so the
// slice-4 seam stays explicit and a rollback that regresses this file re-fences
// rooted expansion.
func rootedExpansionCapabilityAvailable() bool { return true }

// enforceRootedExpansionCapability governs native-mirror creation for a repo
// that has already rooted (ADR 20260724-rsl-root-of-trust-mvp). It reads the
// primary's trust state; a non-rooted repo expands freely. For a rooted repo it
// requires the placement-acceptance capability on both source and destination:
// the source is rooted, hence trust-capable by definition, and the destination
// is probed for mixed-version safety. A data plane that cannot answer for the
// primary (unconfigured bridge) leaves expansion unblocked: the fence is
// specific to the rooted state, and a missing trust answer is not evidence of
// rooting.
//
// It returns rootedExpansion=true only when the primary is rooted and the
// destination is capability-verified, which is the caller's signal to record the
// A->B expansion transition intent as part of the guarded create. A non-rooted
// repo returns false: the ordinary single-placement create path applies.
func (s *NativeMirrorService) enforceRootedExpansionCapability(ctx context.Context, primaryID model.RepoID, primaryClusterSlug, targetClusterSlug string) (bool, error) {
	caps := s.Server.JurisdictionCaps()
	if caps == nil || caps.Bridge == nil {
		return false, nil
	}
	st, err := caps.Bridge.GetTrustState(ctx, primaryID, primaryClusterSlug)
	if err != nil {
		if errors.Is(err, repoadmin.ErrNotFound) || errors.Is(err, repoadmin.ErrNotConfigured) {
			return false, nil
		}
		slogutil.Error(ctx, "native-mirror rooted-expansion trust-state read failed",
			slog.String("repo_id", primaryID.String()), slog.Any("error", err))
		return false, unavailable("trust state unavailable")
	}
	if st.Lifecycle != trustLifecycleRooted {
		return false, nil
	}
	if !rootedExpansionCapabilityAvailable() {
		return false, preconditionFailed("repo is rooted; this build lacks the placement-acceptance capability required to expand a rooted repo")
	}
	if err := s.requireTargetAcceptanceCapability(ctx, primaryID, targetClusterSlug); err != nil {
		return false, err
	}
	return true, nil
}

// requireTargetAcceptanceCapability refuses expansion of a rooted repo into a
// destination cluster whose data plane predates the placement-acceptance RPC
// (a mixed-version target), so Core never publishes a placement it cannot get a
// destination-issued acceptance for. It probes the target with the read-only
// GetTrustState RPC keyed on the primary's id (which the target does not host):
// a target that understands the trust RPCs answers NOT_FOUND, while a pre-trust
// target surfaces as ErrTrustUnsupported. When the target is not reachable
// through this core's bridge (a cross-jurisdiction cluster absent from the local
// router) the probe cannot run, and expansion is allowed: a genuinely incapable
// destination then surfaces as a perpetually behind placement in the acceptance
// matrix (safe and visible), never a falsely rooted one.
func (s *NativeMirrorService) requireTargetAcceptanceCapability(ctx context.Context, primaryID model.RepoID, targetClusterSlug string) error {
	caps := s.Server.JurisdictionCaps()
	if caps == nil || caps.Bridge == nil {
		return nil
	}
	_, err := caps.Bridge.GetTrustState(ctx, primaryID, targetClusterSlug)
	switch {
	case err == nil, errors.Is(err, repoadmin.ErrNotFound):
		// The target understood the trust RPC (the repo is simply absent there):
		// it is trust-capable, so it can accept the published placement.
		return nil
	case errors.Is(err, repoadmin.ErrTrustUnsupported):
		return preconditionFailed("target cluster does not advertise the placement-acceptance capability yet (mixed-version); cannot expand a rooted repo into it")
	case errors.Is(err, repoadmin.ErrUnknownCluster), errors.Is(err, repoadmin.ErrNotConfigured):
		// The target is not reachable through this core's bridge, so its
		// capability cannot be probed here. Allow: incapability surfaces safely as
		// a behind placement rather than blocking a legitimate cross-region expand.
		return nil
	default:
		slogutil.Error(ctx, "native-mirror target acceptance-capability probe failed",
			slog.String("repo_id", primaryID.String()),
			slog.String("target_cluster_slug", targetClusterSlug), slog.Any("error", err))
		return unavailable("target trust capability unavailable")
	}
}

// loadPrimary resolves the local native primary and rejects GitHub-mirror
// groups. Foreign primaries redirect only after requireRepoAuthority has
// authorized the caller, preserving the repo-topology enumeration guard.
func (s *NativeMirrorService) loadPrimary(ctx context.Context, primaryID model.RepoID) (nativeMirrorPrimary, error) {
	return s.loadPrimaryWith(ctx, primaryID, nil)
}

// loadPrimaryWith is loadPrimary reusing a placement row the caller already
// holds for primaryID, such as the one requireRepoAuthorityPlacement read.
// A nil row is read fresh.
func (s *NativeMirrorService) loadPrimaryWith(ctx context.Context, primaryID model.RepoID, known *resource.RepoRegistrationWithURL) (nativeMirrorPrimary, error) {
	repo, _, foreign, err := s.Server.LookupRepoLocalOrGlobal(ctx, primaryID)
	if err != nil {
		if errors.Is(err, resource.ErrNotFound) {
			return nativeMirrorPrimary{}, notFound("repo not found")
		}
		slogutil.Error(ctx, "native-mirror primary repo lookup failed", slog.Any("error", err))
		return nativeMirrorPrimary{}, internalErr()
	}
	// A known row comes from RepoAuthorityPlacement, which keeps a stale read
	// only for a data primary and re-reads every other answer fresh. The fresh
	// read joins tables that live in the primary region, so outside it the
	// read takes about 700ms. Intent creation still loads the primary fresh.
	p := known
	if p == nil || p.ID != primaryID {
		placements, err := s.Server.Resource().ListRepoPlacementsByIDs(ctx, []model.RepoID{primaryID})
		if err != nil {
			slogutil.Error(ctx, "native-mirror primary registration lookup failed", slog.Any("error", err))
			return nativeMirrorPrimary{}, internalErr()
		}
		if len(placements) != 1 {
			return nativeMirrorPrimary{}, internalErr()
		}
		p = placements[0]
	}
	if foreign {
		if oe := s.Server.JurisdictionRedirect(p.Jurisdiction); oe != nil {
			return nativeMirrorPrimary{}, mapOpError(oe)
		}
	}
	if err := validateNativeMirrorPrimary(ctx, primaryID, p); err != nil {
		return nativeMirrorPrimary{}, err
	}
	return nativeMirrorPrimary{repo: repo, placement: p}, nil
}

func nativeMirrorToWire(row nativemirror.NativeMirror) corev1.NativeMirrorPlacement {
	return corev1.NativeMirrorPlacement{
		PlacementID:      row.ID.String(),
		ClusterSlug:      row.ClusterSlug,
		Stage:            row.Stage,
		Status:           row.Status,
		DesiredState:     row.DesiredState,
		Attempts:         row.Attempts,
		LastError:        row.LastError,
		NextRetryAt:      row.NextRetryAt,
		CreationFailedAt: row.CreationFailedAt,
		CreatedAt:        row.CreatedAt,
	}
}

// nativeMirrorRequestToWire shows a region that repo create asked for and
// that has no intent yet. It has no placement ID until the intent exists.
func nativeMirrorRequestToWire(req nativemirror.Request, desiredState string) corev1.NativeMirrorPlacement {
	out := corev1.NativeMirrorPlacement{
		PlacementID:      req.PlacementID.String(),
		ClusterSlug:      req.ClusterSlug,
		Stage:            nativemirror.StagePending,
		Status:           nativemirror.StatusProcessing,
		DesiredState:     desiredState,
		Attempts:         req.Attempts,
		LastError:        req.LastError,
		CreationFailedAt: req.FailedAt,
		CreatedAt:        req.CreatedAt,
	}
	if req.FailedAt != nil {
		out.Status = nativemirror.StatusFailed
		out.FailureCode = req.FailureCode
		out.FailureMessage = req.FailureMessage
	}
	return out
}

func joinPublicRepoURL(base, repoPath string) (string, error) {
	repoURL, err := url.Parse(repoPath)
	if err != nil {
		return "", fmt.Errorf("parse repo URL: %w", err)
	}
	if repoURL.IsAbs() {
		if repoURL.Host == "" || repoURL.Path == "" {
			return "", errors.New("absolute repo URL requires a host and path")
		}
		return repoURL.String(), nil
	}
	baseURL, err := url.Parse(strings.TrimSuffix(base, "/") + "/")
	if err != nil {
		return "", fmt.Errorf("parse cluster public URL: %w", err)
	}
	if !baseURL.IsAbs() || baseURL.Host == "" || repoURL.Path == "" {
		return "", errors.New("cluster public URL and repo path are required")
	}
	repoURL.Path = strings.TrimPrefix(repoURL.Path, "/")
	return baseURL.ResolveReference(repoURL).String(), nil
}

func registerNativeMirrorOperations(api huma.API, svc *NativeMirrorService) {
	tags := []string{"native-mirrors"}
	huma.Register(api, huma.Operation{
		OperationID:   "createNativeMirror",
		Method:        http.MethodPost,
		Path:          "/repos/{repoId}/native-mirrors",
		Summary:       "Create a native-mirror placement",
		DefaultStatus: http.StatusAccepted,
		Tags:          tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusNotFound, http.StatusConflict, http.StatusPreconditionFailed, http.StatusMisdirectedRequest, http.StatusServiceUnavailable),
	}, svc.CreateNativeMirror)
	huma.Register(api, huma.Operation{
		OperationID: "listNativeMirrors",
		Method:      http.MethodGet,
		Path:        "/repos/{repoId}/native-mirrors",
		Summary:     "List native-mirror placement status",
		Tags:        tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusNotFound, http.StatusMisdirectedRequest, http.StatusServiceUnavailable),
	}, svc.ListNativeMirrors)
	huma.Register(api, huma.Operation{
		OperationID:   "deleteNativeMirror",
		Method:        http.MethodDelete,
		Path:          "/repos/{repoId}/native-mirrors/{clusterSlug}",
		Summary:       "Delete a native-mirror placement",
		DefaultStatus: http.StatusAccepted,
		Tags:          tags, Security: securityAny,
		Errors: append(commonErrors, http.StatusNotFound, http.StatusConflict, http.StatusMisdirectedRequest, http.StatusServiceUnavailable),
	}, svc.DeleteNativeMirror)
}

