package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"

	"entire.io/core/model"
)

// RequestStatus is the processing state of a native-mirror request.
type RequestStatus string

const (
	RequestPending    RequestStatus = "pending"
	RequestProcessing RequestStatus = "processing"
	RequestFailed     RequestStatus = "failed"
)

// RequestPublishHold is how long a publish holds off the sweep. It exceeds a
// job's whole JetStream retry chain, so the sweep republishes only a lost job.
const RequestPublishHold = 30 * time.Minute

// Request is one native_mirror_requests row: a native-mirror region that has
// no native_mirrors intent yet.
type Request struct {
	RepoID             model.RepoID
	ClusterSlug        string
	PlacementID        model.RepoID
	Jurisdiction       string
	CreatedByAccountID string
	Status             RequestStatus
	Attempts           int64
	LastError          string
	FailureCode        string
	FailureMessage     string
	NextPublishAt      time.Time
	FailedAt           *time.Time
	// CancelledAt is set when a user removed the region before its intent
	// existed. A job that was already running reads it back when it finishes,
	// and deletes the intent it just created.
	CancelledAt *time.Time
	// CancelledByAccountID is the account that cancelled the request, or
	// empty.
	CancelledByAccountID string
	// CancelSettledAt is set once the job of a cancelled request has removed
	// any intent stored under PlacementID.
	CancelSettledAt *time.Time
	CreatedAt       time.Time
}

// RequestPublisher queues a native_mirror_create job for a request and returns
// nil once the broker has accepted it.
type RequestPublisher interface {
	PublishRequest(ctx context.Context, request Request) error
}

// SubmitRequestParams are the values a POST /native-mirrors stores.
type SubmitRequestParams struct {
	RepoID       model.RepoID
	ClusterSlug  string
	Jurisdiction string
	CreatedBy    model.AccountID
}

const requestColumns = `repo_id, cluster_slug, placement_id, jurisdiction, COALESCE(created_by_account_id, ''),
       status, attempts, COALESCE(last_error, ''), COALESCE(failure_code, ''), COALESCE(failure_message, ''),
       next_publish_at, failed_at, cancelled_at, COALESCE(cancelled_by_account_id, ''), cancel_settled_at, created_at`

func scanRequest(s rowScanner) (Request, error) {
	var r Request
	var repoID, placementID, status string
	if err := s.Scan(&repoID, &r.ClusterSlug, &placementID, &r.Jurisdiction, &r.CreatedByAccountID,
		&status, &r.Attempts, &r.LastError, &r.FailureCode, &r.FailureMessage,
		&r.NextPublishAt, &r.FailedAt, &r.CancelledAt, &r.CancelledByAccountID, &r.CancelSettledAt, &r.CreatedAt); err != nil {
		return Request{}, fmt.Errorf("scan native mirror request: %w", err)
	}
	var err error
	if r.RepoID, err = model.ParseRepoID(repoID); err != nil {
		return Request{}, fmt.Errorf("scan native mirror request: %w", err)
	}
	if r.PlacementID, err = model.ParseRepoID(placementID); err != nil {
		return Request{}, fmt.Errorf("scan native mirror request placement: %w", err)
	}
	r.Status = RequestStatus(status)
	return r, nil
}

type requestQuerier interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

func queryRequests(ctx context.Context, q requestQuerier, sql string, args ...any) ([]Request, error) {
	rows, err := q.Query(ctx, sql, args...)
	if err != nil {
		return nil, fmt.Errorf("native mirror requests: %w", err)
	}
	defer rows.Close()
	var out []Request
	for rows.Next() {
		r, err := scanRequest(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("native mirror requests: %w", err)
	}
	return out, nil
}

// firstRequest returns the only row of a single-row statement.
func firstRequest(ctx context.Context, q requestQuerier, sql string, args ...any) (Request, bool, error) {
	rows, err := queryRequests(ctx, q, sql, args...)
	if err != nil || len(rows) == 0 {
		return Request{}, false, err
	}
	return rows[0], true, nil
}

// RecordRequests stores the native-mirror regions a repo create asked for and
// returns their rows, each with its reserved placement id. jurisdiction is
// the primary's, whose regional core runs the jobs. The repo is not active
// yet, so nothing is published: PublishRepoRequests does that once it is, and
// the sweep publishes after publishAfter if that never happens. A repeated
// slug keeps its row.
func (s *Service) RecordRequests(ctx context.Context, repoID model.RepoID, jurisdiction string, createdBy model.AccountID, clusterSlugs []string, publishAfter time.Duration) ([]Request, error) {
	var creator *string
	if createdBy != "" {
		v := createdBy.String()
		creator = &v
	}
	placementIDs := make([]string, len(clusterSlugs))
	for i := range clusterSlugs {
		placementIDs[i] = model.NewRepoID().String()
	}
	if _, err := s.pool.Exec(ctx,
		`INSERT INTO native_mirror_requests
		     (repo_id, cluster_slug, placement_id, jurisdiction, created_by_account_id, next_publish_at)
		 SELECT $1, slug, pid, $2, $3, now() + ($6::INT8 * INTERVAL '1 microsecond')
		 FROM unnest($4::TEXT[], $5::TEXT[]) AS r(slug, pid)
		 ON CONFLICT (repo_id, cluster_slug) DO NOTHING`,
		repoID.String(), jurisdiction, creator, clusterSlugs, placementIDs, publishAfter.Microseconds()); err != nil {
		return nil, fmt.Errorf("nativemirror: record requests for %s: %w", repoID, err)
	}
	requests, err := queryRequests(ctx, s.pool,
		`SELECT `+requestColumns+` FROM native_mirror_requests
		 WHERE repo_id = $1 AND cluster_slug = ANY($2::TEXT[]) ORDER BY cluster_slug`,
		repoID.String(), clusterSlugs)
	if err != nil {
		return nil, fmt.Errorf("nativemirror: read recorded requests for %s: %w", repoID, err)
	}
	return requests, nil
}

// SubmitRequest stores a request for one region and returns it. A failed or
// cancelled request for the same region is reset; this is how a user retries.
// A live request keeps its placement id. The caller publishes the job with
// PublishRequest after this returns, so a consumer never sees the job before
// the row is committed.
func (s *Service) SubmitRequest(ctx context.Context, p SubmitRequestParams) (Request, error) {
	var creator *string
	if p.CreatedBy != "" {
		v := p.CreatedBy.String()
		creator = &v
	}
	// A row whose job is running stays processing. Its outcome, not this
	// submit, decides what happens next.
	req, found, err := firstRequest(ctx, s.pool,
		`INSERT INTO native_mirror_requests
		     (repo_id, cluster_slug, placement_id, jurisdiction, created_by_account_id, next_publish_at)
		 VALUES ($1, $2, $3, $4, $5, now() + ($6::INT8 * INTERVAL '1 microsecond'))
		 ON CONFLICT (repo_id, cluster_slug) DO UPDATE SET
		     status = CASE
		         WHEN native_mirror_requests.status = 'processing' AND native_mirror_requests.cancelled_at IS NULL
		         THEN 'processing' ELSE 'pending' END,
		     created_at = CASE
		         WHEN native_mirror_requests.failed_at IS NOT NULL OR native_mirror_requests.cancelled_at IS NOT NULL
		         THEN now() ELSE native_mirror_requests.created_at END,
		     created_by_account_id = CASE
		         WHEN native_mirror_requests.failed_at IS NOT NULL OR native_mirror_requests.cancelled_at IS NOT NULL
		         THEN excluded.created_by_account_id ELSE native_mirror_requests.created_by_account_id END,
		     failed_at = NULL,
		     cancelled_at = NULL,
		     cancelled_by_account_id = NULL,
		     cancel_settled_at = NULL,
		     failure_code = NULL,
		     failure_message = NULL,
		     next_publish_at = excluded.next_publish_at
		 RETURNING `+requestColumns,
		p.RepoID.String(), p.ClusterSlug, model.NewRepoID().String(), p.Jurisdiction, creator, RequestPublishHold.Microseconds())
	if err == nil && !found {
		err = errors.New("upsert returned no row")
	}
	if err != nil {
		return Request{}, fmt.Errorf("nativemirror: submit request %s/%s: %w", p.RepoID, p.ClusterSlug, err)
	}
	return req, nil
}

// PublishRequest publishes the job of a request that SubmitRequest stored.
// When the publish fails, the request is rescheduled so the sweep publishes
// it within a minute, and the error is returned for logging.
func (s *Service) PublishRequest(ctx context.Context, req Request, publisher RequestPublisher) error {
	return s.publishClaimed(ctx, []Request{req}, publisher)
}

// PublishRepoRequests publishes the job of each pending request of repoID.
// Repo create calls it once the repo is active. A request whose publish fails
// is left for the sweep, and the first such error is returned.
func (s *Service) PublishRepoRequests(ctx context.Context, repoID model.RepoID, publisher RequestPublisher) error {
	claimed, err := queryRequests(ctx, s.pool,
		`UPDATE native_mirror_requests
		 SET next_publish_at = now() + ($2::INT8 * INTERVAL '1 microsecond')
		 WHERE repo_id = $1 AND status = 'pending' AND failed_at IS NULL AND cancelled_at IS NULL
		 RETURNING `+requestColumns,
		repoID.String(), RequestPublishHold.Microseconds())
	if err != nil {
		return fmt.Errorf("nativemirror: claim requests of %s to publish: %w", repoID, err)
	}
	return s.publishClaimed(ctx, claimed, publisher)
}

// PublishDueRequests publishes up to limit requests in jurisdiction whose
// publish is due: a lost job, a wait that ended, or a repo the provisioning
// reconciler activated. It returns how many it published.
func (s *Service) PublishDueRequests(ctx context.Context, jurisdiction string, limit int, publisher RequestPublisher) (int, error) {
	claimed, err := s.claimDue(ctx, jurisdiction, limit, false, RequestPublishHold)
	if err != nil {
		return 0, fmt.Errorf("nativemirror: claim due requests in %s: %w", jurisdiction, err)
	}
	return len(claimed), s.publishClaimed(ctx, claimed, publisher)
}

// claimDue claims up to limit open requests in jurisdiction whose
// next_publish_at has passed, either failed ones or the rest, and pushes their
// next_publish_at forward by hold so no other pod claims them meanwhile. SKIP
// LOCKED gives concurrent sweeps disjoint batches, as in created_outbox.go.
func (s *Service) claimDue(ctx context.Context, jurisdiction string, limit int, failed bool, hold time.Duration) ([]Request, error) {
	failedCond := "failed_at IS NULL AND cancel_settled_at IS NULL"
	if failed {
		failedCond = "failed_at IS NOT NULL AND cancelled_at IS NULL"
	}
	claimed, err := queryRequests(ctx, s.pool,
		`UPDATE native_mirror_requests
		 SET next_publish_at = now() + ($3::INT8 * INTERVAL '1 microsecond')
		 WHERE (repo_id, cluster_slug) IN (
		     SELECT repo_id, cluster_slug FROM native_mirror_requests
		     WHERE jurisdiction = $1 AND `+failedCond+` AND next_publish_at <= now()
		     ORDER BY next_publish_at LIMIT $2
		     FOR UPDATE SKIP LOCKED)
		   AND `+failedCond+` AND next_publish_at <= now()
		 RETURNING `+requestColumns,
		jurisdiction, limit, hold.Microseconds())
	return claimed, err
}

// requestPublishRetry is when the sweep tries again after a failed publish.
const requestPublishRetry = time.Minute

// publishClaimed tries every claimed request, so one failure does not hold
// back the rest for a whole RequestPublishHold.
func (s *Service) publishClaimed(ctx context.Context, claimed []Request, publisher RequestPublisher) error {
	var errs []error
	for _, req := range claimed {
		err := publisher.PublishRequest(ctx, req)
		if err == nil {
			continue
		}
		errs = append(errs, fmt.Errorf("nativemirror: publish request %s/%s: %w", req.RepoID, req.ClusterSlug, err))
		// Match the publish time this claim set. A resubmit or a wait since the
		// claim set a new one, and its hold must stand.
		if _, err := s.pool.Exec(ctx,
			`UPDATE native_mirror_requests SET next_publish_at = now() + ($3::INT8 * INTERVAL '1 microsecond')
			 WHERE repo_id = $1 AND cluster_slug = $2 AND placement_id = $4 AND next_publish_at = $5`,
			req.RepoID.String(), req.ClusterSlug, requestPublishRetry.Microseconds(), req.PlacementID.String(), req.NextPublishAt); err != nil {
			errs = append(errs, fmt.Errorf("nativemirror: reschedule request %s/%s: %w", req.RepoID, req.ClusterSlug, err))
		}
	}
	return errors.Join(errs...)
}

// StartRequestAttempt marks a live request as processing and returns it with
// its new attempt number. A cancelled request whose removal is not settled
// still starts, so its job can remove the intent. started is false when the
// request is failed, settled, or gone, so the job has nothing to do.
func (s *Service) StartRequestAttempt(ctx context.Context, repoID model.RepoID, clusterSlug string) (Request, bool, error) {
	req, found, err := firstRequest(ctx, s.pool,
		`UPDATE native_mirror_requests SET status = 'processing', attempts = attempts + 1
		 WHERE repo_id = $1 AND cluster_slug = $2 AND failed_at IS NULL AND cancel_settled_at IS NULL
		 RETURNING `+requestColumns,
		repoID.String(), clusterSlug)
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: start request attempt %s/%s: %w", repoID, clusterSlug, err)
	}
	return req, found, nil
}

// sqlFragment is SQL that fencedUpdate splices into a statement. Only an
// untyped string constant converts to it implicitly, so a string variable
// holding user data does not compile as one.
type sqlFragment string

// fencedUpdate applies set to the request only while attempt is still its
// current processing attempt. It reports whether it did. Every value goes in
// args as a bind parameter from $4 on.
func (s *Service) fencedUpdate(ctx context.Context, op string, req Request, set sqlFragment, args ...any) (bool, error) {
	all := append([]any{req.RepoID.String(), req.ClusterSlug, req.Attempts}, args...)
	tag, err := s.pool.Exec(ctx,
		`UPDATE native_mirror_requests SET `+string(set)+`
		 WHERE repo_id = $1 AND cluster_slug = $2 AND attempts = $3 AND status = 'processing'
		   AND failed_at IS NULL AND cancel_settled_at IS NULL`, all...)
	if err != nil {
		return false, fmt.Errorf("nativemirror: %s %s/%s: %w", op, req.RepoID, req.ClusterSlug, err)
	}
	return tag.RowsAffected() == 1, nil
}

// FinishRequest deletes the request attempt req ran, once its intent exists,
// unless the request was cancelled. The delete is fenced on req's attempt and
// placement id, so an attempt that finishes late never removes a newer
// request for the same region; that request's own job finishes it. cancelled
// is true when req's request is still there and cancelled, so the caller must
// remove the intent and call SettleCancelledRequest.
func (s *Service) FinishRequest(ctx context.Context, req Request) (Request, bool, error) {
	tag, err := s.pool.Exec(ctx,
		`DELETE FROM native_mirror_requests
		 WHERE repo_id = $1 AND cluster_slug = $2 AND placement_id = $3 AND attempts = $4 AND cancelled_at IS NULL`,
		req.RepoID.String(), req.ClusterSlug, req.PlacementID.String(), req.Attempts)
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: finish request %s/%s: %w", req.RepoID, req.ClusterSlug, err)
	}
	if tag.RowsAffected() == 1 {
		return Request{}, false, nil
	}
	current, found, err := firstRequest(ctx, s.pool,
		`SELECT `+requestColumns+` FROM native_mirror_requests WHERE repo_id = $1 AND cluster_slug = $2`,
		req.RepoID.String(), req.ClusterSlug)
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: read finished request %s/%s: %w", req.RepoID, req.ClusterSlug, err)
	}
	return current, found && current.CancelledAt != nil && current.PlacementID == req.PlacementID, nil
}

// SettleCancelledRequest records that the job of a cancelled request removed
// any intent it created, so the request is no longer run and can be purged.
// It reports false when the request is no longer cancelled, because a user
// asked for the region again.
//
// status goes back to pending only to say no job holds the row; there is no
// settled status. cancel_settled_at alone keeps the row from running again:
// claimDue, StartRequestAttempt and the fenced updates all require it to be
// NULL, and PublishRepoRequests requires cancelled_at to be NULL.
func (s *Service) SettleCancelledRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (bool, error) {
	tag, err := s.pool.Exec(ctx,
		`UPDATE native_mirror_requests SET cancel_settled_at = now(), status = 'pending'
		 WHERE repo_id = $1 AND cluster_slug = $2 AND cancelled_at IS NOT NULL AND cancel_settled_at IS NULL`,
		repoID.String(), clusterSlug)
	if err != nil {
		return false, fmt.Errorf("nativemirror: settle cancelled request %s/%s: %w", repoID, clusterSlug, err)
	}
	return tag.RowsAffected() == 1, nil
}

// CurrentRequest returns the request as stored now. found is false when the
// row is gone.
func (s *Service) CurrentRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (Request, bool, error) {
	req, found, err := firstRequest(ctx, s.pool,
		`SELECT `+requestColumns+` FROM native_mirror_requests WHERE repo_id = $1 AND cluster_slug = $2`,
		repoID.String(), clusterSlug)
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: read request %s/%s: %w", repoID, clusterSlug, err)
	}
	return req, found, nil
}

// RecordRequestRetry returns the attempt to pending while JetStream redelivers
// its job.
func (s *Service) RecordRequestRetry(ctx context.Context, req Request, lastError string) (bool, error) {
	return s.fencedUpdate(ctx, "record request retry", req, `status = 'pending', last_error = $4`, lastError)
}

// RecordRequestWait returns the attempt to pending and lets the sweep publish
// the job again after wait. Waits that end on their own, such as a primary
// that is still provisioning, use this instead of JetStream redelivery.
func (s *Service) RecordRequestWait(ctx context.Context, req Request, lastError string, wait time.Duration) (bool, error) {
	return s.fencedUpdate(ctx, "record request wait", req,
		`status = 'pending', last_error = $4, next_publish_at = now() + ($5::INT8 * INTERVAL '1 microsecond')`,
		lastError, wait.Microseconds())
}

// requestFailedRecheck is how often the sweep checks that a failed request's
// repo still exists.
const requestFailedRecheck = time.Hour

// RecordRequestFailure marks a request that cannot succeed. code and message
// are shown to users; lastError is for operators. The row stays so the repo
// shows the region as failed.
func (s *Service) RecordRequestFailure(ctx context.Context, req Request, code, message, lastError string) (bool, error) {
	if code == "" || message == "" {
		return false, errors.New("nativemirror: failure code and message are required")
	}
	return s.fencedUpdate(ctx, "record request failure", req,
		`status = 'failed', failed_at = now(), failure_code = $4, failure_message = $5, last_error = $6,
		 next_publish_at = now() + ($7::INT8 * INTERVAL '1 microsecond')`,
		code, message, lastError, requestFailedRecheck.Microseconds())
}

// ListRequests returns the repo's requests that are not cancelled, ordered by
// cluster.
func (s *Service) ListRequests(ctx context.Context, repoID model.RepoID) ([]Request, error) {
	requests, err := queryRequests(ctx, s.pool,
		`SELECT `+requestColumns+` FROM native_mirror_requests
		 WHERE repo_id = $1 AND cancelled_at IS NULL ORDER BY cluster_slug`, repoID.String())
	if err != nil {
		return nil, fmt.Errorf("nativemirror: list requests for %s: %w", repoID, err)
	}
	return requests, nil
}

// CancelRequest marks an open request as cancelled by cancelledBy and returns
// it. found is false when there was no open request. The cancel queues the
// row at once, so its job removes any intent and settles it; a failed request
// is cleared first, so it does not stay stranded where no job runs.
func (s *Service) CancelRequest(ctx context.Context, repoID model.RepoID, clusterSlug string, cancelledBy model.AccountID) (Request, bool, error) {
	req, found, err := firstRequest(ctx, s.pool,
		`UPDATE native_mirror_requests SET cancelled_at = now(), cancelled_by_account_id = NULLIF($3, ''),
		     failed_at = NULL, status = CASE WHEN status = 'failed' THEN 'pending' ELSE status END,
		     next_publish_at = now()
		 WHERE repo_id = $1 AND cluster_slug = $2 AND cancelled_at IS NULL
		 RETURNING `+requestColumns,
		repoID.String(), clusterSlug, string(cancelledBy))
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: cancel request %s/%s: %w", repoID, clusterSlug, err)
	}
	return req, found, nil
}

// DeleteRequest removes one request, cancelled or not, and returns it. found
// is false when there was none.
func (s *Service) DeleteRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (Request, bool, error) {
	req, found, err := firstRequest(ctx, s.pool,
		`DELETE FROM native_mirror_requests WHERE repo_id = $1 AND cluster_slug = $2
		 RETURNING `+requestColumns,
		repoID.String(), clusterSlug)
	if err != nil {
		return Request{}, false, fmt.Errorf("nativemirror: delete request %s/%s: %w", repoID, clusterSlug, err)
	}
	return req, found, nil
}

// PurgeCancelledRequests deletes cancelled requests in jurisdiction whose
// removal settled more than olderThan ago. olderThan must exceed the longest
// job attempt: an attempt that started before the cancel reads the row when
// it finishes, and removes the intent it created.
func (s *Service) PurgeCancelledRequests(ctx context.Context, jurisdiction string, olderThan time.Duration) error {
	_, err := s.pool.Exec(ctx,
		`DELETE FROM native_mirror_requests
		 WHERE jurisdiction = $1 AND cancel_settled_at < now() - ($2::INT8 * INTERVAL '1 microsecond')`,
		jurisdiction, olderThan.Microseconds())
	if err != nil {
		return fmt.Errorf("nativemirror: purge cancelled requests in %s: %w", jurisdiction, err)
	}
	return nil
}

// OldestOpenRequestAgeSeconds returns the age of the oldest request in
// jurisdiction that is neither failed nor cancelled, or zero when none is.
func (s *Service) OldestOpenRequestAgeSeconds(ctx context.Context, jurisdiction string) (int64, error) {
	var age int64
	err := s.pool.QueryRow(ctx,
		`SELECT COALESCE(EXTRACT(EPOCH FROM now() - min(created_at))::INT8, 0)
		 FROM native_mirror_requests
		 WHERE jurisdiction = $1 AND failed_at IS NULL AND cancel_settled_at IS NULL AND cancelled_at IS NULL`,
		jurisdiction).Scan(&age)
	if err != nil {
		return 0, fmt.Errorf("nativemirror: oldest open request in %s: %w", jurisdiction, err)
	}
	return age, nil
}

// ClaimFailedRequestsForCheck returns up to limit failed requests in
// jurisdiction that are due for a check that their repo still exists, and
// pushes their next check back by an hour. Publishing never picks failed
// rows, so next_publish_at is free to schedule this check.
func (s *Service) ClaimFailedRequestsForCheck(ctx context.Context, jurisdiction string, limit int) ([]Request, error) {
	claimed, err := s.claimDue(ctx, jurisdiction, limit, true, requestFailedRecheck)
	if err != nil {
		return nil, fmt.Errorf("nativemirror: claim failed requests in %s: %w", jurisdiction, err)
	}
	return claimed, nil
}

package nativemirrorcreate

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"runtime/debug"
	"time"

	"github.com/entireio/go-nuts/backoff"
	"github.com/entireio/go-nuts/jsconsumer"
	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"entire.io/core/coreapi"
	"entire.io/core/model"
	"entire.io/core/nativemirror"
	"entire.io/internal/entirecore/repoops"
	"entire.io/slogutil"
)

const (
	ackWait           = 2 * time.Minute
	maxDeliver        = 5
	attemptTimeout    = 90 * time.Second
	durableNamePrefix = "entirecore-native-mirror-create-"
	dlqSubjectPrefix  = "repo.ops.dlq.v1.native_mirror_create."
	// exhaustedWait is when the sweep publishes a job again after its
	// JetStream deliveries ran out on retryable errors. The runner fails the
	// request once it has kept failing for a day.
	exhaustedWait = 10 * time.Minute
)

// retryPolicy spaces redeliveries 30 s, 1 min, 2 min, then 4 min apart.
var retryPolicy = backoff.Policy{NakDelay: 30 * time.Second, Factor: 2, MaxDelay: 4 * time.Minute, MaxDeliver: maxDeliver}

// RequestStore is the request state the consumer changes.
type RequestStore interface {
	StartRequestAttempt(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
	RecordRequestRetry(ctx context.Context, req nativemirror.Request, lastError string) (bool, error)
	RecordRequestWait(ctx context.Context, req nativemirror.Request, lastError string, wait time.Duration) (bool, error)
	RecordRequestFailure(ctx context.Context, req nativemirror.Request, code, message, lastError string) (bool, error)
}

// Runner makes one attempt at a request.
type Runner interface {
	Run(ctx context.Context, req nativemirror.Request) coreapi.NativeMirrorRequestOutcome
}

// Config contains the consumer dependencies.
type Config struct {
	Conn         *nats.Conn
	Store        RequestStore
	Runner       Runner
	DLQ          natsmsg.DLQPublisher
	Jurisdiction string
}

// Consumer drains native_mirror_create jobs for one jurisdiction.
type Consumer struct {
	cfg Config
}

// New validates cfg and returns a Consumer.
func New(cfg Config) (*Consumer, error) {
	switch {
	case cfg.Conn == nil:
		return nil, errors.New("nativemirrorcreate: Conn is required")
	case cfg.Store == nil:
		return nil, errors.New("nativemirrorcreate: Store is required")
	case cfg.Runner == nil:
		return nil, errors.New("nativemirrorcreate: Runner is required")
	case cfg.DLQ == nil:
		return nil, errors.New("nativemirrorcreate: DLQ is required")
	case cfg.Jurisdiction == "":
		return nil, errors.New("nativemirrorcreate: Jurisdiction is required")
	}
	return &Consumer{cfg: cfg}, nil
}

// Run consumes jobs until ctx is cancelled.
func (c *Consumer) Run(ctx context.Context) {
	err := jsconsumer.Run(ctx, c.cfg.Conn, jsconsumer.Config{
		Name:           "native-mirror-create",
		Stream:         repoops.StreamName,
		Durable:        durableNamePrefix + c.cfg.Jurisdiction,
		FilterSubject:  subjectFilter(c.cfg.Jurisdiction),
		AckWait:        ackWait,
		MaxDeliver:     maxDeliver,
		MaxMessages:    1,
		KeepInProgress: true,
	}, func(ctx context.Context, msg jetstream.Msg) {
		c.handleMessage(ctx, msg)
	})
	if err != nil {
		slogutil.Error(ctx, "native-mirror-create consumer stopped", slog.String("error", err.Error()))
	}
}

func (c *Consumer) handleMessage(ctx context.Context, msg jetstream.Msg) {
	ctx = natsmsg.ExtractHeader(ctx, msg.Headers())
	stopHeartbeat := natsmsg.KeepInProgress(msg.InProgress, ackWait)
	defer stopHeartbeat()
	defer func() {
		if recovered := recover(); recovered != nil {
			slogutil.Error(ctx, "native-mirror-create delivery panicked",
				slog.Any("panic", recovered), slog.String("stack", string(debug.Stack())))
			c.nak(ctx, msg, fmt.Errorf("native-mirror-create delivery panicked: %v", recovered))
		}
	}()

	parsed, err := repoops.ParseSubject(msg.Subject())
	if err != nil {
		c.deadLetterAndAck(ctx, msg, "bad_subject", err)
		return
	}
	j, repoID, err := unmarshalJob(msg.Data())
	if err != nil {
		c.deadLetterAndAck(ctx, msg, "bad_payload", err)
		return
	}
	if parsed.Placement.Jurisdiction != c.cfg.Jurisdiction || parsed.Placement.ClusterSlug != j.ClusterSlug {
		c.deadLetterAndAck(ctx, msg, "route_mismatch", fmt.Errorf(
			"subject %s does not route job for %s/%s in %s", msg.Subject(), repoID, j.ClusterSlug, c.cfg.Jurisdiction))
		return
	}

	req, started, err := c.cfg.Store.StartRequestAttempt(ctx, repoID, j.ClusterSlug)
	if err != nil {
		c.nak(ctx, msg, err)
		return
	}
	if !started {
		// Failed, cancelled, or already done: nothing is left to run.
		c.ack(ctx, msg)
		return
	}
	if req.Jurisdiction != c.cfg.Jurisdiction {
		c.deadLetterAndAck(ctx, msg, "route_mismatch", fmt.Errorf(
			"request %s/%s belongs to %s, consumer is %s", repoID, j.ClusterSlug, req.Jurisdiction, c.cfg.Jurisdiction))
		return
	}
	c.execute(ctx, msg, req)
}

func (c *Consumer) execute(ctx context.Context, msg jetstream.Msg, req nativemirror.Request) {
	ctx, span := otel.Tracer("entire.io/internal/entirecore/nativemirrorcreate").Start(ctx, "native-mirror-create.execute",
		trace.WithSpanKind(trace.SpanKindConsumer),
		trace.WithAttributes(
			attribute.String("repo_id", req.RepoID.String()),
			attribute.String("cluster_slug", req.ClusterSlug),
			attribute.String("placement_id", req.PlacementID.String()),
			attribute.Int64("attempt", req.Attempts),
			attribute.String("messaging.destination.name", msg.Subject()),
		),
	)
	startedAt := time.Now()
	outcome := c.run(ctx, req)
	kind := string(outcome.Kind)
	defer func() {
		span.SetAttributes(attribute.String("native_mirror_request.outcome", kind))
		recordExecution(ctx, c.cfg.Jurisdiction, kind, outcome.Code, time.Since(startedAt))
		span.End()
	}()
	if outcome.Err != nil {
		span.RecordError(outcome.Err)
	}

	var (
		applied bool
		err     error
	)
	switch outcome.Kind {
	case coreapi.NativeMirrorRequestDone, coreapi.NativeMirrorRequestDropped:
		c.ack(ctx, msg)
		return
	case coreapi.NativeMirrorRequestFail:
		applied, err = c.cfg.Store.RecordRequestFailure(ctx, req, outcome.Code, outcome.Message, errText(outcome.Err))
	case coreapi.NativeMirrorRequestWait:
		applied, err = c.cfg.Store.RecordRequestWait(ctx, req, errText(outcome.Err), outcome.Wait)
	case coreapi.NativeMirrorRequestRetry:
		if backoff.IsFinalDelivery(msg, maxDeliver) {
			kind = "exhausted"
			applied, err = c.cfg.Store.RecordRequestWait(ctx, req, errText(outcome.Err), exhaustedWait)
			break
		}
		applied, err = c.cfg.Store.RecordRequestRetry(ctx, req, errText(outcome.Err))
		if err == nil && applied {
			c.nak(ctx, msg, outcome.Err)
			return
		}
	default:
		c.nak(ctx, msg, fmt.Errorf("unknown native-mirror request outcome %q", outcome.Kind))
		return
	}
	if err != nil {
		c.nak(ctx, msg, fmt.Errorf("record %s outcome: %w", kind, err))
		return
	}
	if !applied {
		// A newer attempt, a cancel, or a retry reset owns the row now.
		kind = "superseded"
	}
	c.ack(ctx, msg)
}

func (c *Consumer) run(ctx context.Context, req nativemirror.Request) (outcome coreapi.NativeMirrorRequestOutcome) {
	defer func() {
		if recovered := recover(); recovered != nil {
			slogutil.Error(ctx, "native-mirror-create runner panicked",
				slog.Any("panic", recovered), slog.String("stack", string(debug.Stack())))
			outcome = coreapi.NativeMirrorRequestOutcome{Kind: coreapi.NativeMirrorRequestRetry, Err: fmt.Errorf("runner panicked: %v", recovered)}
		}
	}()
	ctx, cancel := context.WithTimeout(ctx, attemptTimeout)
	defer cancel()
	return c.cfg.Runner.Run(ctx, req)
}

func errText(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func (c *Consumer) deadLetterAndAck(ctx context.Context, msg jetstream.Msg, reason string, cause error) {
	if err := natsmsg.DeadLetter(ctx, c.cfg.DLQ, dlqSubjectPrefix+natsmsg.SubjectToken(reason), msg, reason); err != nil {
		c.nak(ctx, msg, errors.Join(cause, err))
		return
	}
	c.ack(ctx, msg)
}

func (c *Consumer) ack(ctx context.Context, msg jetstream.Msg) {
	if err := msg.Ack(); err != nil {
		slogutil.Warn(ctx, "native-mirror-create ack failed", slog.String("error", err.Error()))
	}
}

func (c *Consumer) nak(ctx context.Context, msg jetstream.Msg, cause error) {
	delay := retryPolicy.DelayFor(backoff.NumDelivered(msg))
	slogutil.Warn(ctx, "native-mirror-create job failed; will retry",
		slog.Duration("delay", delay), slog.String("error", errText(cause)))
	if err := msg.NakWithDelay(delay); err != nil {
		slogutil.Warn(ctx, "native-mirror-create nak failed", slog.String("error", err.Error()))
	}
}

