package coreapi

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"time"

	"github.com/danielgtaylor/huma/v2"

	"entire.io/core/api"
	"entire.io/core/model"
	"entire.io/core/nativemirror"
	"entire.io/slogutil"
)

// nativeMirrorRequestRunnerStore is the native_mirror_requests slice the
// runner uses. *nativemirror.Service satisfies it.
type nativeMirrorRequestRunnerStore interface {
	FinishRequest(ctx context.Context, req nativemirror.Request) (nativemirror.Request, bool, error)
	CurrentRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
	SettleCancelledRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (bool, error)
	DeleteRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
	ClaimFailedRequestsForCheck(ctx context.Context, jurisdiction string, limit int) ([]nativemirror.Request, error)
	PurgeCancelledRequests(ctx context.Context, jurisdiction string, olderThan time.Duration) error
}

const (
	// A request for a repo that is still missing after this long belongs to a
	// create that failed, or to a deleted repo. Before that, the repo row may
	// not be visible yet.
	nativeMirrorRequestOrphanAge = 15 * time.Minute
	// A request that keeps failing for this long is marked failed, so the repo
	// shows the region as failed instead of pending forever. Waits that end on
	// their own, such as paused admission, never give up.
	nativeMirrorRequestGiveUpAge = 24 * time.Hour
	// nativeMirrorRequestProvisioningWait is how long a request waits for its
	// primary to finish provisioning. Repo create publishes as soon as the repo
	// is active, so this only paces the provisioning reconciler's repos.
	nativeMirrorRequestProvisioningWait = time.Minute
	nativeMirrorRequestPausedWait       = 5 * time.Minute
	// nativeMirrorRequestAuthzGrace is how long a denied requester is retried
	// before the request is dropped. A permission check can read a SpiceDB
	// snapshot older than the grant that repo create just wrote.
	nativeMirrorRequestAuthzGrace = 5 * time.Minute
	// nativeMirrorRequestWriteTimeout bounds each store write after an
	// attempt, which runs detached from the attempt's own deadline.
	nativeMirrorRequestWriteTimeout = 10 * time.Second
	// nativeMirrorRequestCancelledKeep is how long a cancelled row stays, so a
	// job that started before the cancel still reads it. It exceeds a job's
	// whole retry chain.
	nativeMirrorRequestCancelledKeep = nativemirror.RequestPublishHold
	nativeMirrorRequestFailedBatch   = 20
)

// Failure codes a failed native-mirror request reports. They are part of the
// public API; entire.io maps them to its own copy.
const (
	NativeMirrorFailureRegionUnavailable = "region_unavailable"
	NativeMirrorFailurePrimaryFailed     = "primary_failed"
	NativeMirrorFailureRetriesExhausted  = "retries_exhausted"
)

var nativeMirrorFailureMessages = map[string]string{
	NativeMirrorFailureRegionUnavailable: "This region is not available for this repository.",
	NativeMirrorFailurePrimaryFailed:     "The repository could not be created, so this region was not added.",
	NativeMirrorFailureRetriesExhausted:  "Adding this region kept failing. Try again, or remove the region.",
}

// NativeMirrorRequestOutcomeKind says what the queue does with a request after
// one attempt.
type NativeMirrorRequestOutcomeKind string

const (
	// NativeMirrorRequestDone means the intent exists and the request row is
	// gone.
	NativeMirrorRequestDone NativeMirrorRequestOutcomeKind = "done"
	// NativeMirrorRequestRetry asks for JetStream redelivery.
	NativeMirrorRequestRetry NativeMirrorRequestOutcomeKind = "retry"
	// NativeMirrorRequestWait acks the job and lets the sweep publish it again
	// after Wait. It spends no delivery on a wait that ends on its own.
	NativeMirrorRequestWait NativeMirrorRequestOutcomeKind = "wait"
	// NativeMirrorRequestFail marks the request failed with Code.
	NativeMirrorRequestFail NativeMirrorRequestOutcomeKind = "fail"
	// NativeMirrorRequestDropped means the request row was deleted because
	// its repo no longer exists.
	NativeMirrorRequestDropped NativeMirrorRequestOutcomeKind = "dropped"
)

// NativeMirrorRequestOutcome is the result of one attempt at a request.
type NativeMirrorRequestOutcome struct {
	Kind NativeMirrorRequestOutcomeKind
	Wait time.Duration
	// Code and Message are set for NativeMirrorRequestFail. Message is safe to
	// show a user.
	Code    string
	Message string
	// Err is the diagnostic cause, stored as the request's last error.
	Err error
}

func requestFailed(code string, cause error) NativeMirrorRequestOutcome {
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestFail, Code: code, Message: nativeMirrorFailureMessages[code], Err: cause}
}

func requestWait(wait time.Duration, cause error) NativeMirrorRequestOutcome {
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestWait, Wait: wait, Err: cause}
}

// NativeMirrorRequestRunner turns one native-mirror request into an intent.
// The native_mirror_create consumer in the primary's jurisdiction calls it
// once per job. POST /repos/{repoId}/native-mirrors stores the request.
type NativeMirrorRequestRunner struct {
	svc          *NativeMirrorService
	store        nativeMirrorRequestRunnerStore
	jurisdiction string
	now          func() time.Time
}

// NewNativeMirrorRequestRunner returns nil when native mirroring is not wired
// on srv.
func NewNativeMirrorRequestRunner(srv *api.Server) *NativeMirrorRequestRunner {
	store := srv.NativeMirrors()
	if store == nil || srv.Jurisdiction() == "" {
		return nil
	}
	return &NativeMirrorRequestRunner{
		svc:          newNativeMirrorService(srv),
		store:        store,
		jurisdiction: srv.Jurisdiction(),
		now:          time.Now,
	}
}

// Run makes one attempt at req, which StartRequestAttempt has marked
// processing. For NativeMirrorRequestDone and NativeMirrorRequestDropped, Run
// has already finished with the request row; the caller records every other
// kind.
func (r *NativeMirrorRequestRunner) Run(ctx context.Context, req nativemirror.Request) NativeMirrorRequestOutcome {
	if req.CancelledAt != nil {
		return r.settleCancel(ctx, req)
	}
	primary, err := r.svc.loadPrimary(ctx, req.RepoID)
	if err != nil {
		if errorStatus(err) == http.StatusNotFound {
			if r.now().Sub(req.CreatedAt) >= nativeMirrorRequestOrphanAge {
				slogutil.Warn(ctx, "native-mirror request dropped: repo not found", requestAttrs(req)...)
				return r.drop(ctx, req, err)
			}
			return requestWait(nativeMirrorRequestProvisioningWait, err)
		}
		return r.retry(req, err)
	}
	switch primary.repo.State {
	case model.RepoStateActive:
	case model.RepoStateFailed:
		return requestFailed(NativeMirrorFailurePrimaryFailed, errors.New("primary repo failed to provision"))
	case model.RepoStateProvisioning:
		// The provisioning reconciler ends this wait, as active or failed.
		return requestWait(nativeMirrorRequestProvisioningWait, errors.New("primary repo is not active yet"))
	default:
		return r.retry(req, fmt.Errorf("primary repo is in state %q", primary.repo.State))
	}

	allowed, err := r.requesterMayManage(ctx, req)
	if err != nil {
		return r.retry(req, err)
	}
	if !allowed {
		denied := errors.New("requester no longer manages the repo")
		if r.now().Sub(req.CreatedAt) < nativeMirrorRequestAuthzGrace {
			return requestWait(nativeMirrorRequestProvisioningWait, denied)
		}
		slogutil.Warn(ctx, "native-mirror request dropped: requester no longer manages the repo", requestAttrs(req)...)
		return r.drop(ctx, req, denied)
	}

	if _, err := r.svc.createIntent(ctx, req.RepoID, primary, req.ClusterSlug, model.AccountID(req.CreatedByAccountID), req.PlacementID); err != nil {
		// The cell refusals share their statuses with conditions that pass or
		// last, so the problem type decides them first.
		switch problemTypeOf(err) {
		case problemTypeNativeMirrorCellOccupied:
			return requestFailed(NativeMirrorFailureRegionUnavailable, err)
		case problemTypeNativeMirrorCellVacating, problemTypeNativeMirrorCellUnknown:
			// Teardown ends a vacating cell. An unknown cell needs an
			// operator, so it must reach the give-up age that a wait never
			// does.
			return r.retry(req, err)
		}
		switch errorStatus(err) {
		case http.StatusBadRequest:
			return requestFailed(NativeMirrorFailureRegionUnavailable, err)
		case http.StatusServiceUnavailable:
			// Paused admission or a dependency outage; both end on their own.
			return requestWait(nativeMirrorRequestPausedWait, err)
		default:
			return r.retry(req, err)
		}
	}

	wctx, cancel := writeContext(ctx)
	current, cancelled, err := r.store.FinishRequest(wctx, req)
	cancel()
	if err != nil {
		// The intent exists. The next attempt finds it and finishes the row.
		return r.retry(req, fmt.Errorf("finish request after create: %w", err))
	}
	if cancelled {
		// The user removed the region while this attempt ran.
		return r.settleCancel(ctx, current)
	}
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
}

// requesterMayManage reports whether the account that asked for the region
// still holds manage on the repo. Submit checked it, but the job can run hours
// later. A request with no account came from an operator, whose authority
// does not lapse this way.
func (r *NativeMirrorRequestRunner) requesterMayManage(ctx context.Context, req nativemirror.Request) (bool, error) {
	if req.CreatedByAccountID == "" {
		return true, nil
	}
	if r.svc.Server.Authz() == nil {
		return false, errors.New("authorization is not configured")
	}
	allowed, err := r.svc.ManageAuthority.repoActionAllowed(ctx, r.svc.Server, "account:"+req.CreatedByAccountID, req.RepoID, "manage")
	if err != nil {
		return false, fmt.Errorf("recheck requester authority: %w", err)
	}
	return allowed, nil
}

// settleCancel removes the intent a cancelled request may have created, then
// marks the cancel settled. A failure is retried with no cut-off: the
// unsettled row keeps the request queued until the removal the user asked
// for has happened.
//
// The request is read again first: a user who asked for the region again
// after the cancel owns it now, and its own job creates the mirror.
func (r *NativeMirrorRequestRunner) settleCancel(ctx context.Context, req nativemirror.Request) NativeMirrorRequestOutcome {
	wctx, cancel := writeContext(ctx)
	defer cancel()
	current, found, err := r.store.CurrentRequest(wctx, req.RepoID, req.ClusterSlug)
	if err != nil {
		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
	}
	if !found || current.CancelledAt == nil {
		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
	}
	if err := r.undoIntent(ctx, current); err != nil {
		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
	}
	settled, err := r.store.SettleCancelledRequest(wctx, req.RepoID, req.ClusterSlug)
	if err != nil {
		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
	}
	if !settled {
		// Asked for again during the teardown. That request's job gets a
		// conflict until the teardown finishes, then creates the mirror.
		slogutil.Info(ctx, "native-mirror region requested again during a cancel teardown", requestAttrs(req)...)
	}
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
}

// retry asks for redelivery, or fails a request that has kept failing for
// nativeMirrorRequestGiveUpAge.
func (r *NativeMirrorRequestRunner) retry(req nativemirror.Request, cause error) NativeMirrorRequestOutcome {
	if r.now().Sub(req.CreatedAt) >= nativeMirrorRequestGiveUpAge {
		return requestFailed(NativeMirrorFailureRetriesExhausted, cause)
	}
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: cause}
}

func (r *NativeMirrorRequestRunner) drop(ctx context.Context, req nativemirror.Request, cause error) NativeMirrorRequestOutcome {
	wctx, cancel := writeContext(ctx)
	defer cancel()
	if _, _, err := r.store.DeleteRequest(wctx, req.RepoID, req.ClusterSlug); err != nil {
		return r.retry(req, fmt.Errorf("drop request: %w", err))
	}
	return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDropped, Err: cause}
}

// undoIntent marks for teardown the intent stored under a cancelled
// request's reserved placement id, if there is one, and audits it as a delete
// by the user who cancelled. Only that id is touched, so an intent created
// some other way for the same region stays.
func (r *NativeMirrorRequestRunner) undoIntent(ctx context.Context, req nativemirror.Request) error {
	wctx, cancel := writeContext(ctx)
	defer cancel()
	row, err := r.svc.intents.Get(wctx, req.PlacementID)
	if errors.Is(err, nativemirror.ErrNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read intent of cancelled request: %w", err)
	}
	if row.DesiredState == nativemirror.DesiredDeleted {
		return nil
	}
	slogutil.Info(ctx, "native-mirror request cancelled during create; removing the intent", requestAttrs(req)...)
	marked, err := r.svc.intents.MarkDesiredDeletedReturning(wctx, row.RepoGroupID, row.ClusterSlug)
	if errors.Is(err, nativemirror.ErrNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("remove intent of cancelled request: %w", err)
	}
	r.svc.auditIntent(wctx, model.AccountID(req.CancelledByAccountID), "native_mirror_delete_requested", req.RepoID, marked, req.Jurisdiction, r.svc.placementJurisdiction(wctx, marked))
	return nil
}

// Housekeeping purges cancelled rows that no job can still hold, and drops
// failed rows whose repo no longer exists. The sweep calls it.
func (r *NativeMirrorRequestRunner) Housekeeping(ctx context.Context) {
	if err := r.store.PurgeCancelledRequests(ctx, r.jurisdiction, nativeMirrorRequestCancelledKeep); err != nil && ctx.Err() == nil {
		slogutil.Error(ctx, "native-mirror cancelled request purge failed", slog.Any("error", err))
	}
	failed, err := r.store.ClaimFailedRequestsForCheck(ctx, r.jurisdiction, nativeMirrorRequestFailedBatch)
	if err != nil {
		if ctx.Err() == nil {
			slogutil.Error(ctx, "native-mirror failed request check claim failed", slog.Any("error", err))
		}
		return
	}
	for _, req := range failed {
		if ctx.Err() != nil {
			return
		}
		if _, err := r.svc.loadPrimary(ctx, req.RepoID); errorStatus(err) == http.StatusNotFound {
			slogutil.Info(ctx, "native-mirror failed request dropped: repo not found", requestAttrs(req)...)
			wctx, cancel := writeContext(ctx)
			if _, _, err := r.store.DeleteRequest(wctx, req.RepoID, req.ClusterSlug); err != nil {
				slogutil.Error(ctx, "native-mirror request delete failed", append(requestAttrs(req), slog.Any("error", err))...)
			}
			cancel()
		}
	}
}

// writeContext outlives the attempt's deadline, so an attempt that used its
// whole budget still records its outcome.
func writeContext(ctx context.Context) (context.Context, context.CancelFunc) {
	return context.WithTimeout(context.WithoutCancel(ctx), nativeMirrorRequestWriteTimeout)
}

// errorStatus returns the HTTP status of a handler error, or 0.
func errorStatus(err error) int {
	if se, ok := errors.AsType[huma.StatusError](err); ok {
		return se.GetStatus()
	}
	return 0
}

func requestAttrs(req nativemirror.Request) []slog.Attr {
	return []slog.Attr{slog.String("repo_id", req.RepoID.String()), slog.String("cluster_slug", req.ClusterSlug)}
}

package entirecore

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"strings"

	"entire.io/core/cluster"
	"entire.io/core/model"
	"entire.io/core/nativemirror"
	"entire.io/core/regional"
	"entire.io/core/resource"
	"entire.io/postgres"
	"entire.io/slogutil"
)

// NativeMirrorCreateOpts names the placement one create run establishes.
type NativeMirrorCreateOpts struct {
	// RepoID is the PRIMARY's repo ULID (must be homed in this core's
	// jurisdiction).
	RepoID string
	// ClusterSlug is the target cluster; it must carry the
	// native_mirror_hosting capability.
	ClusterSlug string
}

// NativeMirrorCreate is the staging/admin create trigger for a native-mirror
// placement (COR-1039): capability check → primary group resolution → durable
// intent (native_mirrors, stage=pending). The target jurisdiction's executor
// subsystem picks the intent up from there; this command does NOT wait.
//
// The public /api/v1/repos/{repoId}/native-mirrors surface is the canonical
// Phase 5 operator path and carries the complete validation + deletion-lock
// contract. This older run-once remains useful for staging diagnosis; it does
// not wait. Idempotent: re-running returns the existing placement ULID.
//
// Runs against the PRIMARY's jurisdiction: the primary must be homed here for
// its placement routing and group identity to be resolvable from this core's
// stores.
func NativeMirrorCreate(cfg Config) func(context.Context, NativeMirrorCreateOpts) error {
	return func(ctx context.Context, opts NativeMirrorCreateOpts) error {
		if !cfg.NativeMirrorEnabled {
			return errors.New("native-mirror lifecycle is disabled (ENTIRE_NATIVE_MIRROR_ENABLED is false)")
		}
		if !cfg.NativeMirrorCreateEnabled {
			return errors.New("native-mirror creation is disabled (ENTIRE_NATIVE_MIRROR_CREATE_ENABLED is false)")
		}
		if cfg.GlobalCockroachDSN == "" {
			return errors.New("GLOBAL_COCKROACH_DSN is required")
		}
		if cfg.Jurisdiction == "" {
			return errors.New("JURISDICTION is required")
		}
		primaryID, err := model.ParseRepoID(opts.RepoID)
		if err != nil {
			return fmt.Errorf("--repo %q is not a repo ULID: %w", opts.RepoID, err)
		}
		if opts.ClusterSlug == "" {
			return errors.New("--cluster is required")
		}

		globalPool, err := postgres.NewPool(ctx, cfg.GlobalCockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
		if err != nil {
			return fmt.Errorf("connect global cockroachdb: %w", err)
		}
		defer globalPool.Close()
		regionalPool, err := postgres.NewPool(ctx, cfg.CockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
		if err != nil {
			return fmt.Errorf("connect regional cockroachdb: %w", err)
		}
		defer regionalPool.Close()

		resources := resource.NewStore(globalPool, nil)
		clusters := cluster.NewStore(globalPool, cluster.WithCacheTTL(clusterCacheTTL))
		intents := nativemirror.New(globalPool)
		// identity/authz/registry are nil: only the repos-row read (object
		// format) runs against the regional store.
		regionalStore := regional.NewStore(regionalPool, nil, nil, nil, cfg.Jurisdiction)

		// The primary must be homed here: the placement it expands belongs to
		// this core's jurisdiction.
		//
		// ListRepoPlacementsByIDs, NOT ListRepoRegistrationsByIDs: only the
		// placement listing populates GroupDataPrimaryRepoID / GitHubRepoID / GroupForge
		// (the registrations listing leaves them zero), and
		// validateAdminNativeMirrorPrimary below reads exactly those fields —
		// with the registrations listing the identity checks would silently
		// pass for every repo. Same source the public API's loadPrimary uses.
		regs, err := resources.ListRepoPlacementsByIDs(ctx, []model.RepoID{primaryID})
		if err != nil {
			return fmt.Errorf("load primary registration: %w", err)
		}
		if len(regs) == 0 {
			return fmt.Errorf("repo %s has no registry row", primaryID)
		}
		primary := regs[0]
		if primary.Jurisdiction != cfg.Jurisdiction {
			return fmt.Errorf("repo %s is homed in jurisdiction %q — run this in that jurisdiction's core (this one is %q)",
				primaryID, primary.Jurisdiction, cfg.Jurisdiction)
		}
		if primary.URL == "" {
			return fmt.Errorf("repo %s has no repo_urls binding", primaryID)
		}
		if err := validateAdminNativeMirrorPrimary(primary); err != nil {
			return err
		}

		// Capability check — the load-bearing confinement: only clusters whose
		// fixture grants native_mirror_hosting are legal targets, and no prod
		// fixture does. GetBySlugGlobal already filters decommissioned_at IS
		// NULL, so a decommissioned slug surfaces here as a lookup failure —
		// no separate DecommissionedAt branch is reachable.
		target, err := clusters.GetBySlugGlobal(ctx, opts.ClusterSlug)
		if err != nil {
			return fmt.Errorf("target cluster %q: %w", opts.ClusterSlug, err)
		}
		if err := validateAdminNativeMirrorTarget(primary, target); err != nil {
			return err
		}

		// Snapshot the immutable creation params (PLAN.md: object_format is
		// regional-row-only — a Provision without it would default a sha256
		// repo to sha1; the URL pins the primary's public identity for the
		// data-plane 403 hint).
		repo, err := regionalStore.GetRepo(ctx, primaryID)
		if err != nil {
			return fmt.Errorf("load primary regional row: %w", err)
		}
		if repo.State != model.RepoStateActive {
			return fmt.Errorf("repo %s is not active (state %q)", primaryID, repo.State)
		}
		home, err := clusters.GetBySlugGlobal(ctx, primary.ClusterSlug)
		if err != nil {
			return fmt.Errorf("primary home cluster %q: %w", primary.ClusterSlug, err)
		}
		primaryPublicURL := strings.TrimSuffix(home.PublicURL, "/") + primary.URL

		// Step 0 — resolve the group the placement is created under. The
		// primary's own data-plane row already carries it (the regional
		// reconciler passes it to Provision at create time), so nothing is
		// re-stamped here. Idempotent, so re-running a partially-failed
		// create is safe.
		//
		// selfPrimary=true: a native repo is its own processing primary, and
		// only this call stamps processing_primary_repo_id on first mint. The
		// later placement publish never fills it, so the primary's facts
		// would stay suppressed if this call didn't pass itself as primary.
		primaryProject, err := resources.GetProject(ctx, primary.OwningProjectID)
		if err != nil {
			return fmt.Errorf("load primary owning project: %w", err)
		}
		groupID, err := resources.GetOrCreateRepoGroup(ctx, resource.EntireForgeRepo{ID: primaryID}, &primaryID,
			model.NativeGroupFullName(primaryProject.Name, primary.Name), primaryProject.Name, primary.OwningProjectID)
		if err != nil {
			return fmt.Errorf("resolve primary repo group: %w", err)
		}

		// CreateWithGroupLock (not the bare Create) so this trigger serializes
		// against primary deletion exactly like the public API: a standing
		// delete_pending_at tombstone rejects the create instead of landing an
		// intent behind an accepted primary delete.
		placementID, created, err := intents.CreateWithGroupLock(ctx, nativemirror.CreateParams{
			RepoGroupID:   groupID,
			ClusterSlug:   target.Slug,
			ObjectFormat:  repo.ObjectFormat,
			URL:           primaryPublicURL,
			DefaultBranch: "",
		})
		if err != nil {
			return mapAdminNativeMirrorCreateError(err)
		}
		row, err := resumeAdminNativeMirrorIntent(ctx, intents, placementID, created)
		if err != nil {
			return err
		}
		slogutil.Info(ctx, "native-mirror placement intent recorded",
			slog.String("placement_id", placementID.String()),
			slog.String("primary_id", primaryID.String()),
			slog.String("repo_group_id", groupID.String()),
			slog.String("target_cluster", target.Slug),
			slog.String("primary_url", primaryPublicURL),
			slog.Bool("created", created))
		fmt.Printf("placement %s on %s (stage=%s; the %s executor drives it to announced — watch its logs)\n",
			placementID, target.Slug, row.Stage, target.Jurisdiction)
		return nil
	}
}

// adminNativeMirrorIntents is the store slice resumeAdminNativeMirrorIntent
// drives. *nativemirror.Service satisfies it; the fake in the tests pins the
// call ordering and error propagation.
type adminNativeMirrorIntents interface {
	ResetForRetry(ctx context.Context, id model.RepoID) error
	Get(ctx context.Context, id model.RepoID) (nativemirror.NativeMirror, error)
}

// resumeAdminNativeMirrorIntent is the post-create half of the admin trigger,
// mirroring the public API's repeated-POST contract: an idempotent re-run
// (created=false) is also the recovery control for a permanently-failed
// creation (creation_failed_at set at the MaxCreationAttempts cap or on a
// validation-class error), so it MUST re-arm via ResetForRetry before the row
// is read for the operator report — without the reset the row stays
// unclaimable while the report promises the executor will drive it to
// announced. The reset is a no-op for ordinary active/announced rows and
// cannot resurrect a deletion intent. Errors propagate; nothing is swallowed.
// Extracted for unit-testing, like the validate helpers above.
func resumeAdminNativeMirrorIntent(ctx context.Context, intents adminNativeMirrorIntents, placementID model.RepoID, created bool) (nativemirror.NativeMirror, error) {
	if !created {
		if err := intents.ResetForRetry(ctx, placementID); err != nil {
			return nativemirror.NativeMirror{}, fmt.Errorf("reset permanently-failed placement for retry: %w", err)
		}
	}
	// Report the row's ACTUAL state, read AFTER the reset: an idempotent
	// re-run returns an existing placement that may already be
	// registered/seeded/announced, and a pre-reset read would report the
	// stale failed status the reset just cleared.
	row, err := intents.Get(ctx, placementID)
	if err != nil {
		return nativemirror.NativeMirror{}, fmt.Errorf("read placement after create: %w", err)
	}
	return row, nil
}

// validateAdminNativeMirrorPrimary rejects repos that must never be primaries,
// mirroring the public API's loadPrimary (coreapi.CreateNativeMirror): a
// native-mirror placement (manage its primary instead — the data plane would
// reject the group mismatch anyway, but only after GetOrCreateRepoGroup
// created a stray repo_group row for it), a GitHub-mirror-group repo, and
// a placement with inconsistent group identity. Extracted for unit-testing,
// like validateAdminNativeMirrorTarget.
func validateAdminNativeMirrorPrimary(primary *resource.RepoRegistrationWithURL) error {
	// GroupForgeRef is a read-path field, resolved by the scan behind
	// ListRepoPlacementsByIDs (the loader above) — NOT the embedded write-path
	// Role field, which reads never fill. Dispatch on it rather than on forge
	// fields: the group's typed identity is the authority on its own forge.
	// Fail closed on a row whose group ref the scan could not resolve. Every
	// placement joins repo_group on a NOT NULL FK, so the pair is present and
	// an unresolved ref means a forge value this build does not know — corrupt,
	// or written by a newer deploy. A write path must not accept an identity it
	// cannot name.
	if primary.GroupForgeRef == nil {
		return fmt.Errorf("repo %s has an unnameable group forge (forge %q, data_primary_repo_id %q)",
			primary.ID, primary.GroupForge, primary.GroupDataPrimaryRepoID)
	}
	if primary.IsDataPrimary() {
		return nil
	}
	// Ask the ref who owns the data instead. A placement in this system means
	// the caller asked on a replica; an upstream forge means a mirror.
	if primary.GroupForgeRef.OwnedByPlacement() {
		return fmt.Errorf("repo %s is a native-mirror placement; create mirrors on its primary repo instead", primary.ID)
	}
	return fmt.Errorf("repo %s belongs to a GitHub-mirror group; native mirrors can only be created for native repos", primary.ID)
}

// validateAdminNativeMirrorTarget rejects targets the executor could never
// drive, mirroring the public API's checks (coreapi.CreateNativeMirror) so the
// staging/admin trigger cannot record an intent no reconciler runs: a hidden
// cluster, one without the native_mirror_hosting capability, the primary's own
// cluster, or a same-jurisdiction target (v1 supports cross-jurisdiction only —
// the target jurisdiction's executor drives the tail). Extracted so these
// branches are unit-testable without the command's pool/bridge construction.
func validateAdminNativeMirrorTarget(primary *resource.RepoRegistrationWithURL, target *cluster.Cluster) error {
	switch {
	case target.Hidden:
		return fmt.Errorf("cluster %q is hidden", target.Slug)
	case !target.NativeMirrorHosting:
		return fmt.Errorf("cluster %q does not carry the native_mirror_hosting capability", target.Slug)
	case target.Slug == primary.ClusterSlug:
		return fmt.Errorf("cluster %q is the primary's own cluster", target.Slug)
	case target.Jurisdiction == primary.Jurisdiction:
		return fmt.Errorf("cluster %q is in the primary's jurisdiction %q; same-jurisdiction native mirrors are not supported",
			target.Slug, primary.Jurisdiction)
	default:
		return nil
	}
}

// mapAdminNativeMirrorCreateError translates a CreateWithGroupLock failure into
// the operator-facing message. The deletion-race sentinels get a specific hint;
// anything else is wrapped generically. Extracted so the mapping (and, with it,
// the guarantee that this trigger serializes against primary deletion via
// CreateWithGroupLock rather than the bare Create) is unit-testable.
func mapAdminNativeMirrorCreateError(err error) error {
	switch {
	case errors.Is(err, nativemirror.ErrGroupBeingDeleted):
		return errors.New("primary repo is being deleted; native-mirror creation is blocked")
	case errors.Is(err, nativemirror.ErrBeingDeleted):
		return errors.New("a native mirror on this cluster is being deleted; retry once teardown completes")
	case errors.Is(err, nativemirror.ErrTrustPublicationPending):
		return errors.New("a trust publication is pending for this repo; retry after it settles")
	case errors.Is(err, nativemirror.ErrTrustRestoreHold):
		return errors.New("the repo is under a trust restore hold; retry after the restore is adopted or cancelled")
	case errors.Is(err, nativemirror.ErrRepoRooted):
		return errors.New("repo is rooted; adding a placement is not supported in this slice")
	default:
		return fmt.Errorf("insert placement intent: %w", err)
	}
}

