1	package coreapi
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"net/http"
9		"time"
10	
11		"github.com/danielgtaylor/huma/v2"
12	
13		"entire.io/core/api"
14		"entire.io/core/model"
15		"entire.io/core/nativemirror"
16		"entire.io/slogutil"
17	)
18	
19	// nativeMirrorRequestRunnerStore is the native_mirror_requests slice the
20	// runner uses. *nativemirror.Service satisfies it.
21	type nativeMirrorRequestRunnerStore interface {
22		FinishRequest(ctx context.Context, req nativemirror.Request) (nativemirror.Request, bool, error)
23		CurrentRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
24		SettleCancelledRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (bool, error)
25		DeleteRequest(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
26		ClaimFailedRequestsForCheck(ctx context.Context, jurisdiction string, limit int) ([]nativemirror.Request, error)
27		PurgeCancelledRequests(ctx context.Context, jurisdiction string, olderThan time.Duration) error
28	}
29	
30	const (
31		// A request for a repo that is still missing after this long belongs to a
32		// create that failed, or to a deleted repo. Before that, the repo row may
33		// not be visible yet.
34		nativeMirrorRequestOrphanAge = 15 * time.Minute
35		// A request that keeps failing for this long is marked failed, so the repo
36		// shows the region as failed instead of pending forever. Waits that end on
37		// their own, such as paused admission, never give up.
38		nativeMirrorRequestGiveUpAge = 24 * time.Hour
39		// nativeMirrorRequestProvisioningWait is how long a request waits for its
40		// primary to finish provisioning. Repo create publishes as soon as the repo
41		// is active, so this only paces the provisioning reconciler's repos.
42		nativeMirrorRequestProvisioningWait = time.Minute
43		nativeMirrorRequestPausedWait       = 5 * time.Minute
44		// nativeMirrorRequestAuthzGrace is how long a denied requester is retried
45		// before the request is dropped. A permission check can read a SpiceDB
46		// snapshot older than the grant that repo create just wrote.
47		nativeMirrorRequestAuthzGrace = 5 * time.Minute
48		// nativeMirrorRequestWriteTimeout bounds each store write after an
49		// attempt, which runs detached from the attempt's own deadline.
50		nativeMirrorRequestWriteTimeout = 10 * time.Second
51		// nativeMirrorRequestCancelledKeep is how long a cancelled row stays, so a
52		// job that started before the cancel still reads it. It exceeds a job's
53		// whole retry chain.
54		nativeMirrorRequestCancelledKeep = nativemirror.RequestPublishHold
55		nativeMirrorRequestFailedBatch   = 20
56	)
57	
58	// Failure codes a failed native-mirror request reports. They are part of the
59	// public API; entire.io maps them to its own copy.
60	const (
61		NativeMirrorFailureRegionUnavailable = "region_unavailable"
62		NativeMirrorFailurePrimaryFailed     = "primary_failed"
63		NativeMirrorFailureRetriesExhausted  = "retries_exhausted"
64	)
65	
66	var nativeMirrorFailureMessages = map[string]string{
67		NativeMirrorFailureRegionUnavailable: "This region is not available for this repository.",
68		NativeMirrorFailurePrimaryFailed:     "The repository could not be created, so this region was not added.",
69		NativeMirrorFailureRetriesExhausted:  "Adding this region kept failing. Try again, or remove the region.",
70	}
71	
72	// NativeMirrorRequestOutcomeKind says what the queue does with a request after
73	// one attempt.
74	type NativeMirrorRequestOutcomeKind string
75	
76	const (
77		// NativeMirrorRequestDone means the intent exists and the request row is
78		// gone.
79		NativeMirrorRequestDone NativeMirrorRequestOutcomeKind = "done"
80		// NativeMirrorRequestRetry asks for JetStream redelivery.
81		NativeMirrorRequestRetry NativeMirrorRequestOutcomeKind = "retry"
82		// NativeMirrorRequestWait acks the job and lets the sweep publish it again
83		// after Wait. It spends no delivery on a wait that ends on its own.
84		NativeMirrorRequestWait NativeMirrorRequestOutcomeKind = "wait"
85		// NativeMirrorRequestFail marks the request failed with Code.
86		NativeMirrorRequestFail NativeMirrorRequestOutcomeKind = "fail"
87		// NativeMirrorRequestDropped means the request row was deleted because
88		// its repo no longer exists.
89		NativeMirrorRequestDropped NativeMirrorRequestOutcomeKind = "dropped"
90	)
91	
92	// NativeMirrorRequestOutcome is the result of one attempt at a request.
93	type NativeMirrorRequestOutcome struct {
94		Kind NativeMirrorRequestOutcomeKind
95		Wait time.Duration
96		// Code and Message are set for NativeMirrorRequestFail. Message is safe to
97		// show a user.
98		Code    string
99		Message string
100		// Err is the diagnostic cause, stored as the request's last error.
101		Err error
102	}
103	
104	func requestFailed(code string, cause error) NativeMirrorRequestOutcome {
105		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestFail, Code: code, Message: nativeMirrorFailureMessages[code], Err: cause}
106	}
107	
108	func requestWait(wait time.Duration, cause error) NativeMirrorRequestOutcome {
109		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestWait, Wait: wait, Err: cause}
110	}
111	
112	// NativeMirrorRequestRunner turns one native-mirror request into an intent.
113	// The native_mirror_create consumer in the primary's jurisdiction calls it
114	// once per job. POST /repos/{repoId}/native-mirrors stores the request.
115	type NativeMirrorRequestRunner struct {
116		svc          *NativeMirrorService
117		store        nativeMirrorRequestRunnerStore
118		jurisdiction string
119		now          func() time.Time
120	}
121	
122	// NewNativeMirrorRequestRunner returns nil when native mirroring is not wired
123	// on srv.
124	func NewNativeMirrorRequestRunner(srv *api.Server) *NativeMirrorRequestRunner {
125		store := srv.NativeMirrors()
126		if store == nil || srv.Jurisdiction() == "" {
127			return nil
128		}
129		return &NativeMirrorRequestRunner{
130			svc:          newNativeMirrorService(srv),
131			store:        store,
132			jurisdiction: srv.Jurisdiction(),
133			now:          time.Now,
134		}
135	}
136	
137	// Run makes one attempt at req, which StartRequestAttempt has marked
138	// processing. For NativeMirrorRequestDone and NativeMirrorRequestDropped, Run
139	// has already finished with the request row; the caller records every other
140	// kind.
141	func (r *NativeMirrorRequestRunner) Run(ctx context.Context, req nativemirror.Request) NativeMirrorRequestOutcome {
142		if req.CancelledAt != nil {
143			return r.settleCancel(ctx, req)
144		}
145		primary, err := r.svc.loadPrimary(ctx, req.RepoID)
146		if err != nil {
147			if errorStatus(err) == http.StatusNotFound {
148				if r.now().Sub(req.CreatedAt) >= nativeMirrorRequestOrphanAge {
149					slogutil.Warn(ctx, "native-mirror request dropped: repo not found", requestAttrs(req)...)
150					return r.drop(ctx, req, err)
151				}
152				return requestWait(nativeMirrorRequestProvisioningWait, err)
153			}
154			return r.retry(req, err)
155		}
156		switch primary.repo.State {
157		case model.RepoStateActive:
158		case model.RepoStateFailed:
159			return requestFailed(NativeMirrorFailurePrimaryFailed, errors.New("primary repo failed to provision"))
160		case model.RepoStateProvisioning:
161			// The provisioning reconciler ends this wait, as active or failed.
162			return requestWait(nativeMirrorRequestProvisioningWait, errors.New("primary repo is not active yet"))
163		default:
164			return r.retry(req, fmt.Errorf("primary repo is in state %q", primary.repo.State))
165		}
166	
167		allowed, err := r.requesterMayManage(ctx, req)
168		if err != nil {
169			return r.retry(req, err)
170		}
171		if !allowed {
172			denied := errors.New("requester no longer manages the repo")
173			if r.now().Sub(req.CreatedAt) < nativeMirrorRequestAuthzGrace {
174				return requestWait(nativeMirrorRequestProvisioningWait, denied)
175			}
176			slogutil.Warn(ctx, "native-mirror request dropped: requester no longer manages the repo", requestAttrs(req)...)
177			return r.drop(ctx, req, denied)
178		}
179	
180		if _, err := r.svc.createIntent(ctx, req.RepoID, primary, req.ClusterSlug, model.AccountID(req.CreatedByAccountID), req.PlacementID); err != nil {
181			// The cell refusals share their statuses with conditions that pass or
182			// last, so the problem type decides them first.
183			switch problemTypeOf(err) {
184			case problemTypeNativeMirrorCellOccupied:
185				return requestFailed(NativeMirrorFailureRegionUnavailable, err)
186			case problemTypeNativeMirrorCellVacating, problemTypeNativeMirrorCellUnknown:
187				// Teardown ends a vacating cell. An unknown cell needs an
188				// operator, so it must reach the give-up age that a wait never
189				// does.
190				return r.retry(req, err)
191			}
192			switch errorStatus(err) {
193			case http.StatusBadRequest:
194				return requestFailed(NativeMirrorFailureRegionUnavailable, err)
195			case http.StatusServiceUnavailable:
196				// Paused admission or a dependency outage; both end on their own.
197				return requestWait(nativeMirrorRequestPausedWait, err)
198			default:
199				return r.retry(req, err)
200			}
201		}
202	
203		wctx, cancel := writeContext(ctx)
204		current, cancelled, err := r.store.FinishRequest(wctx, req)
205		cancel()
206		if err != nil {
207			// The intent exists. The next attempt finds it and finishes the row.
208			return r.retry(req, fmt.Errorf("finish request after create: %w", err))
209		}
210		if cancelled {
211			// The user removed the region while this attempt ran.
212			return r.settleCancel(ctx, current)
213		}
214		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
215	}
216	
217	// requesterMayManage reports whether the account that asked for the region
218	// still holds manage on the repo. Submit checked it, but the job can run hours
219	// later. A request with no account came from an operator, whose authority
220	// does not lapse this way.
221	func (r *NativeMirrorRequestRunner) requesterMayManage(ctx context.Context, req nativemirror.Request) (bool, error) {
222		if req.CreatedByAccountID == "" {
223			return true, nil
224		}
225		if r.svc.Server.Authz() == nil {
226			return false, errors.New("authorization is not configured")
227		}
228		allowed, err := r.svc.ManageAuthority.repoActionAllowed(ctx, r.svc.Server, "account:"+req.CreatedByAccountID, req.RepoID, "manage")
229		if err != nil {
230			return false, fmt.Errorf("recheck requester authority: %w", err)
231		}
232		return allowed, nil
233	}
234	
235	// settleCancel removes the intent a cancelled request may have created, then
236	// marks the cancel settled. A failure is retried with no cut-off: the
237	// unsettled row keeps the request queued until the removal the user asked
238	// for has happened.
239	//
240	// The request is read again first: a user who asked for the region again
241	// after the cancel owns it now, and its own job creates the mirror.
242	func (r *NativeMirrorRequestRunner) settleCancel(ctx context.Context, req nativemirror.Request) NativeMirrorRequestOutcome {
243		wctx, cancel := writeContext(ctx)
244		defer cancel()
245		current, found, err := r.store.CurrentRequest(wctx, req.RepoID, req.ClusterSlug)
246		if err != nil {
247			return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
248		}
249		if !found || current.CancelledAt == nil {
250			return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
251		}
252		if err := r.undoIntent(ctx, current); err != nil {
253			return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
254		}
255		settled, err := r.store.SettleCancelledRequest(wctx, req.RepoID, req.ClusterSlug)
256		if err != nil {
257			return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: err}
258		}
259		if !settled {
260			// Asked for again during the teardown. That request's job gets a
261			// conflict until the teardown finishes, then creates the mirror.
262			slogutil.Info(ctx, "native-mirror region requested again during a cancel teardown", requestAttrs(req)...)
263		}
264		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDone}
265	}
266	
267	// retry asks for redelivery, or fails a request that has kept failing for
268	// nativeMirrorRequestGiveUpAge.
269	func (r *NativeMirrorRequestRunner) retry(req nativemirror.Request, cause error) NativeMirrorRequestOutcome {
270		if r.now().Sub(req.CreatedAt) >= nativeMirrorRequestGiveUpAge {
271			return requestFailed(NativeMirrorFailureRetriesExhausted, cause)
272		}
273		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestRetry, Err: cause}
274	}
275	
276	func (r *NativeMirrorRequestRunner) drop(ctx context.Context, req nativemirror.Request, cause error) NativeMirrorRequestOutcome {
277		wctx, cancel := writeContext(ctx)
278		defer cancel()
279		if _, _, err := r.store.DeleteRequest(wctx, req.RepoID, req.ClusterSlug); err != nil {
280			return r.retry(req, fmt.Errorf("drop request: %w", err))
281		}
282		return NativeMirrorRequestOutcome{Kind: NativeMirrorRequestDropped, Err: cause}
283	}
284	
285	// undoIntent marks for teardown the intent stored under a cancelled
286	// request's reserved placement id, if there is one, and audits it as a delete
287	// by the user who cancelled. Only that id is touched, so an intent created
288	// some other way for the same region stays.
289	func (r *NativeMirrorRequestRunner) undoIntent(ctx context.Context, req nativemirror.Request) error {
290		wctx, cancel := writeContext(ctx)
291		defer cancel()
292		row, err := r.svc.intents.Get(wctx, req.PlacementID)
293		if errors.Is(err, nativemirror.ErrNotFound) {
294			return nil
295		}
296		if err != nil {
297			return fmt.Errorf("read intent of cancelled request: %w", err)
298		}
299		if row.DesiredState == nativemirror.DesiredDeleted {
300			return nil
301		}
302		slogutil.Info(ctx, "native-mirror request cancelled during create; removing the intent", requestAttrs(req)...)
303		marked, err := r.svc.intents.MarkDesiredDeletedReturning(wctx, row.RepoGroupID, row.ClusterSlug)
304		if errors.Is(err, nativemirror.ErrNotFound) {
305			return nil
306		}
307		if err != nil {
308			return fmt.Errorf("remove intent of cancelled request: %w", err)
309		}
310		r.svc.auditIntent(wctx, model.AccountID(req.CancelledByAccountID), "native_mirror_delete_requested", req.RepoID, marked, req.Jurisdiction, r.svc.placementJurisdiction(wctx, marked))
311		return nil
312	}
313	
314	// Housekeeping purges cancelled rows that no job can still hold, and drops
315	// failed rows whose repo no longer exists. The sweep calls it.
316	func (r *NativeMirrorRequestRunner) Housekeeping(ctx context.Context) {
317		if err := r.store.PurgeCancelledRequests(ctx, r.jurisdiction, nativeMirrorRequestCancelledKeep); err != nil && ctx.Err() == nil {
318			slogutil.Error(ctx, "native-mirror cancelled request purge failed", slog.Any("error", err))
319		}
320		failed, err := r.store.ClaimFailedRequestsForCheck(ctx, r.jurisdiction, nativeMirrorRequestFailedBatch)
321		if err != nil {
322			if ctx.Err() == nil {
323				slogutil.Error(ctx, "native-mirror failed request check claim failed", slog.Any("error", err))
324			}
325			return
326		}
327		for _, req := range failed {
328			if ctx.Err() != nil {
329				return
330			}
331			if _, err := r.svc.loadPrimary(ctx, req.RepoID); errorStatus(err) == http.StatusNotFound {
332				slogutil.Info(ctx, "native-mirror failed request dropped: repo not found", requestAttrs(req)...)
333				wctx, cancel := writeContext(ctx)
334				if _, _, err := r.store.DeleteRequest(wctx, req.RepoID, req.ClusterSlug); err != nil {
335					slogutil.Error(ctx, "native-mirror request delete failed", append(requestAttrs(req), slog.Any("error", err))...)
336				}
337				cancel()
338			}
339		}
340	}
341	
342	// writeContext outlives the attempt's deadline, so an attempt that used its
343	// whole budget still records its outcome.
344	func writeContext(ctx context.Context) (context.Context, context.CancelFunc) {
345		return context.WithTimeout(context.WithoutCancel(ctx), nativeMirrorRequestWriteTimeout)
346	}
347	
348	// errorStatus returns the HTTP status of a handler error, or 0.
349	func errorStatus(err error) int {
350		if se, ok := errors.AsType[huma.StatusError](err); ok {
351			return se.GetStatus()
352		}
353		return 0
354	}
355	
356	func requestAttrs(req nativemirror.Request) []slog.Attr {
357		return []slog.Attr{slog.String("repo_id", req.RepoID.String()), slog.String("cluster_slug", req.ClusterSlug)}
358	}
359

