package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"time"

	"entire.io/core/cluster"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/core/registry"
	"entire.io/core/repoadmin"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

// The executor drives creation and teardown in the placement's jurisdiction.
// Every external step on both legs is idempotent, so a reclaimed row resumes
// from recorded state after a crash or lease loss. Creation is stage-CAS'd;
// teardown is selected by durable desired_state and retains the row as its
// retry anchor until every placement-owned resource has been removed.

// ExecutorRegistry is the resource-store slice the executor uses;
// resource.Service satisfies it. The registry publish is on RegistryPublisher.
type ExecutorRegistry interface {
	GetRepoRegistration(ctx context.Context, repoID model.RepoID) (*model.RepoRegistration, error)
	GetProject(ctx context.Context, projectID model.ProjectID) (*model.Project, error)
	UnpublishRepo(ctx context.Context, repoID model.RepoID) error
}

// ExecutorProvisioner is the core→data-plane Provision slice the executor
// dispatches through. api.RepoBridge (repoadmin.Router in production)
// satisfies it.
type ExecutorProvisioner interface {
	Provision(ctx context.Context, clusterSlug string, params model.ProvisionParams) error
	Delete(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.DeleteResult, error)
}

// ExecutorAuthz links placements to their group and removes placement relationships on teardown.
// authz.Service satisfies it.
type ExecutorAuthz interface {
	NativeMirrorPlacementRegistered(ctx context.Context, mirrorID model.RepoID, groupID model.RepoGroupID) error
	NativeMirrorPlacementDeleted(ctx context.Context, mirrorID model.RepoID) error
}

// ExecutorSeeder publishes the placement's initial entiredb-kind sync job.
// *gitjobs.Publisher satisfies it.
type ExecutorSeeder interface {
	PublishEntireDBSyncRepo(ctx context.Context, placement gitjobs.Placement, source gitjobs.Source, target gitjobs.Target) error
}

// ExecutorClusters resolves cluster rows — the data primary's home (internal
// fetch URL). *cluster.Store satisfies it.
type ExecutorClusters interface {
	GetBySlugGlobal(ctx context.Context, slug string) (*cluster.Cluster, error)
}

// ExecutorLifecycle publishes placement lifecycle projections consumed by
// entire-api. *resourceevents.Emitter satisfies it. Publish is the shared
// best-effort contract; on both legs it is only the low-latency attempt, with
// durability owned by a same-transaction outbox row a relay republishes
// through PubAck — the deletion outbox on teardown (COR-1049) and the created
// outbox on the seeded→announced announce (COR-1359).
type ExecutorLifecycle interface {
	Publish(ctx context.Context, resourceType, resourceID, op, actorID string, opts ...resourceevents.PublishOption)
}

// ExecutorConfig tunes one executor instance.
type ExecutorConfig struct {
	// Jurisdiction scopes claims: only intents whose target cluster lives
	// here are eligible (the Claim SQL joins clusters on it). Required.
	Jurisdiction string
	// ClaimedBy fences every stage transition on this identity (the pod
	// name in production). Required.
	ClaimedBy string
	// Interval between claim attempts; a successful claim immediately
	// re-polls so a backlog drains at execution speed, not tick speed.
	// Default 15s.
	Interval time.Duration
	// Lease is the claim's validity; an expired lease makes the row
	// reclaimable (crashed executor). Default DefaultClaimLease.
	Lease time.Duration
	// RetryBackoff spaces re-claims of a row whose execution errored.
	// Default 30s.
	RetryBackoff time.Duration
	// MaxCreationAttempts caps how many times a creation is retried before it
	// is marked permanently failed (status=failed, creation_failed_at set) so
	// it stops re-claiming and surfaces on the status API. A validation-class
	// error fails immediately regardless of count. Teardown is never capped —
	// it must converge for account erasure. Default 20.
	MaxCreationAttempts int64
	// StuckThreshold is the attempt count past which a still-failing row emits
	// an escalation log/metric. It does not change control flow; it exists so a
	// teardown that cannot converge (which would block account-erasure
	// draining indefinitely, since teardown is never capped) is observable
	// rather than silent. Default 10.
	StuckThreshold int64
}

func (c ExecutorConfig) withDefaults() ExecutorConfig {
	if c.Interval <= 0 {
		c.Interval = 15 * time.Second
	}
	if c.Lease <= 0 {
		c.Lease = DefaultClaimLease
	}
	if c.RetryBackoff <= 0 {
		c.RetryBackoff = 30 * time.Second
	}
	if c.MaxCreationAttempts <= 0 {
		c.MaxCreationAttempts = 20
	}
	if c.StuckThreshold <= 0 {
		c.StuckThreshold = 10
	}
	return c
}

// errPermanentCreation classifies a creation failure that retrying cannot
// resolve (a validation-class error on immutable intent state). RunOnce marks
// such a row permanently failed on the first occurrence instead of hot-looping
// it to the attempts cap.
var errPermanentCreation = errors.New("permanent creation failure")

// errRetryUncapped classifies a creation-step failure that must retry
// indefinitely, exempt from MaxCreationAttempts. Used for the entire
// seeded→announced announce step (project load, event marshal, the terminal
// CAS+enqueue transaction): at that point every resource is built and
// replicating, so permanently failing the row is pure loss — a routine
// database or registry outage longer than cap×backoff (~10 minutes at the
// defaults) would otherwise mass-convert finished creations into permanent
// failures that nothing heals (the resync sweep repairs sync lag on serving
// placements; it never re-announces, and permafailed rows are dropped from
// serving). Rows held here past StuckThreshold attempts emit the same
// escalation signal as a stuck teardown.
var errRetryUncapped = errors.New("retryable outside the attempts cap")

// Executor drives native-mirror creation intents in one jurisdiction.
type Executor struct {
	intents  *Service
	registry ExecutorRegistry
	bridge   ExecutorProvisioner
	authz    ExecutorAuthz
	seeder   ExecutorSeeder
	clusters ExecutorClusters
	events   ExecutorLifecycle
	cfg      ExecutorConfig
	// stageAges tracks emitted stage-age series so a drained combination is
	// zeroed once (see stageAgeSeries). Zero value is ready to use.
	stageAges stageAgeSeries
}

// NewExecutor wires an Executor. Every dep is required; the constructor
// errors on gaps so serve-mode boot fails loudly rather than the executor
// nil-panicking mid-claim.
func NewExecutor(intents *Service, registry ExecutorRegistry, bridge ExecutorProvisioner, authz ExecutorAuthz, seeder ExecutorSeeder, clusters ExecutorClusters, events ExecutorLifecycle, cfg ExecutorConfig) (*Executor, error) {
	switch {
	case intents == nil:
		return nil, errors.New("nativemirror executor: intents store is nil")
	case registry == nil:
		return nil, errors.New("nativemirror executor: registry is nil")
	case bridge == nil:
		return nil, errors.New("nativemirror executor: provision bridge is nil")
	case authz == nil:
		return nil, errors.New("nativemirror executor: authz is nil")
	case seeder == nil:
		return nil, errors.New("nativemirror executor: seed publisher is nil")
	case clusters == nil:
		return nil, errors.New("nativemirror executor: cluster store is nil")
	case events == nil:
		return nil, errors.New("nativemirror executor: lifecycle emitter is nil")
	case cfg.Jurisdiction == "":
		return nil, errors.New("nativemirror executor: jurisdiction is required")
	case cfg.ClaimedBy == "":
		return nil, errors.New("nativemirror executor: claimed-by identity is required")
	case !intents.CanPublishRegistrations():
		return nil, errors.New("nativemirror executor: intents store has no registry publisher; pass nativemirror.WithRegistryPublisher")
	}
	cfg = cfg.withDefaults()
	return &Executor{
		intents:  intents,
		registry: registry,
		bridge:   bridge,
		authz:    authz,
		seeder:   seeder,
		clusters: clusters,
		events:   events,
		cfg:      cfg,
	}, nil
}

// Run polls for claimable intents until ctx is done. Fits the serve-mode
// subsystem contract (func(ctx) error, exits only on cancellation).
func (e *Executor) Run(ctx context.Context) error {
	ticker := time.NewTicker(e.cfg.Interval)
	defer ticker.Stop()
	for {
		// Sampled before draining so the first sample lands at boot rather than
		// one interval later; a failure only warns and retries next tick.
		if err := e.RecordStageAges(ctx); err != nil {
			slogutil.Warn(ctx, "native-mirror executor: intent stage-age sample failed",
				slog.String("jurisdiction", e.cfg.Jurisdiction),
				slog.String("error", err.Error()))
		}
		// Drain the backlog: keep claiming until nothing is eligible.
		for {
			progressed, err := e.RunOnce(ctx)
			if err != nil {
				slogutil.Error(ctx, "native-mirror executor: pass failed", slog.String("error", err.Error()))
				break
			}
			if !progressed {
				break
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

// RecordStageAges samples this jurisdiction's unfinished intents and emits the
// stage-age gauge (COR-1271). Called on every Run tick: this loop is the one
// per-jurisdiction cadence already scoped to exactly these rows, so the signal
// needs no subsystem or configuration of its own — and it is the right scope,
// not just the convenient one, since ENTIRE_NATIVE_MIRROR_ENABLED must stay
// true while a jurisdiction holds an unconverged intent (see its config doc).
//
// Best-effort: the caller warns and the next tick retries, because a telemetry
// read must never stop intents from draining. A failed sample returns BEFORE
// the drained-series bookkeeping — a database error is not evidence that
// anything converged, and zeroing on it would report "nothing pending" for
// intents that are still there.
func (e *Executor) RecordStageAges(ctx context.Context) error {
	samples, err := e.intents.SampleIntentStageAges(ctx, e.cfg.Jurisdiction)
	if err != nil {
		return fmt.Errorf("sample intent stage ages: %w", err)
	}
	recordIntentStageAges(ctx, e.cfg.Jurisdiction, e.stageAges.withDrainedZeros(samples))
	return nil
}

// RunOnce claims at most one intent and drives it. Returns whether a row was
// claimed (progressed or retried) so Run can drain backlogs eagerly.
func (e *Executor) RunOnce(ctx context.Context) (bool, error) {
	row, ok, err := e.intents.Claim(ctx, e.cfg.ClaimedBy, e.cfg.Jurisdiction, e.cfg.Lease)
	if err != nil {
		return false, fmt.Errorf("claim: %w", err)
	}
	if !ok {
		return false, nil
	}
	if row.DesiredState == DesiredDeleted {
		if err := e.teardown(ctx, row); err != nil {
			if errors.Is(err, errStageLost) {
				if rerr := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); rerr != nil {
					return true, fmt.Errorf("release after lost teardown fence: %w", rerr)
				}
				return true, nil
			}
			// Teardown is never marked permanently failed: it must converge or
			// account erasure (BeginPrimaryErasure) never drains. But a teardown
			// that keeps failing would otherwise be invisible, so past
			// StuckThreshold attempts emit an escalation the operator can alert
			// on — this is the recovery signal the v1 reconciler otherwise lacks.
			if row.Attempts >= e.cfg.StuckThreshold {
				slogutil.Error(ctx, "native-mirror executor: teardown stuck; manual recovery may be required (blocks account-erasure drain)",
					slog.String("placement_id", row.ID.String()),
					slog.String("cluster_slug", row.ClusterSlug),
					slog.String("stage", row.Stage),
					slog.Int64("attempts", row.Attempts),
					slog.String("error", err.Error()))
			} else {
				slogutil.Error(ctx, "native-mirror executor: teardown step failed; will retry",
					slog.String("placement_id", row.ID.String()),
					slog.String("stage", row.Stage),
					slog.String("error", err.Error()))
			}
			if rerr := e.intents.RecordRetry(ctx, row.ID, e.cfg.ClaimedBy, err.Error(), e.cfg.RetryBackoff); rerr != nil {
				return true, fmt.Errorf("record teardown retry: %w (after: %w)", rerr, err)
			}
		}
		return true, nil
	}
	if row.DesiredState != DesiredActive {
		return true, fmt.Errorf("unsupported desired state %q", row.DesiredState)
	}
	if err := e.execute(ctx, row); err != nil {
		// A lost fenced CAS is not a failure — the row moved under us
		// (deletion flipped mid-flight, or another executor won). Drop the
		// claim (fenced; a no-op if we no longer hold it) and let the next
		// claimer re-read. Crucially do NOT RecordRetry here: RecordRetry
		// would stamp a misleading last_error attributing the lost race to a
		// failure and bump attempts on a row we no longer own. (A deleted row
		// re-surfaces on the next drain iteration and is backed off there via
		// the non-active branch — so the deferral is a beat, not permanent;
		// the point is only that THIS lost CAS is not itself a failure.)
		if errors.Is(err, errStageLost) {
			slogutil.Info(ctx, "native-mirror executor: stage transition lost, releasing claim for re-read",
				slog.String("placement_id", row.ID.String()),
				slog.String("stage", row.Stage))
			if rerr := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); rerr != nil {
				return true, fmt.Errorf("release after lost stage: %w", rerr)
			}
			return true, nil
		}
		// Classify: a validation-class error can never succeed on retry, and a
		// row that has burned through MaxCreationAttempts is treated the same —
		// EXCEPT an uncapped step (the announce step), which retries
		// indefinitely because permafailing completed work is worse than
		// holding it. Capped failures are marked permanently failed (fenced) so
		// Claim stops returning the row — ending the flat-backoff hot loop —
		// and the failure surfaces on the status API (status=failed,
		// last_error, creation_failed_at). A repeated POST (ResetForRetry)
		// re-arms it. row.Attempts already counts this execution (Claim bumped
		// it).
		// Uncapped when the step says so (errRetryUncapped, set inside the
		// seeded branch) OR when the row was already at 'seeded' when claimed —
		// the latter covers the preamble loads (GroupPrimary, the data
		// primary's registration) failing on a fully-built placement, which
		// carry no sentinel because they are shared by all stages.
		uncapped := errors.Is(err, errRetryUncapped) || row.Stage == StageSeeded
		if errors.Is(err, errPermanentCreation) || (!uncapped && row.Attempts >= e.cfg.MaxCreationAttempts) {
			slogutil.Error(ctx, "native-mirror executor: creation permanently failed; halting retries",
				slog.String("placement_id", row.ID.String()),
				slog.String("stage", row.Stage),
				slog.Int64("attempts", row.Attempts),
				slog.Bool("validation_class", errors.Is(err, errPermanentCreation)),
				slog.String("error", err.Error()))
			marked, merr := e.intents.MarkFailedPermanent(ctx, row.ID, e.cfg.ClaimedBy, err.Error())
			if merr != nil {
				return true, fmt.Errorf("mark creation permanently failed: %w (after: %w)", merr, err)
			}
			if !marked {
				// The guard didn't match: deletion flipped desired_state under us
				// (teardown owns the row now) or our lease was already reclaimed.
				// In the deletion case MarkFailedPermanent left our claim in place,
				// so release it — otherwise the teardown leg cannot reclaim until
				// the lease expires, delaying erasure drain and interactive delete.
				// Release is fenced, so it is a no-op if we no longer hold the claim.
				if rerr := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); rerr != nil {
					return true, fmt.Errorf("release after unmarked permanent-fail: %w (after: %w)", rerr, err)
				}
			}
			return true, nil
		}
		// An uncapped step retrying past StuckThreshold is otherwise invisible
		// (it never permafails), so it emits the same escalation signal as a
		// stuck teardown.
		if uncapped && row.Attempts >= e.cfg.StuckThreshold {
			slogutil.Error(ctx, "native-mirror executor: announce stuck; the placement is built but its terminal CAS and created-event enqueue keep failing",
				slog.String("placement_id", row.ID.String()),
				slog.String("stage", row.Stage),
				slog.Int64("attempts", row.Attempts),
				slog.String("error", err.Error()))
		} else {
			slogutil.Error(ctx, "native-mirror executor: creation step failed; will retry",
				slog.String("placement_id", row.ID.String()),
				slog.String("stage", row.Stage),
				slog.Int64("attempts", row.Attempts),
				slog.String("error", err.Error()))
		}
		if rerr := e.intents.RecordRetry(ctx, row.ID, e.cfg.ClaimedBy, err.Error(), e.cfg.RetryBackoff); rerr != nil {
			return true, fmt.Errorf("record retry: %w (after: %w)", rerr, err)
		}
		return true, nil
	}
	// Reached announced (execute only returns nil there). Release the claim:
	// AdvanceStage moves stage but leaves claimed_by/claimed_at set, and an
	// announced+active row is otherwise excluded from re-claim, so a later
	// desired_state=deleted flip would have to wait out the full lease before
	// a teardown could claim it. Releasing frees it immediately.
	if err := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); err != nil {
		return true, fmt.Errorf("release after announce: %w", err)
	}
	return true, nil
}

// teardown removes every placement-owned resource before deleting the durable
// intent. Every external step is idempotent, so a crash or lease expiry can
// replay the whole sequence. The final row delete is fenced: a worker that lost
// its lease may finish harmless cleanup calls, but cannot erase the new owner's
// retry anchor.
func (e *Executor) teardown(ctx context.Context, row NativeMirror) error {
	if _, err := e.bridge.Delete(ctx, row.ID, row.ClusterSlug); err != nil {
		switch {
		case errors.Is(err, repoadmin.ErrNotFound):
			// Already gone: continue the idempotent control-plane cleanup.
		case errors.Is(err, repoadmin.ErrUnknownCluster):
			// Decommissioned clusters are deliberately absent from the bridge,
			// but their teardown rows remain claimable so account erasure and
			// data-primary deletion can converge. Decommissioning already requires
			// an empty repo_registry; any surviving pre-registration storage is
			// on the retired data plane and cannot be reached from this core.
			slogutil.Warn(ctx, "native-mirror executor: target cluster absent during teardown; continuing control-plane cleanup",
				slog.String("placement_id", row.ID.String()),
				slog.String("cluster_slug", row.ClusterSlug))
		default:
			return fmt.Errorf("delete data-plane repo: %w", err)
		}
	}
	if err := e.registry.UnpublishRepo(ctx, row.ID); err != nil && !errors.Is(err, registry.ErrNotFound) {
		return fmt.Errorf("unpublish placement registration: %w", err)
	}
	if err := e.authz.NativeMirrorPlacementDeleted(ctx, row.ID); err != nil {
		return fmt.Errorf("delete native-mirror authorization relationships: %w", err)
	}

	// The native-mirror lifecycle consumer handles activation only. Placement
	// removal uses the existing repo.deleted arm so entire-api drops its local
	// repos row and settings exactly like any other deleted placement. This is
	// the low-latency best-effort attempt; intents.Delete atomically replaces
	// the intent with a durable repo-deletion outbox row, whose relay retries
	// through PubAck after a loss or crash.
	e.events.Publish(ctx, resourceevents.TypeRepo, row.ID.String(), resourceevents.OpDeleted, "",
		resourceevents.WithJurisdiction(e.cfg.Jurisdiction))

	deleted, err := e.intents.Delete(ctx, row.ID, e.cfg.ClaimedBy)
	if err != nil {
		return fmt.Errorf("delete intent: %w", err)
	}
	if !deleted {
		return fmt.Errorf("delete intent: %w", errStageLost)
	}
	slogutil.Info(ctx, "native-mirror executor: placement deleted",
		slog.String("placement_id", row.ID.String()),
		slog.String("cluster_slug", row.ClusterSlug))
	return nil
}

// errStageLost marks a fenced stage CAS that found the row moved under us —
// another executor won, or desired_state flipped. The claim is simply
// released; the next claimer re-reads current state.
var errStageLost = errors.New("stage transition lost")

// execute drives one claimed, active intent to announced. No side effect lands
// after the stage that publishes it: the data-plane repo before `provisioned`,
// the authz tuple before `registered` and the registry row with it.
func (e *Executor) execute(ctx context.Context, row NativeMirror) error {
	// GroupPrimary's own query constrains forge = 'entire', so dataPrimary.ID
	// is already the model.RepoID both ExecutorRegistry and ExecutorAuthz
	// need — no re-parsing required.
	dataPrimary, err := e.intents.GroupPrimary(ctx, row.RepoGroupID)
	if err != nil {
		return fmt.Errorf("resolve group data primary: %w", err)
	}
	dataPrimaryReg, err := e.registry.GetRepoRegistration(ctx, dataPrimary.ID)
	if err != nil {
		return fmt.Errorf("load data-primary registration: %w", err)
	}
	// Resolved once here: StagePending (Provision) and StageRegistered (the
	// seed job) both need it and can run on separate passes.
	home, err := e.clusters.GetBySlugGlobal(ctx, dataPrimaryReg.ClusterSlug)
	if err != nil {
		return fmt.Errorf("resolve data-primary home cluster %q: %w", dataPrimaryReg.ClusterSlug, err)
	}
	if home.InternalURL == "" {
		return fmt.Errorf("data-primary home cluster %q has no internal URL", dataPrimaryReg.ClusterSlug)
	}
	internalURL := gitjobs.EntireDBSourceURL(home.InternalURL, dataPrimary.ID.String())

	stage := row.Stage
	if stage == StagePending {
		// The placement serves the same public path as the data primary; the
		// intent's url column is the data primary's public URL, so its path IS
		// the placement's routing path on the target cluster.
		parsed, err := url.Parse(row.URL)
		if err != nil || parsed.Path == "" {
			// Immutable snapshot of the data primary's URL — retrying cannot
			// fix a malformed one, so fail permanently rather than hot-loop to
			// the cap.
			return fmt.Errorf("intent url %q has no usable path: %w", row.URL, errPermanentCreation)
		}
		// Auto-rooting on create is disabled, so a native-mirror placement
		// provisions the disabled trust intent (ADR 20260724-rsl-root-of-trust-mvp):
		// it is rooted out-of-band by the operator run that roots its data
		// primary, not automatically at create time. ProvisionTrustIntent is
		// the single source of this classification (row.URL is the data
		// primary's public URL, the native-mirror slot).
		if err := e.bridge.Provision(ctx, row.ClusterSlug, model.ProvisionParams{
			RepoID:                         row.ID,
			URL:                            parsed.Path,
			ObjectFormat:                   row.ObjectFormat,
			RepoGroupID:                    row.RepoGroupID.String(),
			DefaultBranch:                  row.DefaultBranch,
			NativeMirrorPrimaryURL:         row.URL,
			NativeMirrorPrimaryInternalURL: internalURL,
			TrustLifecycle:                 repoadmin.ProvisionTrustIntent("", 0, row.URL),
			// A native group's namespace owner is its data primary
			// (COR-1564), reached over the same two URLs resolved above.
			// Stamped as a replica, so the namespace forwards rather than
			// accepting locally.
			EntireDataPrimary: model.EntireDataPrimaryStamp{
				URL:         row.URL,
				InternalURL: internalURL,
			},
		}); err != nil {
			return fmt.Errorf("provision data-plane repo: %w", err)
		}
		if stage, err = e.advance(ctx, row.ID, StagePending, StageProvisioned); err != nil {
			return err
		}
	}
	if stage == StageProvisioned {
		// Outside the transaction below: no SpiceDB round trip across the
		// repo_group lock. A lost fence leaks a tuple that blocks nothing.
		if err := e.authz.NativeMirrorPlacementRegistered(ctx, row.ID, row.RepoGroupID); err != nil {
			return fmt.Errorf("write native-mirror group relationship: %w", err)
		}
		// Register commits the publish with the fenced CAS (COR-1698): a racing
		// MarkDesiredDeleted rolls this back, or loses and teardown removes both.
		ok, err := e.intents.Register(ctx, row.ID, e.cfg.ClaimedBy, model.RepoRegistration{
			ID:              row.ID,
			OwningProjectID: dataPrimaryReg.OwningProjectID,
			Name:            dataPrimaryReg.Name,
			Jurisdiction:    e.cfg.Jurisdiction,
			ClusterSlug:     row.ClusterSlug,
			RepoGroupID:     row.RepoGroupID,
		})
		if err != nil {
			return fmt.Errorf("register placement: %w", err)
		}
		if !ok {
			return fmt.Errorf("advance %s→%s: %w", StageProvisioned, StageRegistered, errStageLost)
		}
		stage = StageRegistered
	}
	if stage == StageRegistered {
		if err := e.seeder.PublishEntireDBSyncRepo(ctx,
			gitjobs.Placement{Jurisdiction: e.cfg.Jurisdiction, ClusterID: row.ClusterSlug},
			gitjobs.Source{URL: internalURL},
			gitjobs.Target{ULID: row.ID.String()},
		); err != nil {
			return fmt.Errorf("publish seed sync job: %w", err)
		}
		if stage, err = e.advance(ctx, row.ID, StageRegistered, StageSeeded); err != nil {
			return err
		}
	}
	if stage == StageSeeded {
		// EVERY failure in this block is UNCAPPED (errRetryUncapped): at
		// 'seeded' every resource is already built and replicating, so
		// counting a transient project-load or transaction error against
		// MaxCreationAttempts could permafail a finished mirror — which drops
		// it from serving and leaves an event nothing republishes.
		project, err := e.registry.GetProject(ctx, dataPrimaryReg.OwningProjectID)
		if err != nil {
			return fmt.Errorf("load data-primary project: %w (%w)", err, errRetryUncapped)
		}
		// native_mirror.created is the sole trigger that seeds entire-api's
		// product-layer row; an empty mirror emits no ref event to re-create
		// it and the resync sweep repairs sync lag, never a missing
		// projection. Durability therefore lives in the created outbox: the
		// fully marshaled event is enqueued in the SAME transaction as the
		// terminal CAS (Announce), and the relay republishes it with PubAck
		// until acknowledged — the event is delivered iff the placement
		// announced, at least once, even across a crash right here. A
		// disabled emitter no longer needs special-casing: rows simply queue,
		// and the outbox backlog telemetry exposes the gap.
		opts := []resourceevents.PublishOption{
			resourceevents.WithJurisdiction(e.cfg.Jurisdiction),
			resourceevents.WithMirrorMeta(row.RepoGroupID.String(), dataPrimaryReg.OwningProjectID.String(), project.Name+"/"+dataPrimaryReg.Name, row.ClusterSlug),
			// WithPrimaries(gitDataPrimary, processingPrimary): an entire-forge
			// group's processing primary is stamped once at creation to the
			// same value as its data primary and never re-elected, so both
			// arguments here are the same dataPrimary.
			resourceevents.WithPrimaries(dataPrimary.String(), dataPrimary.ID.String()),
		}
		// The executor runs after the request, so the actor is the creator the
		// intent row recorded. It is empty for rows without one.
		msg, err := resourceevents.NewMessage(e.cfg.Jurisdiction,
			resourceevents.TypeNativeMirror, row.ID.String(), resourceevents.OpCreated, row.CreatedByAccountID, opts...)
		if err != nil {
			return fmt.Errorf("marshal native_mirror.created: %w (%w)", err, errRetryUncapped)
		}
		ok, err := e.intents.Announce(ctx, row.ID, e.cfg.ClaimedBy, e.cfg.Jurisdiction, CreatedEvent{
			MsgID:   createdEventMsgID(row.ID),
			Subject: msg.Subject,
			Payload: msg.Data,
		})
		if err != nil {
			return fmt.Errorf("announce: %w (%w)", err, errRetryUncapped)
		}
		if !ok {
			return fmt.Errorf("advance %s→%s: %w", StageSeeded, StageAnnounced, errStageLost)
		}
		// Low-latency best-effort duplicate of the event the transaction above
		// just made durable, mirroring teardown's repo.deleted pattern: the
		// consumer sees the placement within a NATS round trip instead of the
		// relay's next tick. The stream's msg-id dedup does not apply here (no
		// msg id on the core-NATS path), but the consumer is idempotent, so
		// the duplicate is harmless.
		e.events.Publish(ctx, resourceevents.TypeNativeMirror, row.ID.String(), resourceevents.OpCreated, row.CreatedByAccountID, opts...)
	}
	slogutil.Info(ctx, "native-mirror executor: placement announced",
		slog.String("placement_id", row.ID.String()),
		slog.String("cluster_slug", row.ClusterSlug),
		slog.String("data_primary_id", dataPrimary.ID.String()))
	return nil
}

// advance runs one fenced stage CAS and returns the reached stage. A lost
// CAS (fence or stage mismatch, desired_state flipped, row suspended) is
// errStageLost — the caller's retry path releases the claim and the next
// claimer re-reads.
func (e *Executor) advance(ctx context.Context, id model.RepoID, from, to string) (string, error) {
	ok, err := e.intents.AdvanceStage(ctx, id, e.cfg.ClaimedBy, from, to)
	if err != nil {
		return "", fmt.Errorf("advance %s→%s: %w", from, to, err)
	}
	if !ok {
		return "", fmt.Errorf("advance %s→%s: %w", from, to, errStageLost)
	}
	return to, nil
}

package nativemirror

import (
	"context"
	"errors"
	"fmt"

	"log/slog"

	"github.com/jackc/pgx/v5"

	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/core/resource"
	"entire.io/postgres"
	"entire.io/slogutil"
)

// RoutingPlacement is one placement in a native-mirror-routing answer: the
// placement's repo ULID, where it lives, and whether it is safe to READ
// from. The repolookup Connect handler maps the addressing fields onto the
// wire Placement message; ReadEligible has no wire counterpart because that
// RPC's only consumer is replication fan-out.
type RoutingPlacement struct {
	RepoID       model.RepoID
	Jurisdiction string
	ClusterSlug  string
	// ReadEligible is the readEligible predicate's answer for this row —
	// strictly narrower than membership in Routing.NativeMirrors.
	ReadEligible bool
}

// Routing is LookupNativeMirrorsByRepoID's store-level answer.
type Routing struct {
	Home RoutingPlacement
	// NativeMirrors lists placements matching replicationFilter, ordered by
	// (jurisdiction, cluster_slug). Empty for mirror-group and ungrouped
	// repos — those route elsewhere. Membership is deliberately not a
	// statement that the placement holds content: read consumers gate on
	// each placement's ReadEligible.
	NativeMirrors []RoutingPlacement
	// NamespaceMirrors lists the replication targets for the Entire-owned
	// ref namespace of a github group whose owner is live: every other
	// placement of the group that is ready, active and unsuspended, ordered
	// by (jurisdiction, cluster_slug). Disjoint from NativeMirrors — a group
	// populates at most one list. ReadEligible is left false throughout: it
	// answers a native_mirrors predicate, and membership here already
	// requires the placement to be ready.
	NamespaceMirrors []RoutingPlacement
	// SourceURL is the home cluster's INTERNAL by-ID git URL for the
	// group's primary; empty when the group is not an entire group or the
	// home cluster has no internal URL registered.
	SourceURL string
}

// replicationFilter is REPLICATION eligibility: the placement is registered
// (or beyond), not marked for deletion, not suspended, and not permanently
// failed. Matches the plan's "stage >= registered" gate — fan-out jobs must
// never target a half-created, deleting, or dead placement. The
// creation_failed_at exclusion matters because a creation can permafail AT a
// serving stage (e.g. the seed publish caps out at 'registered', when the
// mirror is still empty): without it, fan-out would keep publishing sync jobs
// at a placement the control plane itself has declared failed, indefinitely.
// ResetForRetry clears the mark and re-admits the row here.
//
// This is NOT the read gate, and cannot be tightened into one (COR-1356).
// Replication must reach a placement from the moment it is registered and
// throughout its initial sync — that traffic is what MAKES it converge — so
// the stage set has to admit rows that hold nothing yet. 'seeded' in
// particular says only that the initial sync_repo job was PUBLISHED, not
// that it finished: for a large repo the clone runs long afterwards, and a
// read routed there for the whole of that window answers with an empty or
// partially-synced repo. Reads gate on readEligible instead.
const replicationFilter = `nr.stage IN ('registered', 'seeded', 'announced')
   AND nr.desired_state = 'active' AND nr.suspended_at IS NULL
   AND nr.creation_failed_at IS NULL`

// readEligible is READ eligibility: everything replication requires, AND
// proof the placement has actually converged — status = 'ready', which
// ApplyCompletionStatus stamps off the worker's mirror_done completion. The
// status clause is an ADDITIONAL condition, never a replacement: 'ready'
// speaks only about the last sync, and says nothing about deletion intent,
// suspension, or a permanently-failed creation, each of which must still
// exclude the row.
//
// 'ready' is a stable gate rather than a flapping one: the failed arm of
// ApplyCompletionStatus matches only a 'processing' row, so a converged
// placement never regresses on a later sync failure, and the two writers
// that do return status to 'processing'/'suspended' (ResetForRetry, guarded
// on creation_failed_at IS NOT NULL, and MarkDesiredDeleted) are already
// excluded by the replication clauses above. A placement therefore keeps
// serving reads across resyncs; it does not drop out of the read set on
// every write to the primary.
//
// Parenthesised for the same reason completionEligible is: it is a bare AND
// chain, and it is spliced into a SELECT list as a projected boolean, where
// losing the grouping would silently WIDEN what counts as readable — the
// over-claim direction.
const readEligible = `(` + replicationFilter + `
   AND nr.status = 'ready')`

// ResolveRouting resolves any placement's repo id to its group's home
// placement, replication-eligible native mirrors (each carrying its own
// ReadEligible bit), and fetch source. A github group that has a namespace
// owner answers the namespace shape instead (see namespaceRouting); every
// other non-entire group and every ungrouped row resolves to home = the
// row's own placement with nothing to replicate (whole-repo GitHub mirroring
// routes through LookupByMirror). Returns ErrNotFound when no registry row
// exists for repoID.
func (s *Service) ResolveRouting(ctx context.Context, repoID model.RepoID) (Routing, error) {
	// One read resolves the row, its group identity, and — via the group's
	// data_primary_repo_id — the primary's own registry row and cluster.
	var (
		ownJur, ownSlug   string
		forge, primaryID  *string
		namespaceOwner    *string
		homeJur, homeSlug *string
		homeInternalURL   *string
	)
	// g is INNER: r.repo_group_id is NOT NULL with a FK to repo_group(id).
	// pr stays LEFT: g.data_primary_repo_id has no FK, and the primary's own
	// registry row can be gone mid-teardown (see below).
	err := s.pool.QueryRow(ctx,
		`SELECT r.jurisdiction, COALESCE(r.cluster_slug, ''),
		        g.forge, g.data_primary_repo_id, g.entire_data_primary,
		        pr.jurisdiction, pr.cluster_slug,
		        hc.internal_url
		 FROM repo_registry r
		 JOIN repo_group g ON g.id = r.repo_group_id
		 LEFT JOIN repo_registry pr ON g.forge = 'entire' AND pr.id = g.data_primary_repo_id
		 LEFT JOIN clusters hc ON hc.slug = pr.cluster_slug
		 WHERE r.id = $1`,
		repoID,
	).Scan(&ownJur, &ownSlug, &forge, &primaryID, &namespaceOwner, &homeJur, &homeSlug, &homeInternalURL)
	if errors.Is(err, pgx.ErrNoRows) {
		return Routing{}, ErrNotFound
	}
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s: %w", repoID, err)
	}

	self := RoutingPlacement{RepoID: repoID, Jurisdiction: ownJur, ClusterSlug: ownSlug}
	if forge != nil && *forge == "github" && namespaceOwner != nil && primaryID != nil {
		return leaseholderFallback(ctx, repoID, s.reads.AOST(), func(aost postgres.AOST) (Routing, error) {
			return s.namespaceRouting(ctx, repoID, self, *namespaceOwner, *primaryID, aost)
		})
	}
	if forge == nil || *forge != "entire" || primaryID == nil || homeJur == nil {
		// Mirror group, ungrouped row, or a group whose primary's registry
		// row is gone mid-teardown: nothing to mirror from here.
		return Routing{Home: self}, nil
	}
	primaryRepoID, err := model.ParseRepoID(*primaryID)
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s: primary id %q: %w", repoID, *primaryID, err)
	}
	home := RoutingPlacement{RepoID: primaryRepoID, Jurisdiction: *homeJur}
	if homeSlug != nil {
		home.ClusterSlug = *homeSlug
	}

	routing := Routing{Home: home}
	if homeInternalURL != nil && *homeInternalURL != "" {
		routing.SourceURL = gitjobs.EntireDBSourceURL(*homeInternalURL, *primaryID)
	}

	// readEligible rides along as a projected boolean rather than a second
	// query, and deliberately repeats the WHERE clause's replication terms
	// instead of narrowing to `nr.status = 'ready'` alone: ReadEligible then
	// carries the whole read gate on its own, so widening the filter later
	// can never quietly widen what the read path accepts.
	rows, err := s.pool.Query(ctx,
		`SELECT nr.id, c.jurisdiction, nr.cluster_slug, `+readEligible+`
		 FROM native_mirrors nr
		 JOIN repo_group g ON g.id = nr.repo_group_id
		 JOIN clusters c ON c.slug = nr.cluster_slug
		 WHERE g.forge = 'entire' AND g.data_primary_repo_id = $1
		   AND `+replicationFilter+`
		 ORDER BY c.jurisdiction, nr.cluster_slug`,
		*primaryID,
	)
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s (native mirrors): %w", repoID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var p RoutingPlacement
		if err := rows.Scan(&p.RepoID, &p.Jurisdiction, &p.ClusterSlug, &p.ReadEligible); err != nil {
			return Routing{}, fmt.Errorf("nativemirror: scan native-mirror placement: %w", err)
		}
		routing.NativeMirrors = append(routing.NativeMirrors, p)
	}
	if err := rows.Err(); err != nil {
		return Routing{}, fmt.Errorf("nativemirror: iterate native-mirror placements: %w", err)
	}
	return routing, nil
}

// errFollowerMiss: the follower snapshot has no owner row yet. Never returned
// to a caller; leaseholderFallback reads fresh instead.
var errFollowerMiss = errors.New("nativemirror: namespace owner not yet follower-visible")

// leaseholderFallback runs read at first, the follower clause in production,
// and, when that snapshot has no owner row yet or the read itself fails, once
// more against the leaseholder. A cancelled context is returned as is: the fresh
// read would fail the same way. The miss is silent (a placement elected
// within the follower lag is expected); any other follower error is logged,
// because a cluster that cannot serve follower reads would otherwise degrade
// to a double read without anyone noticing.
func leaseholderFallback(ctx context.Context, repoID model.RepoID, first postgres.AOST, read func(postgres.AOST) (Routing, error)) (Routing, error) {
	routing, err := read(first)
	if err == nil || ctx.Err() != nil {
		return routing, err
	}
	if !errors.Is(err, errFollowerMiss) {
		slogutil.Warn(ctx, "nativemirror: namespace routing follower read failed, falling back to leaseholder read",
			slog.String("repo_id", repoID.String()), slog.String("error", err.Error()))
	}
	return read(postgres.CurrentReadAOST)
}

// namespaceRouting answers for a github group that names a namespace owner:
// home is the owner placement — the only writer of refs/heads/entire/native/*
// for the group — and NamespaceMirrors is every OTHER placement of the same
// upstream that has converged, so a fan-out at the owner's cell replicates the
// namespace to each. NativeMirrors stays empty: a github group has none, and a
// fanout that ignores NamespaceMirrors must therefore publish nothing.
//
// Membership requires status = 'ready' rather than the looser stage gate
// native mirrors use, because nothing here seeds a placement: a mirror still
// importing from GitHub has no namespace to converge, and its seed (COR-1646)
// is what admits it.
//
// The mirror list is empty whenever the owner cannot serve the fetch, so no
// job is published against a source that would refuse it. Two shapes say so,
// and the difference is loop prevention: an owner whose row is gone, marked
// for deletion, on a cluster with no row, or naming another upstream falls
// back to the shape the group answered before it had one, while a SUSPENDED
// owner still comes back as home. A replica cell compares home against itself to decide whether to drop
// an event, so dropping the owner from home would make some other cell
// conclude it is home and replicate from the wrong side. Suspension lifts on
// its own, and the owner's next namespace write resumes replication; the
// namespace is read-only for the group until owner migration ships (COR-1564).
//
// Both reads are served AS OF SYSTEM TIME follower_read_timestamp() (COR-1771).
// mirror_repos is REGIONAL BY ROW, so a group's siblings are homed in other
// regions and a leaseholder read of them is one cross-region round trip per
// region: 200 ms to 1.2 s per lookup, on the fanout's per-ref-event path. The
// follower answer is ~4.8 s stale, which the fanout already tolerates by
// caching each answer for 60 s. A sibling that converged inside that window
// is missed for one answer; its own seed (COR-1646) admits it regardless.
// An owner row the follower cannot see yet is errFollowerMiss, and the caller
// reads fresh: a placement that became owner within seconds of creation must
// not be answered as ownerless.
func (s *Service) namespaceRouting(ctx context.Context, repoID model.RepoID, fallback RoutingPlacement, ownerID, githubRepoID string, aost postgres.AOST) (Routing, error) {
	var (
		ownerJur, ownerSlug string
		internalURL         *string
	)
	// entire_data_primary has no foreign key, and the sibling query below
	// keys on the OWNER's upstream. An owner naming a placement of another
	// upstream would therefore route this group's pushes to a foreign
	// placement and fan out that upstream's siblings, so the owner must
	// prove it belongs to this group. github_repo_id is INT8 and
	// data_primary_repo_id is TEXT (migration 029); the row is already pinned by
	// primary key, so casting the column costs no index.
	err := s.pool.QueryRow(ctx,
		`SELECT c.jurisdiction, o.cluster_slug, c.internal_url
		   FROM mirror_repos o
		   JOIN clusters c ON c.slug = o.cluster_slug
		  `+string(aost)+`
		  WHERE o.id = $1 AND o.github_repo_id::STRING = $2
		    AND o.desired_state <> 'deleted'`,
		ownerID, githubRepoID,
	).Scan(&ownerJur, &ownerSlug, &internalURL)
	if errors.Is(err, pgx.ErrNoRows) {
		if aost != postgres.CurrentReadAOST {
			return Routing{}, errFollowerMiss
		}
		return Routing{Home: fallback}, nil
	}
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s (namespace owner): %w", repoID, err)
	}
	ownerRepoID, err := model.ParseRepoID(ownerID)
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s: namespace owner %q: %w", repoID, ownerID, err)
	}

	routing := Routing{Home: RoutingPlacement{RepoID: ownerRepoID, Jurisdiction: ownerJur, ClusterSlug: ownerSlug}}
	if internalURL != nil && *internalURL != "" {
		routing.SourceURL = gitjobs.EntireDBSourceURL(*internalURL, ownerID)
	}

	rows, err := s.pool.Query(ctx,
		`SELECT m.id, c.jurisdiction, m.cluster_slug
		   FROM mirror_repos o
		   JOIN mirror_repos m ON m.github_repo_id = o.github_repo_id AND m.id <> o.id
		   JOIN clusters c ON c.slug = m.cluster_slug
		  `+string(aost)+`
		  WHERE o.id = $1 AND o.suspended_at IS NULL
		    AND m.status = 'ready' AND m.desired_state <> 'deleted'
		    AND m.suspended_at IS NULL
		  ORDER BY c.jurisdiction, m.cluster_slug`,
		ownerID,
	)
	if err != nil {
		return Routing{}, fmt.Errorf("nativemirror: resolve routing %s (namespace mirrors): %w", repoID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var p RoutingPlacement
		if err := rows.Scan(&p.RepoID, &p.Jurisdiction, &p.ClusterSlug); err != nil {
			return Routing{}, fmt.Errorf("nativemirror: scan namespace-mirror placement: %w", err)
		}
		routing.NamespaceMirrors = append(routing.NamespaceMirrors, p)
	}
	if err := rows.Err(); err != nil {
		return Routing{}, fmt.Errorf("nativemirror: iterate namespace-mirror placements: %w", err)
	}
	return routing, nil
}

// NativeMirrorInCluster returns the repo's read-eligible native-mirror
// placement in clusterSlug, if one exists. repoID may name any placement in
// the group — ResolveRouting resolves via the group's primary. This is the
// read path, so it gates on readEligible rather than on membership in
// Routing.NativeMirrors (COR-1356).
//
// A placement that is not read-eligible is OMITTED rather than answered with
// the group's primary. The consumer is the token-exchange audience resolver,
// which mints a token scoped to the PLACEMENT's ULID precisely because the
// mirror host's data plane exact-matches the token scope against its own
// local repo id; substituting the primary's id there yields a token that host
// refuses, i.e. an opaque failure at the mirror instead of a diagnosis.
// Reporting false instead falls through to the resolver's existing
// invalid_target hint, which names the home cluster and tells the client to
// re-target — one actionable error, and the content it then gets is correct.
//
// Repos with no registry row, mirror-group repos, and ungrouped repos all
// report false.
func (s *Service) NativeMirrorInCluster(ctx context.Context, repoID model.RepoID, clusterSlug string) (model.RepoID, bool, error) {
	routing, err := s.ResolveRouting(ctx, repoID)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return model.RepoID{}, false, nil
		}
		return model.RepoID{}, false, err
	}
	for _, m := range routing.NativeMirrors {
		// UNIQUE(repo_group_id, cluster_slug): at most one placement can
		// match, so an unready one is a definitive false, not a reason to
		// keep scanning for a readable sibling in the same cluster.
		if m.ClusterSlug == clusterSlug {
			if !m.ReadEligible {
				return model.RepoID{}, false, nil
			}
			return m.RepoID, true, nil
		}
	}
	return model.RepoID{}, false, nil
}

// GroupPrimary returns the data-primary identity of an entire-forge group —
// the group's data_primary_repo_id IS the data primary's repo id (ADR
// 20260715-repo-group-for-every-repo). The query itself constrains
// forge = 'entire', so this returns the concrete resource.EntireForgeRepo
// type rather than a forge-generic shape: the SQL already guarantees the
// forge, so the return value should carry that guarantee in its type, not
// repeat it as a runtime string a caller could get wrong. ErrNotFound when
// the group row is missing or belongs to another forge.
func (s *Service) GroupPrimary(ctx context.Context, groupID model.RepoGroupID) (resource.EntireForgeRepo, error) {
	var dataPrimaryRepoID string
	err := s.pool.QueryRow(ctx,
		`SELECT data_primary_repo_id FROM repo_group WHERE id = $1 AND forge = 'entire'`,
		groupID,
	).Scan(&dataPrimaryRepoID)
	if errors.Is(err, pgx.ErrNoRows) {
		return resource.EntireForgeRepo{}, ErrNotFound
	}
	if err != nil {
		return resource.EntireForgeRepo{}, fmt.Errorf("nativemirror: group primary %s: %w", groupID, err)
	}
	id, err := model.ParseRepoID(dataPrimaryRepoID)
	if err != nil {
		return resource.EntireForgeRepo{}, fmt.Errorf("nativemirror: group primary %s: data_primary_repo_id %q: %w", groupID, dataPrimaryRepoID, err)
	}
	return resource.EntireForgeRepo{ID: id}, nil
}

