// RepoLookup is the internal cross-jurisdictional directory: given upstream
// mirror coordinates, returns every (jurisdiction, cluster_slug) that
// mirrors them. Used by webhook ingest to fan a single upstream event out
// across the per-cluster NATS subjects defined by ADR 20260408.
//
// Auth: mTLS-only. The receiver listener gates by per-listener workload
// allowlist (ADR 20260501); there is no end-user identity in these calls.

syntax = "proto3";

package repolookup.v1;

option go_package = "entire.io/gen/proto/internalapi/repolookup/v1;repolookupv1";

service RepoLookup {
  // LookupByMirror resolves upstream mirror coordinates to every routable
  // placement that hosts a mirror of them. An upstream may be mirrored in
  // multiple jurisdictions/clusters; the response carries the full list,
  // ordered by (jurisdiction, cluster_slug).
  //
  // Placements without a cluster_slug (legacy rows still in the COR-138
  // backfill window) are filtered server-side and logged at warn level —
  // they are not addressable on per-cluster NATS subjects, so returning
  // them would silently route work nowhere. An empty response means no
  // routable mirror exists; it does not distinguish "no mirror at all"
  // from "all mirrors are still unstamped."
  rpc LookupByMirror(LookupByMirrorRequest) returns (LookupByMirrorResponse);

  // LookupMirrorByID is LookupByMirror's inverse: given a mirror's EntireDB
  // repo ULID, return the upstream coordinates (provider/owner/repo) it
  // mirrors. Callers that hold only the mirror_repos id — e.g. a consumer of a
  // resource_lifecycle_v1 mirror.created event, whose payload is a thin
  // resource_id-only projection — use it to recover the (owner, repo) they
  // need to act on the mirror (COR-717: seed github_repo_meta on mirror
  // creation). Returns CodeNotFound when no mirror_repos row matches the id (or
  // the placement is suspended); CodeInvalidArgument when repo_id is empty or
  // not a valid ULID.
  rpc LookupMirrorByID(LookupMirrorByIDRequest) returns (LookupMirrorByIDResponse);

  // LookupNativeMirrorsByRepoID resolves a repo id (any placement of a native
  // repo — primary or native mirror; the id a repo_refs_v1 ref event carries) to
  // its group's git-data HOME placement and every REPLICATION-eligible
  // native-mirror placement (ADR 20260720-native-mirroring). Replica fan-out
  // consumes this: it drops the event unless its local cluster is the home
  // (loop prevention), then publishes one sync job per native mirror.
  // source_url is the home cluster's INTERNAL by-ID git URL, computed here so
  // fanout and the worker stay source-agnostic; it is never user-facing.
  //
  // Native mirrors below the serving stage (still being created), suspended, or
  // marked for deletion are excluded. Placements that ARE listed may still hold
  // an empty or partially-synced repo — a placement is listed from the moment
  // it is registered, and that replication traffic is what makes it converge,
  // so this response is not a statement that a mirror can serve READS. Read
  // routing gates separately, on the placement having converged; do not reuse
  // this RPC to answer "where may I read this repo from". An ungrouped repo
  // resolves to home = its own placement with no mirrors of either kind. A
  // GitHub mirror group resolves the same way unless one of its placements
  // owns the group's git data, in which case home is that owner and the
  // siblings come back as namespace_mirrors (see below); full-repo GitHub
  // mirroring still routes through LookupByMirror, not here. CodeNotFound
  // when the repo id is unknown; CodeInvalidArgument when it is empty or not
  // a ULID.
  rpc LookupNativeMirrorsByRepoID(LookupNativeMirrorsByRepoIDRequest) returns (LookupNativeMirrorsByRepoIDResponse);
}

message LookupByMirrorRequest {
  // Upstream provider, e.g. "github". Required.
  string provider = 1;

  // Upstream owner segment (org or user), e.g. "octocat". Required.
  string owner = 2;

  // Upstream repo name, e.g. "hello-world". Required.
  string repo = 3;

  // GitHub's immutable numeric repo id, from the webhook's repository.id.
  // Optional; 0 means unknown. When set, only placements of that upstream are
  // returned: owner/repo can be stale on our side (a teardown leaked, then the
  // owner renamed away) and claimed by another GitHub account, whose events
  // must not route onto the old mirror (ENT-2822).
  int64 github_repo_id = 4;
}

message LookupByMirrorResponse {
  repeated Placement placements = 1;
}

message LookupMirrorByIDRequest {
  // Crockford Base32 ULID of the mirrored repo within EntireDB. Required.
  string repo_id = 1;
}

message LookupMirrorByIDResponse {
  // Upstream provider, e.g. "github". Always "github" today — mirror_repos
  // joins github_repos for its upstream coordinates.
  string provider = 1;

  // Upstream owner segment (org or user), e.g. "octocat".
  string owner = 2;

  // Upstream repo name, e.g. "hello-world".
  string repo = 3;
}

message Placement {
  // Crockford Base32 ULID of the mirrored repo within EntireDB.
  string repo_id = 1;

  // Jurisdiction that homes this mirror, e.g. "us" / "eu".
  string jurisdiction = 2;

  // Cluster slug within the jurisdiction that homes this mirror, e.g.
  // "royalcanin". Guaranteed non-empty: rows whose repo_registry row has
  // not yet been cluster-stamped are filtered out by the server before
  // the response is built (see service comment on LookupByMirror).
  string cluster_slug = 3;
}

message LookupNativeMirrorsByRepoIDRequest {
  // Crockford Base32 ULID of any placement of the repo. Required.
  string repo_id = 1;
}

message LookupNativeMirrorsByRepoIDResponse {
  // The group's git-data home placement — where pushes land.
  Placement home = 1;

  // Replication-eligible native-mirror placements, ordered by (jurisdiction,
  // cluster_slug). Empty for repos with no native mirrors (every repo
  // today). Listed placements are sync TARGETS, not necessarily readable
  // sources — see the RPC comment.
  repeated Placement native_mirrors = 2;

  // The home cluster's INTERNAL by-ID git URL for the primary
  // (https://<internal host>/git/repo/<primary ULID>) — the sync job's
  // fetch source. Empty when the home cluster has no internal URL
  // registered. Never user-facing.
  string source_url = 3;

  // Namespace-mirror placements: the other ready placements of a GitHub
  // group whose git data is owned by one of them (COR-1566). They receive
  // entiredb_ns sync jobs, which replicate ONLY the Entire-owned
  // refs/heads/entire/native/* namespace from source_url — the rest of
  // their ref state comes from GitHub. Ordered by (jurisdiction,
  // cluster_slug); empty for every group without an owner, and never
  // populated together with native_mirrors (a group is one kind or the
  // other).
  repeated Placement namespace_mirrors = 4;
}

package main

import (
	"context"
	"errors"
	"log/slog"
	"slices"
	"strings"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/refevents"
)

// Native-mirror trigger consumer (COR-1021): consumes the LOCAL cluster's
// repo_refs_v1 ref-event stream and publishes one mirror.git sync_repo job per
// serving native mirror of the pushed repo — the event-driven fast path that
// keeps native mirrors fresh. Enabled per cluster via
// FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED; a no-op while no native mirrors exist
// (every event resolves to an empty route set and Acks).
const (
	// nativeMirrorDurable is the pull-consumer durable on repo_refs_v1. A fixed
	// name (unlike FANOUT_DURABLE) is safe here because the stream itself is
	// per-cluster local — durables are stream-scoped, so two clusters' consumers
	// can never collide on one stream the way the shared US webhook stream's
	// could.
	nativeMirrorDurable = "native-mirror-fanout"

	// Retry envelope: same flat-NakWithDelay shape as the webhook consumer.
	// repo_refs_v1 is limits-retention, so an exhausted delivery is simply not
	// redelivered again (nothing orphans, nothing pins). A dropped event is
	// healed by the primary's next push — every sync replicates full ref
	// state — so no DLQ is wired (rev 11: v1 accepts "next push" as the
	// staleness RPO). No InactiveThreshold either: an abandoned durable on a
	// limits stream pins nothing.
	nativeMirrorFailureDelay = 30 * time.Second
	nativeMirrorMaxDeliver   = 8
	nativeMirrorAckWait      = 30 * time.Second
)

// Ack reasons for benign no-op dispositions, recorded on the completed metric
// so drops are observable without per-event logs (not_home fires on every
// worker-push echo in a mirror cluster; no_native_mirrors on every push in a
// home cluster — both far too hot to log).
const (
	ackReasonTlogRef      = "tlog_ref"          // transparency-log ref churn; the branch event triggers the sync
	ackReasonRepoNotFound = "repo_not_found"    // repo deleted between event publish and consume
	ackReasonNotHome      = "not_home"          // event echoed from a native-mirror placement (loop prevention)
	ackReasonNoMirrors    = "no_native_mirrors" // repo has no serving native mirrors (every repo today)

	// ackReasonNamespaceOutOfScope fires on a namespace group (a GitHub
	// group whose git data one placement owns): those placements replicate
	// only the Entire-owned namespace from here, so every other ref —
	// refs/heads/main, tags, HEAD symref moves — is acked without a job.
	// Hot on the owner cell: one per ordinary push.
	ackReasonNamespaceOutOfScope = "namespace_out_of_scope"
)

// namespaceRefPrefix is the Entire-owned branch namespace replicated by
// entiredb_ns jobs (COR-1566). The worker enforces the same scope on the
// sync itself; this filter only keeps the jobs off the stream.
const namespaceRefPrefix = "refs/heads/entire/native/"

// newNativeMirrorConsumer wires the ref-event resolver into the shared
// fanoutengine runtime. Same worker pool knobs and region map as the webhook
// consumer; no DLQ (see the retry-envelope comment above).
func newNativeMirrorConsumer(js nats.JetStreamContext, resolver *nativeMirrorSyncResolver, regions fanoutengine.Regions, metrics *fanoutMetrics, concurrency, fetchBatch int) *fanoutengine.Consumer {
	return fanoutengine.New(js, refEventDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:         refevents.NATSSubjectPrefix + ">",
		Stream:          refevents.NATSStreamName,
		Durable:         nativeMirrorDurable,
		Tracer:          tracerName,
		SpanName:        "fanout.native_mirror.dispatch",
		DestinationName: refevents.NATSStreamName,
		AckWait:         nativeMirrorAckWait,
		MaxDeliver:      nativeMirrorMaxDeliver,
		NakDelay:        nativeMirrorFailureDelay,
		SpanAttrs:       stampRefEventSpanAttrs,
		Concurrency:     concurrency,
		FetchBatch:      fetchBatch,
	})
}

// refEventDecoder turns a raw repo_refs_v1 delivery into the engine envelope.
// A decode failure → Term (bad envelope). Event carries the ref op so the
// completed metric's event attribute stays low-cardinality: the KNOWN wire
// vocabulary (create/update/delete/force_update/symref_update) passes
// through, anything else is clamped to "other" — Unmarshal tolerates
// newer-producer payloads by design, so the wire value is unbounded even
// though the payload is valid. DeliveryID is the producer's
// content+timestamp identity, which doubles as the engine's route-memo key.
type refEventDecoder struct{}

// eventOther stands in for a ref op outside the known vocabulary on the
// metric attribute, so a future producer op can't create unbounded metric
// cardinality. Spans/logs still carry the real op via the resolver.
const eventOther = "other"

var knownRefOps = map[string]bool{
	refevents.RefOpCreate:       true,
	refevents.RefOpUpdate:       true,
	refevents.RefOpDelete:       true,
	refevents.RefOpForceUpdate:  true,
	refevents.RefOpSymrefUpdate: true,
}

func (refEventDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	ev, err := refevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	event := ev.RefOp
	if !knownRefOps[event] {
		event = eventOther
	}
	return fanoutengine.Envelope{
		Event:      event,
		DeliveryID: ev.DeliveryID(),
		ObservedAt: ev.Timestamp,
		Body:       data,
	}, nil
}

// stampRefEventSpanAttrs stamps the envelope-level identity; the resolver adds
// the repo/ref attributes once it has re-decoded the body.
func stampRefEventSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("entire.ref_event.op", env.Event),
		attribute.String("entire.ref_event.delivery_id", env.DeliveryID),
	)
}

// nativeRouteResolver is the mirrorjobs.NativeMirrorResolver surface this
// consumer needs, narrowed for tests.
type nativeRouteResolver interface {
	NativeMirrorRoutes(ctx context.Context, repoID string) (mirrorjobs.NativeMirrorResolution, error)
}

// nativeMirrorSyncResolver resolves local ref events into mirror.git sync_repo
// routes, one per serving native mirror. It is the engine's Resolver for the
// native-mirror consumer.
//
// Loop prevention: a worker push into a native-mirror placement emits ref
// events on THAT cluster's repo_refs_v1 too. Those events resolve to a home
// cluster different from this consumer's local cluster and are dropped, so a
// sync can never trigger another sync. Only the home cluster — where user
// pushes land — fans out.
type nativeMirrorSyncResolver struct {
	routes         nativeRouteResolver
	localClusterID string
}

func newNativeMirrorSyncResolver(routes nativeRouteResolver, localClusterID string) *nativeMirrorSyncResolver {
	return &nativeMirrorSyncResolver{routes: routes, localClusterID: localClusterID}
}

// Resolve returns one sync_repo route per serving mirror of the pushed repo.
// For a native-mirror group every ref op fans out — hash transitions move
// objects, and a symref_update (default-branch move) is reconciled by the
// worker's post-sync HEAD follow, the entiredb twin of the webhook path's
// default-branch edit. For a namespace group only refs under
// namespaceRefPrefix fan out; the rest of that repo's ref state belongs to
// GitHub's own mirroring. Transparency-log refs are skipped either way: every
// push writes them alongside the branch ref, so the branch event already
// triggers the (full-ref-state) sync.
func (d *nativeMirrorSyncResolver) Resolve(ctx context.Context, _ string, _ string, _ time.Time, body []byte) ([]fanoutengine.Route, string, error) {
	ev, err := refevents.Unmarshal(body)
	if err != nil {
		// Unreachable in practice — Decode already validated this payload —
		// kept as an input error so a future decoder/resolver drift Terms
		// instead of redelivering a poison payload forever.
		return nil, "", fanoutengine.Input("invalid ref event: %v", err)
	}
	if ev.RepoID == "" {
		// Unmarshal tolerates absent fields by design (independent producer
		// deploys), but an event with no repo id can never resolve — an
		// input error (Term), not a Nak, or the poison payload would ride
		// all MaxDeliver redeliveries for nothing.
		return nil, "", fanoutengine.Input("ref event has no repo_id")
	}

	if strings.HasPrefix(ev.RefName, "refs/tlog/") {
		return nil, ackReasonTlogRef, nil
	}

	// Stamp the parent span with the source coordinates so dropped or failed
	// deliveries are still findable by repo id. entire.ref_event.op is
	// re-stamped with the WIRE value: the decoder's envelope clamps unknown
	// ops to "other" for metric cardinality, but the span can carry the
	// real one.
	span := trace.SpanFromContext(ctx)
	span.SetAttributes(
		attribute.String("entire.source_kind", "entiredb"),
		attribute.String("entire.repo_id", ev.RepoID),
		attribute.String("entire.ref_name", ev.RefName),
		attribute.String("entire.ref_event.op", ev.RefOp),
	)

	res, err := d.routes.NativeMirrorRoutes(ctx, ev.RepoID)
	if err != nil {
		if errors.Is(err, mirrorjobs.ErrNativeRepoNotFound) {
			// Repo deleted between event publish and consume: benign skip.
			span.AddEvent("native_mirror.repo_not_found")
			slog.InfoContext(ctx, "Ref event for unknown repo; skipping",
				slog.String("repo_id", ev.RepoID), slog.String("ref_name", ev.RefName))
			return nil, ackReasonRepoNotFound, nil
		}
		slog.ErrorContext(ctx, "Native mirror route resolution failed",
			slog.String("repo_id", ev.RepoID), slog.Any("error", err))
		return nil, "", err
	}

	if res.HomeClusterID != d.localClusterID {
		// Mirror-side echo of a worker push (or an event for a repo homed
		// elsewhere): only the home cluster fans out.
		span.SetAttributes(attribute.String("entire.native_mirror.home_cluster_id", res.HomeClusterID))
		return nil, ackReasonNotHome, nil
	}

	if len(res.NamespaceRoutes) > 0 && !strings.HasPrefix(ev.RefName, namespaceRefPrefix) {
		return nil, ackReasonNamespaceOutOfScope, nil
	}

	routes := slices.Concat(res.Routes, res.NamespaceRoutes)
	if len(routes) == 0 {
		return nil, ackReasonNoMirrors, nil
	}

	out := make([]fanoutengine.Route, 0, len(routes))
	for _, route := range routes {
		out = append(out, gitSyncRoute{route: route})
	}
	return out, "", nil
}

package mirrorjobs

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"

	"connectrpc.com/connect"
	"github.com/oklog/ulid/v2"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	repolookupv1 "github.com/entirehq/mirror-pipeline/gen/proto/repolookup/v1"
	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// ErrNativeRepoNotFound is returned by NativeMirrorRoutes when entire-core has
// no repo for the given ULID — normal for a repo deleted between a ref event
// being published and consumed. Callers treat it as a benign skip, not a
// transient error to retry.
var ErrNativeRepoNotFound = errors.New("mirrorjobs: native repo not found")

// NativeMirrorLookupClient is the subset of the generated Connect client
// needed by NativeMirrorResolver. Kept separate from RepoLookupClient so the
// GitHub-webhook resolver and its fakes don't grow a method they never call.
type NativeMirrorLookupClient interface {
	LookupNativeMirrorsByRepoID(context.Context, *connect.Request[repolookupv1.LookupNativeMirrorsByRepoIDRequest]) (*connect.Response[repolookupv1.LookupNativeMirrorsByRepoIDResponse], error)
}

// NativeMirrorResolution is one resolved ref event: the group's git-data home
// cluster (the loop-prevention key — the caller drops the event unless its
// local cluster is the home) and one sync route per serving mirror.
type NativeMirrorResolution struct {
	HomeClusterID string
	Routes        []MirrorRoute
	// NamespaceRoutes replicate only refs/heads/entire/native/* (COR-1566)
	// onto the group's namespace mirrors — GitHub placements that own the
	// rest of their ref state. Core populates namespace mirrors only for
	// GitHub groups, which have no native mirrors, so this is never
	// non-empty at the same time as Routes; the caller filters the event's
	// ref name against the namespace before publishing these.
	NamespaceRoutes []MirrorRoute
}

// NativeMirrorResolver resolves repo ULIDs from repo_refs_v1 events into
// native-mirror sync routes through entire-core
// RepoLookup.LookupNativeMirrorsByRepoID.
type NativeMirrorResolver struct {
	client NativeMirrorLookupClient
	skips  metric.Int64Counter
}

// NewNativeMirrorResolver returns a lookup-backed native-mirror route
// resolver. The placement_skipped counter is shared (by name) with
// CoreLookupResolver — same signal, same dashboards: entire-core returned
// unroutable placement data.
func NewNativeMirrorResolver(client NativeMirrorLookupClient) *NativeMirrorResolver {
	skips, _ := otel.Meter("github.com/entirehq/mirror-pipeline/internal/mirrorjobs").
		Int64Counter("mirrorjobs.placement_skipped",
			metric.WithDescription("Placements dropped from a repo lookup because a required routing field (cluster_slug or repo_id) was blank or malformed, by reason."))
	return &NativeMirrorResolver{client: client, skips: skips}
}

func (r *NativeMirrorResolver) recordSkip(ctx context.Context, reason string) {
	if r.skips != nil {
		r.skips.Add(ctx, 1, metric.WithAttributes(attribute.String("reason", reason)))
	}
}

// validateNativeMirrorLookupResponse checks the two response invariants a
// delivery cannot proceed without: a home placement with a cluster slug (the
// loop-prevention key) and, when any routable mirror exists, a source URL
// (the sync job's fetch source). Shared by NativeMirrorRoutes (which fails
// the delivery on a violation → Nak → redelivery until Core is fixed) and
// the caching client (which must NOT store a violating response — a cached
// one would keep failing redeliveries for a full TTL after the Core-side
// fix). Per-placement problems are deliberately NOT here: a single malformed
// placement only skips that route, so it must not block caching either.
func validateNativeMirrorLookupResponse(resp *repolookupv1.LookupNativeMirrorsByRepoIDResponse) error {
	if resp.GetHome().GetClusterSlug() == "" {
		return errors.New("home placement has no cluster slug")
	}
	if resp.GetSourceUrl() == "" &&
		(slices.ContainsFunc(resp.GetNativeMirrors(), routableNativeMirror) ||
			slices.ContainsFunc(resp.GetNamespaceMirrors(), routableNativeMirror)) {
		return fmt.Errorf("home cluster %s has no internal source URL registered", resp.GetHome().GetClusterSlug())
	}
	return nil
}

// routableNativeMirror reports whether a placement would survive
// NativeMirrorRoutes's per-placement validation and become a route.
func routableNativeMirror(p *repolookupv1.Placement) bool {
	if p.GetClusterSlug() == "" || p.GetRepoId() == "" {
		return false
	}
	_, err := ulid.ParseStrict(p.GetRepoId())
	return err == nil
}

// NativeMirrorRoutes resolves the repo id carried by a ref event (any
// placement of the repo — the home primary, or a mirror echoing a worker
// push) to its group's home cluster, one sync route per serving native
// mirror, and one namespace route per namespace mirror. Both route sets
// empty is normal — a repo with no mirrors, i.e. every repo today.
//
// Mirrors of either kind are unique per cluster (UNIQUE(repo_group_id,
// cluster_slug) on native_mirrors; one mirror_repos row per cluster in a
// GitHub group), so two routes never share a Region() in one delivery — the
// fan-out engine's route-memo correctness bound.
//
// Errors: ErrNativeRepoNotFound for an unknown repo id (benign skip — the
// repo was deleted); a plain error otherwise (transient — the caller Naks so
// JetStream redelivers). A response whose home placement is missing its
// cluster slug, or whose source_url is empty while serving mirrors exist, is
// also a plain error: both are server-side data/config problems (an
// unregistered internal URL for the home cluster) that an operator fix
// heals, and dropping the event instead would silently strand the mirrors
// until the next push.
func (r *NativeMirrorResolver) NativeMirrorRoutes(ctx context.Context, repoID string) (NativeMirrorResolution, error) {
	if repoID == "" {
		return NativeMirrorResolution{}, errors.New("repo id is required")
	}

	resp, err := r.client.LookupNativeMirrorsByRepoID(ctx, connect.NewRequest(&repolookupv1.LookupNativeMirrorsByRepoIDRequest{
		RepoId: repoID,
	}))
	if err != nil {
		if connect.CodeOf(err) == connect.CodeNotFound {
			return NativeMirrorResolution{}, fmt.Errorf("%w: %s", ErrNativeRepoNotFound, repoID)
		}
		return NativeMirrorResolution{}, fmt.Errorf("native mirror lookup %s: %w", repoID, err)
	}

	if err := validateNativeMirrorLookupResponse(resp.Msg); err != nil {
		return NativeMirrorResolution{}, fmt.Errorf("native mirror lookup %s: %w", repoID, err)
	}
	return NativeMirrorResolution{
		HomeClusterID:   resp.Msg.GetHome().GetClusterSlug(),
		Routes:          r.routesFor(ctx, repoID, gitjobs.SourceKindEntireDB, resp.Msg.GetSourceUrl(), resp.Msg.GetNativeMirrors()),
		NamespaceRoutes: r.routesFor(ctx, repoID, gitjobs.SourceKindEntireDBNamespace, resp.Msg.GetSourceUrl(), resp.Msg.GetNamespaceMirrors()),
	}, nil
}

// routesFor turns one placement list into sync routes of the given kind,
// skipping (and counting) placements Core returned without the routing
// fields a job needs.
func (r *NativeMirrorResolver) routesFor(ctx context.Context, repoID string, kind gitjobs.SourceKind, sourceURL string, mirrors []*repolookupv1.Placement) []MirrorRoute {
	routes := make([]MirrorRoute, 0, len(mirrors))
	for _, p := range mirrors {
		if p.GetClusterSlug() == "" {
			slog.WarnContext(ctx, "native mirror lookup returned empty cluster slug; skipping placement",
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("mirror_repo_id", p.GetRepoId()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "empty_cluster_slug")
			continue
		}
		if p.GetRepoId() == "" {
			slog.WarnContext(ctx, "native mirror lookup returned empty repo_id; skipping placement",
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "empty_repo_id")
			continue
		}
		if _, err := ulid.ParseStrict(p.GetRepoId()); err != nil {
			slog.WarnContext(ctx, "native mirror lookup returned malformed repo_id; skipping placement",
				slog.String("mirror_repo_id", p.GetRepoId()),
				slog.String("cluster_slug", p.GetClusterSlug()),
				slog.String("jurisdiction", p.GetJurisdiction()),
				slog.String("repo_id", repoID))
			r.recordSkip(ctx, "invalid_repo_id")
			continue
		}
		routes = append(routes, MirrorRoute{
			Placement: gitjobs.Placement{
				Jurisdiction: p.GetJurisdiction(),
				ClusterID:    p.GetClusterSlug(),
			},
			SourceKind: kind,
			Source:     gitjobs.Source{URL: sourceURL},
			Target:     gitjobs.Target{ULID: p.GetRepoId()},
		})
	}
	return routes
}

