// Package refevents is the CONSUME-side projection of entiredb's
// repo_refs_v1 wire contract (entiredb refevents/refevents.go — the source
// of truth, which owns the stream, the producer sinks, and the full RefEvent
// format). This copy exists so mirror-pipeline can decode ref events without
// taking a Go-module dependency on the entiredb tree, the same trade the
// repository-local repolookup proto copy makes. Keep the stream/subject names
// and the JSON field names byte-for-byte identical with entiredb's copy — they
// are the on-the-wire contract and any drift silently breaks the consumer.
//
// The stream is per-cluster and LOCAL: every entiredb cluster publishes its
// own repo_refs_v1 onto its own NATS island, one event per committed ref
// change on any repo hosted there. Producers guarantee at-least-once
// delivery of committed changes (transactional outbox), but the stream is
// limits-retention and its history is bounded — a consumer that needs
// correctness beyond the retention window must get it elsewhere (for native
// mirroring: every sync replicates full ref state, so the next push heals a
// lost event).
package refevents

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

// NATS stream / subject identity, as declared by entiredb (the stream owner).
// Events are published on NATSSubjectPrefix + <repo ULID>.
const (
	NATSSubjectPrefix = "repo_refs_v1."
	NATSStreamName    = "repo_refs_v1"
)

// refEventVersion is the supported wire envelope version.
const refEventVersion = 1

// Wire values for RefEvent.RefOp.
const (
	RefOpCreate      = "create"
	RefOpUpdate      = "update"
	RefOpDelete      = "delete"
	RefOpForceUpdate = "force_update"
	// RefOpSymrefUpdate is a symbolic ref retargeting (today only HEAD, moved
	// on a default-branch change). It carries no object motion: the targets
	// stay empty and the transition is OldSymrefTarget → NewSymrefTarget.
	RefOpSymrefUpdate = "symref_update"
)

// RefEvent is the JSON wire format for ref-change notifications on
// repo_refs_v1. Only the fields this repo's consumers read are declared;
// unknown fields are tolerated by Unmarshal (producers deploy independently).
type RefEvent struct {
	Version       int       `json:"version"`
	RepoID        string    `json:"repo_id"`
	RefName       string    `json:"ref_name"`
	RefOp         string    `json:"ref_op"`
	OldTarget     string    `json:"old_target"`
	NewTarget     string    `json:"new_target"`
	HashAlgorithm string    `json:"hash_algorithm"`
	Timestamp     time.Time `json:"timestamp"`
	// OldSymrefTarget/NewSymrefTarget carry a symbolic ref's retargeting for
	// RefOpSymrefUpdate events (full ref names, e.g. "refs/heads/main" →
	// "refs/heads/studio"). Empty on every hash-transition op.
	OldSymrefTarget string `json:"old_symref_target,omitempty"`
	NewSymrefTarget string `json:"new_symref_target,omitempty"`
}

// Unmarshal decodes a JSON ref event from its NATS payload.
//
// Unknown fields are tolerated deliberately: producers (entiredb nodes) and
// this consumer deploy independently, so payloads from a publisher one
// version ahead of or behind the decoder are normal, not malformed. The
// version field is the gate for genuinely breaking envelope changes.
func Unmarshal(data []byte) (RefEvent, error) {
	var ev RefEvent
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&ev); err != nil {
		return RefEvent{}, fmt.Errorf("decode ref event: %w", err)
	}
	if dec.More() {
		return RefEvent{}, errors.New("trailing data after ref event")
	}
	if ev.Version != refEventVersion {
		return RefEvent{}, fmt.Errorf("unsupported ref event version: %d", ev.Version)
	}
	return ev, nil
}

// DeliveryID identifies one emitted event: the ref-transition content scoped
// by the emit timestamp — the same identity the producer uses as its outbox
// Nats-Msg-Id, so a JetStream redelivery of one emit carries the same value
// while a later re-push of the same transition gets a fresh one. Consumers
// use it as their per-delivery dedup/memo key.
func (ev RefEvent) DeliveryID() string {
	old, next := ev.OldTarget, ev.NewTarget
	if ev.RefOp == RefOpSymrefUpdate {
		// A symref move carries no hashes; its transition is the ref-name
		// pair. Ref names cannot contain ':', so the format stays unambiguous.
		old, next = ev.OldSymrefTarget, ev.NewSymrefTarget
	}
	return fmt.Sprintf("%s:%s:%s:%s:%d", ev.RepoID, ev.RefName, old, next, ev.Timestamp.UnixNano())
}

