1	// Package gitjobs defines the target-owned Git mirror job contract.
2	package gitjobs
3	
4	import (
5		"encoding/json"
6		"errors"
7		"fmt"
8		"log/slog"
9		"net/url"
10		"reflect"
11		"regexp"
12		"strconv"
13		"strings"
14		"time"
15	
16		"github.com/nats-io/nats.go"
17		"go.opentelemetry.io/otel/attribute"
18	)
19	
20	const (
21		StreamName    = "mirror_git_v1"
22		SubjectPrefix = "mirror.git.v1."
23		Version1      = 1
24	
25		// StreamDuplicatesWindow is the JetStream dedup window. Publishes that
26		// reuse the same Nats-Msg-Id within this window are collapsed server-side
27		// to a single stored message. Scoped to collapse the webhook fan-out burst
28		// from a single source change; long-tail races are handled by route-level
29		// coalescing in the ingest (see Task 6).
30		StreamDuplicatesWindow = 1 * time.Second
31	
32		// StreamMaxAge bounds how long an unacked job can sit in the stream
33		// before JetStream drops it server-side. 6h is the tightest window
34		// that survives a realistic worker outage. NOTE: the periodic resync
35		// scheduler that used to backstop drops past this window has been
36		// decommissioned, so a job aged out here is only recovered by the next
37		// webhook for that source (or a manual resync) — not automatically.
38		StreamMaxAge = 6 * time.Hour
39	
40		// StreamMaxBytes caps the on-disk footprint per replica. With
41		// Discard=DiscardNew, hitting this rejects new publishes (the
42		// webhook returns 500) instead of silently dropping already-enqueued
43		// jobs. ~500B payloads => ~2M queued jobs per replica; cluster total
44		// at R=3 is 3× this.
45		StreamMaxBytes = 1 << 30 // 1 GiB
46	
47		// DefaultStreamReplicas is the production target. Single-node dev
48		// NATS overrides via ENTIRE_NATS_STREAM_REPLICAS=1.
49		DefaultStreamReplicas = 3
50	)
51	
52	type SourceKind string
53	type Op string
54	
55	const (
56		SourceKindGithub   SourceKind = "github"
57		SourceKindEntireDB SourceKind = "entiredb"
58		// SourceKindEntireDBNamespace is an entiredb sync scoped to the
59		// Entire-owned refs/heads/entire/native/* namespace (COR-1566): same
60		// body shape as entiredb, different replication scope on the worker,
61		// and its own subject token so the two kinds land on separate durables.
62		SourceKindEntireDBNamespace SourceKind = "entiredb_ns"
63	
64		OpSyncRepo Op = "sync_repo"
65	
66		GithubAppInstallationAuthRefPrefix = "github_app_installation:"
67	)
68	
69	// SourceKinds lists every source kind, for code that visits each kind of a
70	// target (the worker's pending-note hand-off).
71	var SourceKinds = []SourceKind{SourceKindGithub, SourceKindEntireDB, SourceKindEntireDBNamespace}
72	
73	// Placement is the target cluster identity used to compose the message
74	// subject. It is not on the wire — every published message carries its
75	// placement in the subject (mirror.git.v1.<jur>.<cluster>.<src>.<op>), so
76	// consumers recover it via ParseSubject(msg.Subject).
77	type Placement struct {
78		Jurisdiction string
79		ClusterID    string
80	}
81	
82	// ParsedSubject is the inverse of Subject: everything the message subject
83	// encodes. Consumers use this to recover placement / source kind / op
84	// without trusting the body, since the broker routed by subject.
85	type ParsedSubject struct {
86		Placement  Placement
87		SourceKind SourceKind
88		Op         Op
89	}
90	
91	type Target struct {
92		ULID string `json:"ulid"`
93	}
94	
95	type Source struct {
96		// Owner/Repo are the GitHub upstream coordinates. github kind only.
97		Owner   string `json:"owner,omitempty"`
98		Repo    string `json:"repo,omitempty"`
99		AuthRef string `json:"auth_ref,omitempty"`
100		// URL is the source repo's internal by-ID git URL on its home entiredb
101		// cluster (https://<internal host>/git/repo/<ULID>), computed by
102		// entire-core so fanout and the worker stay source-agnostic. entiredb
103		// kind only; the worker additionally gates the host against its
104		// configured source-cluster allowlist before fetching — schema
105		// validation here bounds the shape, not the trust.
106		URL string `json:"url,omitempty"`
107	}
108	
109	type Job struct {
110		Version int    `json:"version"`
111		Source  Source `json:"source"`
112		Target  Target `json:"target"`
113	}
114	
115	// FormatGithubInstallationAuthRef encodes a GitHub App installation ID as the
116	// canonical auth_ref string used in Source.AuthRef. Returns "" for non-positive
117	// IDs so anonymous public-repo flows leave AuthRef empty.
118	func FormatGithubInstallationAuthRef(installationID int64) string {
119		if installationID <= 0 {
120			return ""
121		}
122		return GithubAppInstallationAuthRefPrefix + strconv.FormatInt(installationID, 10)
123	}
124	
125	// ParseGithubInstallationAuthRef is the inverse of FormatGithubInstallationAuthRef.
126	// An empty authRef returns (0, nil) so callers can treat it as "no installation".
127	func ParseGithubInstallationAuthRef(authRef string) (int64, error) {
128		if authRef == "" {
129			return 0, nil
130		}
131		if !strings.HasPrefix(authRef, GithubAppInstallationAuthRefPrefix) {
132			return 0, fmt.Errorf("unsupported github auth_ref")
133		}
134		raw := strings.TrimPrefix(authRef, GithubAppInstallationAuthRefPrefix)
135		id, err := strconv.ParseInt(raw, 10, 64)
136		if err != nil || id <= 0 {
137			return 0, fmt.Errorf("invalid github installation auth_ref")
138		}
139		return id, nil
140	}
141	
142	// SplitFullName splits a GitHub "owner/repo" full_name into its parts. ok is
143	// false for any input that isn't exactly two non-empty slash-separated tokens,
144	// so callers can reject a malformed webhook payload up front. Inverse-adjacent
145	// to the other GitHub identity helpers above.
146	func SplitFullName(fullName string) (owner, repo string, ok bool) {
147		parts := strings.SplitN(fullName, "/", 2)
148		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
149			return "", "", false
150		}
151		return parts[0], parts[1], true
152	}
153	
154	// Subject composes the canonical subject for a published message. Round-trip
155	// with ParseSubject.
156	func Subject(ps ParsedSubject) string {
157		return fmt.Sprintf("%s%s.%s.%s.%s",
158			SubjectPrefix,
159			ps.Placement.Jurisdiction,
160			ps.Placement.ClusterID,
161			ps.SourceKind,
162			ps.Op,
163		)
164	}
165	
166	// ParseSubject extracts placement / source kind / op from a canonical
167	// subject. Errors on prefix mismatch or wrong token count; does not validate
168	// that the kind/op values are known — that is the caller's policy decision.
169	func ParseSubject(s string) (ParsedSubject, error) {
170		if !strings.HasPrefix(s, SubjectPrefix) {
171			return ParsedSubject{}, fmt.Errorf("subject %q missing prefix %q", s, SubjectPrefix)
172		}
173		parts := strings.Split(strings.TrimPrefix(s, SubjectPrefix), ".")
174		if len(parts) != 4 {
175			return ParsedSubject{}, fmt.Errorf("subject %q has %d tokens after prefix, want 4", s, len(parts))
176		}
177		for i, p := range parts {
178			if p == "" {
179				return ParsedSubject{}, fmt.Errorf("subject %q has empty token at position %d", s, i)
180			}
181		}
182		return ParsedSubject{
183			Placement: Placement{
184				Jurisdiction: parts[0],
185				ClusterID:    parts[1],
186			},
187			SourceKind: SourceKind(parts[2]),
188			Op:         Op(parts[3]),
189		}, nil
190	}
191	
192	// SpanAttrs returns the OTel span attributes for the body-resident fields of
193	// a Job. Combine with ParsedSubject.SpanAttrs() at the call site so spans
194	// carry the full identity (subject-derived + body-derived).
195	func (j Job) SpanAttrs() []attribute.KeyValue {
196		return []attribute.KeyValue{
197			attribute.String("entire.source_owner", j.Source.Owner),
198			attribute.String("entire.source_repo", j.Source.Repo),
199			attribute.String("entire.target_ulid", j.Target.ULID),
200		}
201	}
202	
203	// LogAttrs is the slog counterpart to SpanAttrs (without the "entire." prefix).
204	func (j Job) LogAttrs() []slog.Attr {
205		return []slog.Attr{
206			slog.String("source_owner", j.Source.Owner),
207			slog.String("source_repo", j.Source.Repo),
208			slog.String("target_ulid", j.Target.ULID),
209		}
210	}
211	
212	// SpanAttrs returns the OTel span attributes for the subject-encoded fields
213	// (placement + source kind + op). Combine with Job.SpanAttrs() at the call
214	// site.
215	func (ps ParsedSubject) SpanAttrs() []attribute.KeyValue {
216		return []attribute.KeyValue{
217			attribute.String("entire.operation", string(ps.Op)),
218			attribute.String("entire.source_kind", string(ps.SourceKind)),
219			attribute.String("entire.target_jurisdiction", ps.Placement.Jurisdiction),
220			attribute.String("entire.target_cluster_id", ps.Placement.ClusterID),
221		}
222	}
223	
224	// LogAttrs is the slog counterpart to SpanAttrs (without the "entire." prefix).
225	func (ps ParsedSubject) LogAttrs() []slog.Attr {
226		return []slog.Attr{
227			slog.String("operation", string(ps.Op)),
228			slog.String("source_kind", string(ps.SourceKind)),
229			slog.String("target_jurisdiction", ps.Placement.Jurisdiction),
230			slog.String("target_cluster_id", ps.Placement.ClusterID),
231		}
232	}
233	
234	// ValidateFor validates the job body against the source kind carried by the
235	// message subject. The body is kind-shaped (github: owner/repo coordinates;
236	// entiredb: the by-ID source URL), so validation cannot be kind-blind — both
237	// producer and consumer sides have the kind in hand (the subject is built
238	// from it / parsed before the body).
239	func (j Job) ValidateFor(kind SourceKind) error {
240		if err := j.validateVersion(true); err != nil {
241			return err
242		}
243		if err := j.Source.ValidateFor(kind); err != nil {
244			return err
245		}
246		if err := j.Target.Validate(); err != nil {
247			return err
248		}
249		return nil
250	}
251	
252	func (j Job) validateVersion(allowZero bool) error {
253		if allowZero && j.Version == 0 {
254			return nil
255		}
256		if j.Version != Version1 {
257			return fmt.Errorf("unknown version %d", j.Version)
258		}
259		return nil
260	}
261	
262	func (j Job) withVersion() Job {
263		if j.Version == 0 {
264			j.Version = Version1
265		}
266		return j
267	}
268	
269	// entireDBSourcePath matches the exact by-ID git route an entiredb source
270	// URL must carry: /git/repo/<ULID> (26 Crockford base32 chars), nothing else.
271	var entireDBSourcePath = regexp.MustCompile(`^/git/repo/[0-9A-HJKMNP-TV-Z]{26}$`)
272	
273	func (s Source) ValidateFor(kind SourceKind) error {
274		switch kind {
275		case SourceKindGithub:
276			if s.Owner == "" {
277				return errors.New("source.owner is required")
278			}
279			if s.Repo == "" {
280				return errors.New("source.repo is required")
281			}
282			if s.URL != "" {
283				return errors.New("source.url is forbidden for github sources")
284			}
285			return nil
286		case SourceKindEntireDB, SourceKindEntireDBNamespace:
287			if s.Owner != "" || s.Repo != "" {
288				return errors.New("source.owner/repo are forbidden for entiredb sources")
289			}
290			if s.AuthRef != "" {
291				// entiredb source fetches authenticate with the worker's client
292				// cert, never a minted token.
293				return errors.New("source.auth_ref is forbidden for entiredb sources")
294			}
295			return validateEntireDBSourceURL(s.URL)
296		default:
297			return fmt.Errorf("unknown source kind %q", kind)
298		}
299	}
300	
301	// validateEntireDBSourceURL treats the job as an input boundary: https only,
302	// a host, the exact by-ID path shape, and none of the URL parts a crafted
303	// job could smuggle routing through (userinfo, query, fragment, port games
304	// are left to the worker's host allowlist).
305	func validateEntireDBSourceURL(raw string) error {
306		if raw == "" {
307			return errors.New("source.url is required for entiredb sources")
308		}
309		u, err := url.Parse(raw)
310		if err != nil {
311			return fmt.Errorf("source.url: %w", err)
312		}
313		if u.Scheme != "https" {
314			return fmt.Errorf("source.url scheme %q: https required", u.Scheme)
315		}
316		if u.Host == "" {
317			return errors.New("source.url host is required")
318		}
319		if u.User != nil {
320			return errors.New("source.url must not carry userinfo")
321		}
322		if u.RawQuery != "" || u.Fragment != "" || u.ForceQuery {
323			return errors.New("source.url must not carry a query or fragment")
324		}
325		// The regexp below runs on the DECODED path, but the wire request is
326		// built from the raw one — a percent-encoded variant ("/git%2Frepo%2F…",
327		// "/git/repo/%30…") would pass the shape check while putting something
328		// else entirely on the request line. Require the two to agree so the
329		// validated shape IS the wire shape.
330		if u.EscapedPath() != u.Path {
331			return fmt.Errorf("source.url path %q carries percent-encoding: want the literal /git/repo/<ULID>", u.EscapedPath())
332		}
333		if !entireDBSourcePath.MatchString(u.Path) {
334			return fmt.Errorf("source.url path %q: want exactly /git/repo/<ULID>", u.Path)
335		}
336		return nil
337	}
338	
339	// SourceRepoULID extracts the source repo ULID from an entiredb source URL.
340	// Callers validate first; a malformed URL yields "".
341	func (s Source) SourceRepoULID() string {
342		u, err := url.Parse(s.URL)
343		if err != nil || !entireDBSourcePath.MatchString(u.Path) {
344			return ""
345		}
346		return u.Path[len("/git/repo/"):]
347	}
348	
349	func (t Target) Validate() error {
350		if t.ULID == "" {
351			return errors.New("target.ulid is required")
352		}
353		return nil
354	}
355	
356	func MarshalFor(kind SourceKind, job Job) ([]byte, error) {
357		job = job.withVersion()
358		if err := job.ValidateFor(kind); err != nil {
359			return nil, err
360		}
361		data, err := json.Marshal(job)
362		if err != nil {
363			return nil, fmt.Errorf("marshal git job: %w", err)
364		}
365		return data, nil
366	}
367	
368	func UnmarshalFor(kind SourceKind, data []byte) (Job, error) {
369		var job Job
370		if err := json.Unmarshal(data, &job); err != nil {
371			return job, fmt.Errorf("unmarshal git job: %w", err)
372		}
373		if err := job.validateVersion(false); err != nil {
374			return job, fmt.Errorf("validate git job: %w", err)
375		}
376		if err := job.ValidateFor(kind); err != nil {
377			return job, fmt.Errorf("validate git job: %w", err)
378		}
379		return job, nil
380	}
381	
382	// MsgID composes the JetStream dedup id for a job: source coordinates +
383	// target, per kind — github keys on the upstream owner/repo, entiredb on the
384	// source repo ULID. Shared by every publisher so retries and the duplicate
385	// window collapse identically no matter who published.
386	func MsgID(parsed ParsedSubject, job Job) string {
387		if parsed.SourceKind == SourceKindEntireDB || parsed.SourceKind == SourceKindEntireDBNamespace {
388			return fmt.Sprintf("%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.SourceRepoULID(), job.Target.ULID)
389		}
390		return fmt.Sprintf("%s/%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.Owner, job.Source.Repo, job.Target.ULID)
391	}
392	
393	// EnsureStream is idempotent: create the stream if it's absent, otherwise
394	// reconcile any drift in the contract fields (including a Replicas scale-up
395	// — supported online by nats-server >= 2.8). Replicas comes from the caller
396	// so dev (single-node NATS) can pass 1 via ENTIRE_NATS_STREAM_REPLICAS.
397	// ParseStreamReplicas parses a replica count from a raw env-var string.
398	// Empty input returns DefaultStreamReplicas (production target). Any other
399	// input must be a positive integer; zero, negative, or non-integer values
400	// are rejected so a typo in deploy config fails fast at startup instead of
401	// silently shipping a single-replica stream.
402	func ParseStreamReplicas(raw string) (int, error) {
403		if raw == "" {
404			return DefaultStreamReplicas, nil
405		}
406		n, err := strconv.Atoi(raw)
407		if err != nil {
408			return 0, fmt.Errorf("invalid replica count %q: %w", raw, err)
409		}
410		if n < 1 {
411			return 0, fmt.Errorf("invalid replica count %d: must be >= 1", n)
412		}
413		return n, nil
414	}
415	
416	func EnsureStream(js nats.JetStreamContext, replicas int) error {
417		desired := ownedStreamConfig(replicas)
418	
419		_, err := js.AddStream(desired)
420		if err == nil {
421			return nil
422		}
423		if !errors.Is(err, nats.ErrStreamNameAlreadyInUse) {
424			return fmt.Errorf("create git mirror stream: %w", err)
425		}
426	
427		existing, err := js.StreamInfo(StreamName)
428		if err != nil {
429			return fmt.Errorf("get git mirror stream: %w", err)
430		}
431	
432		updated := existing.Config
433		applyContract(&updated, replicas)
434		if reflect.DeepEqual(updated, existing.Config) {
435			return nil
436		}
437	
438		if _, err = js.UpdateStream(&updated); err != nil {
439			return fmt.Errorf("update git mirror stream: %w", err)
440		}
441		return nil
442	}
443	
444	func ownedStreamConfig(replicas int) *nats.StreamConfig {
445		cfg := &nats.StreamConfig{}
446		applyContract(cfg, replicas)
447		return cfg
448	}
449	
450	func applyContract(cfg *nats.StreamConfig, replicas int) {
451		cfg.Name = StreamName
452		cfg.Subjects = []string{SubjectPrefix + ">"}
453		cfg.Retention = nats.WorkQueuePolicy
454		cfg.Storage = nats.FileStorage
455		cfg.Discard = nats.DiscardNew
456		cfg.Duplicates = StreamDuplicatesWindow
457		cfg.MaxAge = StreamMaxAge
458		cfg.MaxBytes = StreamMaxBytes
459		cfg.Replicas = replicas
460	}
