// Package gitjobs defines the target-owned Git mirror job contract.
package gitjobs

import (
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"reflect"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
)

const (
	StreamName    = "mirror_git_v1"
	SubjectPrefix = "mirror.git.v1."
	Version1      = 1

	// StreamDuplicatesWindow is the JetStream dedup window. Publishes that
	// reuse the same Nats-Msg-Id within this window are collapsed server-side
	// to a single stored message. Scoped to collapse the webhook fan-out burst
	// from a single source change; long-tail races are handled by route-level
	// coalescing in the ingest (see Task 6).
	StreamDuplicatesWindow = 1 * time.Second

	// StreamMaxAge bounds how long an unacked job can sit in the stream
	// before JetStream drops it server-side. 6h is the tightest window
	// that survives a realistic worker outage. NOTE: the periodic resync
	// scheduler that used to backstop drops past this window has been
	// decommissioned, so a job aged out here is only recovered by the next
	// webhook for that source (or a manual resync) — not automatically.
	StreamMaxAge = 6 * time.Hour

	// StreamMaxBytes caps the on-disk footprint per replica. With
	// Discard=DiscardNew, hitting this rejects new publishes (the
	// webhook returns 500) instead of silently dropping already-enqueued
	// jobs. ~500B payloads => ~2M queued jobs per replica; cluster total
	// at R=3 is 3× this.
	StreamMaxBytes = 1 << 30 // 1 GiB

	// DefaultStreamReplicas is the production target. Single-node dev
	// NATS overrides via ENTIRE_NATS_STREAM_REPLICAS=1.
	DefaultStreamReplicas = 3
)

type SourceKind string
type Op string

const (
	SourceKindGithub   SourceKind = "github"
	SourceKindEntireDB SourceKind = "entiredb"
	// SourceKindEntireDBNamespace is an entiredb sync scoped to the
	// Entire-owned refs/heads/entire/native/* namespace (COR-1566): same
	// body shape as entiredb, different replication scope on the worker,
	// and its own subject token so the two kinds land on separate durables.
	SourceKindEntireDBNamespace SourceKind = "entiredb_ns"

	OpSyncRepo Op = "sync_repo"

	GithubAppInstallationAuthRefPrefix = "github_app_installation:"
)

// SourceKinds lists every source kind, for code that visits each kind of a
// target (the worker's pending-note hand-off).
var SourceKinds = []SourceKind{SourceKindGithub, SourceKindEntireDB, SourceKindEntireDBNamespace}

// Placement is the target cluster identity used to compose the message
// subject. It is not on the wire — every published message carries its
// placement in the subject (mirror.git.v1.<jur>.<cluster>.<src>.<op>), so
// consumers recover it via ParseSubject(msg.Subject).
type Placement struct {
	Jurisdiction string
	ClusterID    string
}

// ParsedSubject is the inverse of Subject: everything the message subject
// encodes. Consumers use this to recover placement / source kind / op
// without trusting the body, since the broker routed by subject.
type ParsedSubject struct {
	Placement  Placement
	SourceKind SourceKind
	Op         Op
}

type Target struct {
	ULID string `json:"ulid"`
}

type Source struct {
	// Owner/Repo are the GitHub upstream coordinates. github kind only.
	Owner   string `json:"owner,omitempty"`
	Repo    string `json:"repo,omitempty"`
	AuthRef string `json:"auth_ref,omitempty"`
	// URL is the source repo's internal by-ID git URL on its home entiredb
	// cluster (https://<internal host>/git/repo/<ULID>), computed by
	// entire-core so fanout and the worker stay source-agnostic. entiredb
	// kind only; the worker additionally gates the host against its
	// configured source-cluster allowlist before fetching — schema
	// validation here bounds the shape, not the trust.
	URL string `json:"url,omitempty"`
}

type Job struct {
	Version int    `json:"version"`
	Source  Source `json:"source"`
	Target  Target `json:"target"`
}

// FormatGithubInstallationAuthRef encodes a GitHub App installation ID as the
// canonical auth_ref string used in Source.AuthRef. Returns "" for non-positive
// IDs so anonymous public-repo flows leave AuthRef empty.
func FormatGithubInstallationAuthRef(installationID int64) string {
	if installationID <= 0 {
		return ""
	}
	return GithubAppInstallationAuthRefPrefix + strconv.FormatInt(installationID, 10)
}

// ParseGithubInstallationAuthRef is the inverse of FormatGithubInstallationAuthRef.
// An empty authRef returns (0, nil) so callers can treat it as "no installation".
func ParseGithubInstallationAuthRef(authRef string) (int64, error) {
	if authRef == "" {
		return 0, nil
	}
	if !strings.HasPrefix(authRef, GithubAppInstallationAuthRefPrefix) {
		return 0, fmt.Errorf("unsupported github auth_ref")
	}
	raw := strings.TrimPrefix(authRef, GithubAppInstallationAuthRefPrefix)
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id <= 0 {
		return 0, fmt.Errorf("invalid github installation auth_ref")
	}
	return id, nil
}

// SplitFullName splits a GitHub "owner/repo" full_name into its parts. ok is
// false for any input that isn't exactly two non-empty slash-separated tokens,
// so callers can reject a malformed webhook payload up front. Inverse-adjacent
// to the other GitHub identity helpers above.
func SplitFullName(fullName string) (owner, repo string, ok bool) {
	parts := strings.SplitN(fullName, "/", 2)
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", "", false
	}
	return parts[0], parts[1], true
}

// Subject composes the canonical subject for a published message. Round-trip
// with ParseSubject.
func Subject(ps ParsedSubject) string {
	return fmt.Sprintf("%s%s.%s.%s.%s",
		SubjectPrefix,
		ps.Placement.Jurisdiction,
		ps.Placement.ClusterID,
		ps.SourceKind,
		ps.Op,
	)
}

// ParseSubject extracts placement / source kind / op from a canonical
// subject. Errors on prefix mismatch or wrong token count; does not validate
// that the kind/op values are known — that is the caller's policy decision.
func ParseSubject(s string) (ParsedSubject, error) {
	if !strings.HasPrefix(s, SubjectPrefix) {
		return ParsedSubject{}, fmt.Errorf("subject %q missing prefix %q", s, SubjectPrefix)
	}
	parts := strings.Split(strings.TrimPrefix(s, SubjectPrefix), ".")
	if len(parts) != 4 {
		return ParsedSubject{}, fmt.Errorf("subject %q has %d tokens after prefix, want 4", s, len(parts))
	}
	for i, p := range parts {
		if p == "" {
			return ParsedSubject{}, fmt.Errorf("subject %q has empty token at position %d", s, i)
		}
	}
	return ParsedSubject{
		Placement: Placement{
			Jurisdiction: parts[0],
			ClusterID:    parts[1],
		},
		SourceKind: SourceKind(parts[2]),
		Op:         Op(parts[3]),
	}, nil
}

// SpanAttrs returns the OTel span attributes for the body-resident fields of
// a Job. Combine with ParsedSubject.SpanAttrs() at the call site so spans
// carry the full identity (subject-derived + body-derived).
func (j Job) SpanAttrs() []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("entire.source_owner", j.Source.Owner),
		attribute.String("entire.source_repo", j.Source.Repo),
		attribute.String("entire.target_ulid", j.Target.ULID),
	}
}

// LogAttrs is the slog counterpart to SpanAttrs (without the "entire." prefix).
func (j Job) LogAttrs() []slog.Attr {
	return []slog.Attr{
		slog.String("source_owner", j.Source.Owner),
		slog.String("source_repo", j.Source.Repo),
		slog.String("target_ulid", j.Target.ULID),
	}
}

// SpanAttrs returns the OTel span attributes for the subject-encoded fields
// (placement + source kind + op). Combine with Job.SpanAttrs() at the call
// site.
func (ps ParsedSubject) SpanAttrs() []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("entire.operation", string(ps.Op)),
		attribute.String("entire.source_kind", string(ps.SourceKind)),
		attribute.String("entire.target_jurisdiction", ps.Placement.Jurisdiction),
		attribute.String("entire.target_cluster_id", ps.Placement.ClusterID),
	}
}

// LogAttrs is the slog counterpart to SpanAttrs (without the "entire." prefix).
func (ps ParsedSubject) LogAttrs() []slog.Attr {
	return []slog.Attr{
		slog.String("operation", string(ps.Op)),
		slog.String("source_kind", string(ps.SourceKind)),
		slog.String("target_jurisdiction", ps.Placement.Jurisdiction),
		slog.String("target_cluster_id", ps.Placement.ClusterID),
	}
}

// ValidateFor validates the job body against the source kind carried by the
// message subject. The body is kind-shaped (github: owner/repo coordinates;
// entiredb: the by-ID source URL), so validation cannot be kind-blind — both
// producer and consumer sides have the kind in hand (the subject is built
// from it / parsed before the body).
func (j Job) ValidateFor(kind SourceKind) error {
	if err := j.validateVersion(true); err != nil {
		return err
	}
	if err := j.Source.ValidateFor(kind); err != nil {
		return err
	}
	if err := j.Target.Validate(); err != nil {
		return err
	}
	return nil
}

func (j Job) validateVersion(allowZero bool) error {
	if allowZero && j.Version == 0 {
		return nil
	}
	if j.Version != Version1 {
		return fmt.Errorf("unknown version %d", j.Version)
	}
	return nil
}

func (j Job) withVersion() Job {
	if j.Version == 0 {
		j.Version = Version1
	}
	return j
}

// entireDBSourcePath matches the exact by-ID git route an entiredb source
// URL must carry: /git/repo/<ULID> (26 Crockford base32 chars), nothing else.
var entireDBSourcePath = regexp.MustCompile(`^/git/repo/[0-9A-HJKMNP-TV-Z]{26}$`)

func (s Source) ValidateFor(kind SourceKind) error {
	switch kind {
	case SourceKindGithub:
		if s.Owner == "" {
			return errors.New("source.owner is required")
		}
		if s.Repo == "" {
			return errors.New("source.repo is required")
		}
		if s.URL != "" {
			return errors.New("source.url is forbidden for github sources")
		}
		return nil
	case SourceKindEntireDB, SourceKindEntireDBNamespace:
		if s.Owner != "" || s.Repo != "" {
			return errors.New("source.owner/repo are forbidden for entiredb sources")
		}
		if s.AuthRef != "" {
			// entiredb source fetches authenticate with the worker's client
			// cert, never a minted token.
			return errors.New("source.auth_ref is forbidden for entiredb sources")
		}
		return validateEntireDBSourceURL(s.URL)
	default:
		return fmt.Errorf("unknown source kind %q", kind)
	}
}

// validateEntireDBSourceURL treats the job as an input boundary: https only,
// a host, the exact by-ID path shape, and none of the URL parts a crafted
// job could smuggle routing through (userinfo, query, fragment, port games
// are left to the worker's host allowlist).
func validateEntireDBSourceURL(raw string) error {
	if raw == "" {
		return errors.New("source.url is required for entiredb sources")
	}
	u, err := url.Parse(raw)
	if err != nil {
		return fmt.Errorf("source.url: %w", err)
	}
	if u.Scheme != "https" {
		return fmt.Errorf("source.url scheme %q: https required", u.Scheme)
	}
	if u.Host == "" {
		return errors.New("source.url host is required")
	}
	if u.User != nil {
		return errors.New("source.url must not carry userinfo")
	}
	if u.RawQuery != "" || u.Fragment != "" || u.ForceQuery {
		return errors.New("source.url must not carry a query or fragment")
	}
	// The regexp below runs on the DECODED path, but the wire request is
	// built from the raw one — a percent-encoded variant ("/git%2Frepo%2F…",
	// "/git/repo/%30…") would pass the shape check while putting something
	// else entirely on the request line. Require the two to agree so the
	// validated shape IS the wire shape.
	if u.EscapedPath() != u.Path {
		return fmt.Errorf("source.url path %q carries percent-encoding: want the literal /git/repo/<ULID>", u.EscapedPath())
	}
	if !entireDBSourcePath.MatchString(u.Path) {
		return fmt.Errorf("source.url path %q: want exactly /git/repo/<ULID>", u.Path)
	}
	return nil
}

// SourceRepoULID extracts the source repo ULID from an entiredb source URL.
// Callers validate first; a malformed URL yields "".
func (s Source) SourceRepoULID() string {
	u, err := url.Parse(s.URL)
	if err != nil || !entireDBSourcePath.MatchString(u.Path) {
		return ""
	}
	return u.Path[len("/git/repo/"):]
}

func (t Target) Validate() error {
	if t.ULID == "" {
		return errors.New("target.ulid is required")
	}
	return nil
}

func MarshalFor(kind SourceKind, job Job) ([]byte, error) {
	job = job.withVersion()
	if err := job.ValidateFor(kind); err != nil {
		return nil, err
	}
	data, err := json.Marshal(job)
	if err != nil {
		return nil, fmt.Errorf("marshal git job: %w", err)
	}
	return data, nil
}

func UnmarshalFor(kind SourceKind, data []byte) (Job, error) {
	var job Job
	if err := json.Unmarshal(data, &job); err != nil {
		return job, fmt.Errorf("unmarshal git job: %w", err)
	}
	if err := job.validateVersion(false); err != nil {
		return job, fmt.Errorf("validate git job: %w", err)
	}
	if err := job.ValidateFor(kind); err != nil {
		return job, fmt.Errorf("validate git job: %w", err)
	}
	return job, nil
}

// MsgID composes the JetStream dedup id for a job: source coordinates +
// target, per kind — github keys on the upstream owner/repo, entiredb on the
// source repo ULID. Shared by every publisher so retries and the duplicate
// window collapse identically no matter who published.
func MsgID(parsed ParsedSubject, job Job) string {
	if parsed.SourceKind == SourceKindEntireDB || parsed.SourceKind == SourceKindEntireDBNamespace {
		return fmt.Sprintf("%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.SourceRepoULID(), job.Target.ULID)
	}
	return fmt.Sprintf("%s/%s/%s/%s/%s", parsed.Op, parsed.SourceKind, job.Source.Owner, job.Source.Repo, job.Target.ULID)
}

// EnsureStream is idempotent: create the stream if it's absent, otherwise
// reconcile any drift in the contract fields (including a Replicas scale-up
// — supported online by nats-server >= 2.8). Replicas comes from the caller
// so dev (single-node NATS) can pass 1 via ENTIRE_NATS_STREAM_REPLICAS.
// ParseStreamReplicas parses a replica count from a raw env-var string.
// Empty input returns DefaultStreamReplicas (production target). Any other
// input must be a positive integer; zero, negative, or non-integer values
// are rejected so a typo in deploy config fails fast at startup instead of
// silently shipping a single-replica stream.
func ParseStreamReplicas(raw string) (int, error) {
	if raw == "" {
		return DefaultStreamReplicas, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return 0, fmt.Errorf("invalid replica count %q: %w", raw, err)
	}
	if n < 1 {
		return 0, fmt.Errorf("invalid replica count %d: must be >= 1", n)
	}
	return n, nil
}

func EnsureStream(js nats.JetStreamContext, replicas int) error {
	desired := ownedStreamConfig(replicas)

	_, err := js.AddStream(desired)
	if err == nil {
		return nil
	}
	if !errors.Is(err, nats.ErrStreamNameAlreadyInUse) {
		return fmt.Errorf("create git mirror stream: %w", err)
	}

	existing, err := js.StreamInfo(StreamName)
	if err != nil {
		return fmt.Errorf("get git mirror stream: %w", err)
	}

	updated := existing.Config
	applyContract(&updated, replicas)
	if reflect.DeepEqual(updated, existing.Config) {
		return nil
	}

	if _, err = js.UpdateStream(&updated); err != nil {
		return fmt.Errorf("update git mirror stream: %w", err)
	}
	return nil
}

func ownedStreamConfig(replicas int) *nats.StreamConfig {
	cfg := &nats.StreamConfig{}
	applyContract(cfg, replicas)
	return cfg
}

func applyContract(cfg *nats.StreamConfig, replicas int) {
	cfg.Name = StreamName
	cfg.Subjects = []string{SubjectPrefix + ">"}
	cfg.Retention = nats.WorkQueuePolicy
	cfg.Storage = nats.FileStorage
	cfg.Discard = nats.DiscardNew
	cfg.Duplicates = StreamDuplicatesWindow
	cfg.MaxAge = StreamMaxAge
	cfg.MaxBytes = StreamMaxBytes
	cfg.Replicas = replicas
}

