package githttp

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"strings"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"

	"entire.io/forge"
	"entire.io/mirror"
	"entire.io/refpolicy"
	"entire.io/reqctx"
	"entire.io/secsignal"
	"entire.io/slogutil"
)

const (
	// SyncKindHeader declares which mirror-worker job kind a sync push
	// belongs to. Only the namespace kind may write the Entire-owned
	// namespace; see namespaceWriterScopeErrors.
	SyncKindHeader = "X-Entire-Sync-Kind"

	// SyncKindNamespace is the mirror-worker source kind that replicates
	// mirror.NativeRefPrefix. It matches the NATS source kind mirror-pipeline
	// publishes namespace jobs under, so the two must change together.
	SyncKindNamespace = "entiredb_ns"

	// gitsyncScaffoldPrefix is git-sync's own temp-ref namespace on a sync
	// TARGET: a batched bootstrap parks each branch at
	// refs/gitsync/bootstrap/heads/<branch> and removes it when the branch
	// lands. Scaffolding, not content — the sync creates and deletes these
	// itself. refpolicy reserves no part of it, so every other caller may
	// already write it; it does carve the namespace out of RSL recording, since
	// a target-only ref has no entry on the primary to attest.
	gitsyncScaffoldPrefix = refpolicy.GitSyncScaffoldPrefix
)

// errNamespaceWriterScope is the per-ref refusal a worker sync gets for the
// Entire-owned namespace. The worker's job kind, not the ref, is what is
// wrong, so the text names the kind.
var errNamespaceWriterScope = errors.New(
	"mirror-worker syncs may not write refs/heads/entire/native/*; declare " +
		SyncKindHeader + ": " + SyncKindNamespace)

// namespaceWriterScopeErrors holds a mirror-worker sync to the ref scope its
// declared job kind owns, refusing every command outside it.
//
// This is the server half of the two-writer split a GitHub mirror gets once
// the namespace ships: the GitHub-kind sync owns every ordinary ref, the
// namespace-kind sync owns refs/heads/entire/native/*, and neither may touch
// the other's refs. Both directions are enforced, keyed on the sync-kind
// header:
//
//   - A sync declaring SyncKindNamespace may write ONLY refs the namespace
//     routes (routesWithNamespace), plus git-sync's own scaffolding under
//     gitsyncScaffoldPrefix. Every other command in that push is refused.
//     The namespace job's scope IS the namespace, so this cannot refuse a
//     legitimate write.
//   - A sync declaring nothing — the GitHub-kind sync — may write everything
//     EXCEPT those refs.
//
// The worker also carries a ref-exclusion list, but that list is only as safe
// as the oldest worker build allowed to run — rolling the GitHub worker back
// to a build without it would restore a destructive prune of the whole
// namespace. Enforcing the scope here makes the exclusion an optimisation
// that avoids noisy refusals, not the safety property. The reverse direction
// is the same argument pointed the other way: a namespace worker that lost
// its scope must not be able to prune the refs GitHub owns.
//
// Refusals are per ref so the rest of a sync still converges: an obsolete
// GitHub worker's prune of the namespace is dropped and its ordinary refs
// land. Deletes are refused like creates and updates — a prune IS the
// dangerous case.
//
// Only ref commands are in scope. HEAD moves through RepoAdmin.SetDefaultBranch
// as a symref, never as a receive-pack command, so the default-branch
// reconcile is unaffected by either rule.
//
// A sync that declares nothing is gated on GITHUB-MIRROR ROWS ONLY. On every
// other row the namespace is not Entire-owned: refpolicy reserves the anchor
// on the GitHub-mirror domain alone, so refs/heads/entire/native/* is an
// ordinary branch on a native repo. Its placements are replicated by the
// entiredb-kind sync, which declares no kind and is the sole writer at every
// replica — scoping the undeclared direction to mirror rows is what keeps
// that sync from refusing those branches forever.
//
// A sync that DECLARES the namespace kind is held to the namespace on every
// row class. It is a claim about the job, not about the row, and the row
// class it writes today is not a reason to let a mis-targeted job prune a
// native replica whole.
//
// workerPush is derived from the request principal rather than passed in
// because every caller of HandleReceivePack must be covered: a caller that
// forgot the argument would silently disable the scope. mirrorRepo IS a
// parameter because it is a property of the repos row, which this function
// does not load.
func namespaceWriterScopeErrors(
	ctx context.Context,
	r *http.Request,
	mirrorRepo bool,
	repoID string,
	commands []*packp.Command,
) map[plumbing.ReferenceName]error {
	principal, _ := reqctx.GetPrincipal(ctx)
	if !isMirrorWorker(principal) {
		return nil
	}
	declaredKind := r.Header.Get(SyncKindHeader)
	namespaceSync := declaredKind == SyncKindNamespace
	if !mirrorRepo && !namespaceSync {
		return nil
	}
	var refused map[plumbing.ReferenceName]error
	for _, command := range commands {
		// A command is in scope when the ref's side of the split matches the
		// writer's. The two rules are one comparison because they are one
		// rule: each writer owns exactly one side.
		//
		// forge.NamespaceOwned, not IsNativeNamespaceRef: the bare anchor
		// sits on the namespace's side of the split, because a write to it
		// decides the fate of every ref inside. It takes the row class
		// because a worker sync resolves no routing at all.
		//
		// refpolicy also reserves the anchor exactly on the GitHub-mirror
		// domain, and that check runs before this one and refuses the whole
		// request, so today the anchor never reaches here. This gate does not
		// rely on that: the two answer to different owners (a reserved name
		// versus a declared writer), and a later carve-out or reordering must
		// not silently open the anchor to a worker sync.
		//
		// The declared kind is ORed into the row class so a namespace sync is
		// scoped to the namespace on a native row too, where the namespace is
		// an ordinary branch that this row class does not own.
		// git-sync parks a batched bootstrap's branches under
		// gitsyncScaffoldPrefix on the target, so the FIRST namespace sync
		// onto a replica that holds none of these refs writes them. That push
		// is the one that cannot be retried into success, and the header-less
		// GitHub-kind sync writes the same scaffolding already: admitting it
		// here makes the two writers symmetric on their own temp refs, and
		// reaches no content ref either of them owns. The trailing slash
		// keeps the bare anchor out, as everywhere else.
		if namespaceSync && strings.HasPrefix(command.Name.String(), gitsyncScaffoldPrefix) {
			continue
		}
		if forge.NamespaceOwned(mirrorRepo || namespaceSync, command.Name) == namespaceSync {
			continue
		}
		if refused == nil {
			refused = make(map[plumbing.ReferenceName]error, 1)
		}
		if namespaceSync {
			refused[command.Name] = fmt.Errorf(
				"namespace sync may not write %s; it is scoped to %s*", command.Name, mirror.NativeRefPrefix)
		} else {
			refused[command.Name] = errNamespaceWriterScope
		}
		slogutil.Warn(ctx, "receive-pack: refusing worker sync write outside its ref scope",
			slog.String("repo_id", repoID),
			slog.String("ref", command.Name.String()),
			slog.String("declared_sync_kind", declaredKind))
		secsignal.Emit(ctx, secsignal.PushRejected,
			secsignal.WithSurface("githttp"),
			secsignal.WithReason(scopeSignalReason(namespaceSync)),
			secsignal.WithResource("repo", repoID),
			secsignal.WithDetail("security.detail.ref", command.Name.String()))
	}
	return refused
}

// scopeSignalReason separates the two directions in the security signal, so a
// namespace worker reaching outside its scope is not indistinguishable from
// an obsolete GitHub worker pruning the namespace.
func scopeSignalReason(namespaceSync bool) string {
	if namespaceSync {
		return "namespace_sync_out_of_scope"
	}
	return "worker_namespace_scope"
}

	//
	// Backup-restore pushes (RestoreMode=true on the backup-access
	// JWT) share the same exemptions: a restore replays bundle
	// contents byte-for-byte and must not be re-routed to GitHub via
	// mirror push-through, must not trip the user-facing push-size
	// cap (whole-cluster bundles can dwarf any per-push limit), and
	// must not re-emit RSL/event entries (handled above via
	// refstore.ContextWithRestoreMode). The legacy /git/repo/{id} API-key
	// branch passed nil mirrorTargets + 0 limit explicitly; we
	// reproduce that here.
	principal, _ := reqctx.GetPrincipal(ctx)
	workerPush := isMirrorWorker(principal)
	// Withhold repo_refs_v1 emission for a worker-synced repo's initial
	// import, so consumers don't index a repo mid-import;
	// RepoAdmin.MarkMirrorInitialSyncDone releases it as one final-tips
	// snapshot. Rationale and scope: ADR 20260818-native-mirror-resync-sweep,
	// "Initial-sync ref-event gate: the worker-synced scope".
	//
	// Local to this site: the workerPush conjunct is what keeps the gate off
	// user traffic. A placement forwards user pushes to its primary rather
	// than originating them — every ref since COR-1627, main included — and
	// a GitHub mirror admits them mid-import; both sets of events must
	// flow. The refs themselves are always written; only the notification
	// is withheld.
	if workerPush && repoRow.IsWorkerSynced() && !repoRow.MirrorInitialSyncDone {
		loader.Storage().SuppressRefEvents()
	}
	// The write-mirror class (docs/auth.md §3.2) is scoped to
	// worker-synced repos — GitHub mirrors and native-mirror placements
	// — but PermitsGit ran before the repos row was loaded — enforce
	// the class boundary here, where the class is definitive. A missing
	// row (zero repoRow) is neither, so a worker push to a plain repo
	// fails closed.
	if principal.WriteMirror && !repoRow.IsWorkerSynced() {
		// A sync job racing its repo's teardown lands here after
		// RepoAdmin.Delete has removed the rows (ENT-2074). That is
		// routine — the worker's job terminates on the 403 — so log it
		// apart from the mis-provisioning signature the "write-mirror
		// sync rejected" monitor pages on (ENT-1241). Indeterminate or
		// partial states keep the alerting path: fail toward alerting.
		if !repoRowFound {
			if deleted, err := s.repoDeleted(ctx, repoID); err == nil && deleted {
				slogutil.Info(ctx, "write-mirror push to deleted repo rejected",
					slog.String("repo_id", repoID.String()))
				http.Error(w, "repository has been deleted", http.StatusForbidden)
				return
			}
		}
		// A sync job queued before a detach lands here after
		// ClearMirrorUpstream has turned the row native (ENT-2726). The
		// detached_at stamp makes that definitive, so it is routine too.
		if repoRowFound && !repoRow.DetachedAt.IsZero() {
			slogutil.Info(ctx, "write-mirror push to detached repo rejected",
				slog.String("repo_id", repoID.String()),
				slog.Time("detached_at", repoRow.DetachedAt))
			http.Error(w, "repository was detached from GitHub", http.StatusForbidden)
			return
		}
		slogutil.Warn(ctx, "write-mirror push to non-worker-synced repo rejected",
			slog.String("repo_id", repoID.String()))
		http.Error(w, "write-mirror credential permits pushes to mirror and native-mirror repos only", http.StatusForbidden)
		return
	}
	// CI push is NATIVE REPOS ONLY, and this is the kind check the git
	// path has never had. It sits here for two reasons.
	//
	// First, the class boundary: a mirror's grant sweep reads account
	// subjects only — core/mirrorperms skips any grantee whose type is not
	// "account" — so a writer tuple held by
	// an automation on a worker-synced placement is a write grant nothing
	// can revoke. SpiceDB cannot express "native only", so it is expressed
	// here, where the repos row makes the class definitive — exactly the
	// argument the write-mirror class gate above makes for itself.
	//
	// Second, defense in depth, which this path lacks and the repo API has
	// (server/repoapi/service.go refuses an automation write on kind
	// ahead of SpiceDB, so a transient 503 cannot mask it). Until now the
	// single line `automation` is not admissible on repo#writer was the
	// ENTIRE distance between a build and a push. Admitting the subject
	// type on writer removes that line deliberately, so this check
	// restores the second layer for the one limit that is not a ref: the
	// repo class.
	//
	// A missing row (zero repoRow) is not worker-synced, so it falls
	// through to the SpiceDB check, which denies an automation holding no
	// grant. That is the same fail-closed shape the write-mirror gate uses.
	if ciPushRefused(principal, repoRow.IsWorkerSynced()) {
		slogutil.Warn(ctx, "CI push to worker-synced repo rejected",
			slog.String("repo_id", repoID.String()))
		secsignal.Emit(ctx, secsignal.PushRejected,
			secsignal.WithSurface("githttp"),
			secsignal.WithReason("ci_push_non_native"),
			secsignal.WithResource("repo", repoID.String()))
		http.Error(w, errCIPushMirror.Error(), http.StatusForbidden)
		return
	}
	// The write freeze refuses every writer but the mirror worker, a
	// restore included. It runs before AdmitWrite and before the pack is
	// read, so a refused push stores nothing.
	if refuseFrozenWrite(ctx, w, principal, repoRow, repoID) {
		return
	}
	// Same Kind gate as the earlier ContextWithRestoreMode flip:
	// only a backup-access JWT may flag a push as a restore push.
	restorePush := isRestorePrincipal(principal)
	bypassPolicy := workerPush || restorePush

	// Restore prohibition for a trust-enabled repo (ADR 20260724-rsl-root-of-trust-mvp):
	// an ordinary historical restore replays bundle refs byte-for-byte and would
	// rewind or replace the repo's signed RSL/policy state, an untracked rollback
	// of the root of trust. A bootstrap_pending or rooted repo therefore refuses
	// ordinary restore outright; recovery is the dedicated reseed procedure (a
	// follow-up), which re-establishes trust rather than rewinding it.
	//
	// This check is the sole gate, not just an early-exit convenience: restore
	// mode skips RSL recording, so ensureOrdinaryWriteAllowed never runs, and
	// since the trust tripwire guards only refs/gittuf/** (migration 021) it no
	// longer rejects an ordinary-ref restore onto a non-disabled repo. Without
	// this reject, a backup-access restore could commit ordinary refs during
	// bootstrap and race the baseline snapshot.
	if restorePush && !repoRow.TrustDisabled() {
		slogutil.Warn(ctx, "ordinary restore of a trust-enabled repo rejected",
			slog.String("repo_id", repoID.String()),
			slog.String("trust_lifecycle", repoRow.TrustLifecycle))
		http.Error(w,
			"ordinary historical restore of a trust-enabled repository is prohibited; use the dedicated trust reseed procedure",
			http.StatusForbidden)
		return
	}
	if restorePush {
		// A flow 1 restore ingest reads the row it is checked against
		// from here. The ingest needs the push options, which only
		// HandleReceivePack decodes.
		r = r.WithContext(contextWithRestoreTarget(r.Context(), restoreTarget{row: repoRow, found: repoRowFound}))
	}

	// Native-mirror replication is a legitimate internal writer to a
	// bootstrap_pending or rooted repo: the worker republishes the primary's
	// signed RSL state, including gittuf refs the trust tripwire guards.
	// Declare the transaction trust-aware so its ref writes clear the tripwire.
	// Scoped to a native-mirror worker push; a GitHub-mirror worker push is not
	// trust-managed. An ordinary user push does not need a mode here: since
	// migration 021 the tripwire guards only refs/gittuf/**, and the RSL writer
	// declares its own record mode for the one gittuf ref a user push appends.
	// The mode is an audit label, not authorization; the worker's write-mirror
	// class was already enforced above.
	nativeReplication := workerPush && repoRow.IsNativeMirror()
	if nativeReplication {
		// Stamp the storer's bound context, not the request context: the
		// ref-store CAS entry points read the context captured when the storer
		// was built (resolveRepoLoader, above), so a request-context flip here
		// would never reach applyTrustWriteMode. This mirrors SetRepoGroupID.
		loader.Storage().SetTrustWriteMode(pgutil.TrustWriteModeNativeReplication)
		// Same fact, separate signal: this push lands on a placement, so it
		// skips the write-position bump. Kept off the trust mode so a writer
		// added to that audit label later does not silently inherit it.
		loader.Storage().MarkPlacementWrite()
	}

	limit := effectivePushLimit(s.MaxPushSizeBytes, repoRow.MaxPushSizeBytes)
	if bypassPolicy {
		limit = 0
	}
	var mirrorTargets *mirror.WriteTargets
	if !bypassPolicy {
		targets, rejection := mirror.AdmitWrite(ctx, s.MirrorPush.shared(), repoRow, loader.Storage())
		if rejection != nil {
			hErr := mirrorAdmissionHTTPError(rejection)
			if rejection.Kind == mirror.RejectionSyncInProgress {
				http.Error(w, hErr.message, hErr.status)
				return
			}
			w.WriteHeader(hErr.status)
			if hErr.message != "" {
				_, _ = w.Write([]byte(hErr.message)) //nolint:errcheck // error response, failure not critical
			}
			return
		}
		mirrorTargets = targets
	}
	// A user push to a native-mirror placement is forwarded to the primary,
	// which signs its RSL entry. The local write that follows must record
	// none, or the placement's RSL forks from the primary's. Replication
	// brings the primary's entry. The write also lands on a placement, so
	// it skips the write-position bump like replication does.
	if mirrorTargets != nil && repoRow.IsNativeMirror() {
		loader.Storage().MarkPlacementPushThrough()
		loader.Storage().MarkPlacementWrite()
	}
	protection := rowBranchProtection(repoRow, bypassPolicy)
	// Tag the request context so downstream spans (incl. an fsck
	// validation failure) show whether this pack came via client
	// push-through or the mirror worker's GH->entiredb sync.
	r = r.WithContext(mirrorTelemetryContext(r.Context(), mirrorTargets != nil, workerPush))
	if nativeReplication {
		// The handler's reserved-ref gate reads this to admit the primary's
		// refs/gittuf/**. Set from the same variable as the trust-write mode
		// above so the two cannot admit different pushes.
		r = r.WithContext(contextWithNativeReplication(r.Context()))
	}
	s.HandleReceivePack(w, r, loader.Storage(), limit, mirrorTargets, isMirrorRepo(repoRow), protection)
	// Best-effort analytics; see captureGitOp. The repos row loaded above
	// for mirror routing gives is_mirror for free.
	s.captureGitOp(r, eventGitPush, func() *bool { m := isMirrorRepo(repoRow); return &m })
	// A restore needs no HEAD compensation of its own. `git push
	// --mirror` does not transmit symbolic refs, but receive-pack
	// already runs updateHEADIfTargetMissing on every push: it seeds
	// HEAD when the repo has none and retargets it when the restored
	// ref set no longer contains the old target. The legacy
	// handleRepoByID instead forced HEAD -> refs/heads/main after
	// each restore, which retargeted a repo whose default branch is
	// master or develop, and did so even when the push failed.
	return
}

if r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/git-upload-pack") {
	s.HandleUploadPack(w, r, loader.Storage())
	// Best-effort analytics; see captureGitOp. is_mirror needs the repos
	// row, which this path doesn't otherwise load, so it's resolved lazily
	// and only if the event is actually emitted.

