const (
	NATSSubjectPrefix = "repo_refs_v1."
	NATSStreamName    = "repo_refs_v1"
)

// refEventVersion is the supported wire envelope version.
const refEventVersion = 1

// Wire values for RefEvent.RefOp.
const (
	RefOpCreate      = "create"
	RefOpUpdate      = "update"
	RefOpDelete      = "delete"
	RefOpForceUpdate = "force_update"
	// RefOpSymrefUpdate is a symbolic ref retargeting (today only HEAD, moved by
	// RepoAdmin.SetDefaultBranch on a default-branch change). It carries no
	// object motion: OldTarget/NewTarget stay empty and the transition is the
	// ref-name pair OldSymrefTarget → NewSymrefTarget. Additive: consumers that
	// filter on the other ops (or on refs/heads/ names) never match it.
	RefOpSymrefUpdate = "symref_update"
)

// RefEvent is the JSON wire format for ref-change notifications on NATS. It is
// a projection of a ref update: sufficient for notification, not for
// cryptographic verification.
type RefEvent struct {
	Version       int       `json:"version"`
	RepoID        string    `json:"repo_id"`
	RefName       string    `json:"ref_name"`
	RefOp         string    `json:"ref_op"`
	OldTarget     string    `json:"old_target"`
	NewTarget     string    `json:"new_target"`
	HashAlgorithm string    `json:"hash_algorithm"`
	Timestamp     time.Time `json:"timestamp"`
	// PusherID is the account ULID of the authenticated user who pushed this
	// ref change, for activity attribution. Empty for non-user pushes
	// (service accounts, backup/restore) and for events from publishers
	// predating the field. Additive: the version is unchanged because
	// consumers tolerate unknown fields and an absent pusher_id decodes to "".
	PusherID string `json:"pusher_id"`
	// PusherHandle is PusherID's human-readable half, carried because a
	// consumer outside core cannot resolve a ULID into one — the CI leaf names
	// it as a build's author. Set only when PusherID is. A display name, never
	// an authorization input. Additive, like PusherID.
	PusherHandle string `json:"pusher_handle,omitempty"`
	// PusherAutomationID is the automation ULID that pushed this ref change,
	// set only for a push authenticated as an automation (an enrolled CI
	// build, ADR 20260728-automation-principal). Empty for every human and
	// service push, and for events from publishers predating the field.
	//
	// It is carried because PusherID cannot be: an automation holds no account
	// id, so it arrives with PusherID empty, which is indistinguishable from a
	// backup restore. A CI dispatcher reads this to skip a push authored by
	// the same subscription's own automation — without it, a build that pushes
	// a ref dispatches a build that pushes a ref, at machine speed and on the
	// customer's CI budget.
	//
	// Never an authorization input. It names who pushed, and every authority
	// question is answered against SpiceDB on the push path.
	//
	// Additive, like PusherID: omitted from the payload when empty, and the
	// envelope version is unchanged.
	PusherAutomationID string `json:"pusher_automation_id,omitempty"`
	// RepoGroupID is the placement-independent identity of the group this repo
	// belongs to: the shared "github" group of a mirrored upstream (every cell's
	// placement carries the same value) or a native repo's own singleton "entire"
	// group. Empty for events from publishers predating the field, and for a
	// native repo whose data-plane row has not yet been stamped with its group
	// (the pre-existing-natives backfill is a follow-up). Consumers use it as the
	// activity "origin" — deduping a commit mirrored across N cells to one — and
	// fall back to RepoID when it is absent. Additive like PusherID: omitted from
	// the payload when empty, and the envelope version is unchanged.
	RepoGroupID string `json:"repo_group_id,omitempty"`
	// Cluster is the entry domain of the cluster that wrote the event, e.g.
	// "royalcanin.partial.to". Additive: omitted when empty, and the envelope
	// version is unchanged.
	Cluster string `json:"cluster,omitempty"`
	// DefaultBranch is the full ref name HEAD names once the change commits,
	// e.g. "refs/heads/main". On a symref_update it equals NewSymrefTarget.
	// Empty when the write path did not resolve it. Additive, like Cluster.
	DefaultBranch string `json:"default_branch,omitempty"`
	// OldSymrefTarget/NewSymrefTarget carry a symbolic ref's retargeting for
	// RefOpSymrefUpdate events (full ref names, e.g. "refs/heads/main" →
	// "refs/heads/studio"; old empty for a previously unborn or detached HEAD).

