// prepareFusedEvents builds the outbox rows for a fenced batch before the
// CAS, from the same inputs Outbox.Emit uses, and returns ctx carrying them
// so PostgresStore can insert each row inside the ref's CAS statement. It
// returns ctx unchanged and a nil carrier when nothing is to be fused: a sink
// that is not the transactional outbox, the legacy path, suppressed events,
// restore mode, no ambient transaction, or a batch with only trust refs,
// which produce no event. The RSL ref is inside refs/gittuf/** and is
// excluded with it. Rows are marshalled for every ref before the CAS knows
// which apply, so a ref the CAS rejects costs a wasted marshal, which is
// accepted. A marshal failure fails the batch, as Emit would, even for a ref
// whose CAS would have been rejected.
func (s *RecordingStore) prepareFusedEvents(ctx context.Context, repoID repositories.ID, commands []*packp.Command) (context.Context, *fusedEvents, error) {
	outbox, ok := s.events.(*refevents.Outbox)
	tx := pgutil.TxFromContext(ctx)
	if !ok || !outbox.Enabled() || tx == nil || !fencedPath(ctx) || RefEventsSuppressed(ctx) || IsRestoreMode(ctx) {
		return ctx, nil, nil
	}
	pusher := refevents.PusherFromContext(ctx)
	repoGroupID := reqctx.RepoGroupIDFromContext(ctx)
	now := time.Now()
	rows := make(map[plumbing.ReferenceName]outboxRow, len(commands))
	for _, c := range commands {
		name := c.Name.String()
		if refpolicy.InGittufNamespace(name) {
			continue
		}
		ch := refevents.Change{RefName: name, OldTarget: c.Old, NewTarget: c.New, Op: opFor(ctx, name, c.Old, c.New)}
		subject, msgID, payload, shard, err := outbox.ChangeRow(ctx, repoID, ch, pusher, repoGroupID, now)
		if err != nil {
			return ctx, nil, fmt.Errorf("fuse ref events: %w", err)
		}
		rows[c.Name] = outboxRow{subject: subject, msgID: msgID, payload: payload, shard: shard}
	}
	if len(rows) == 0 {
		return ctx, nil, nil
	}
	f := &fusedEvents{tx: tx, repoID: repoID, table: outbox.Table(), rows: rows}
	return contextWithFusedEvents(ctx, f), f, nil
}

// hasGittufCommand reports whether any command in the batch targets gittuf's
// namespace, so the common all-ordinary-refs batch skips the guard loop and its
// slice allocation entirely.
func (s *RecordingStore) hasGittufCommand(commands []*packp.Command) bool {
	for _, c := range commands {
		if refpolicy.InGittufNamespace(c.Name.String()) {
			return true
		}
	}
	return false
}

func (s *RecordingStore) RemoveReference(ctx context.Context, repoID repositories.ID, n plumbing.ReferenceName) error {
	ctx, plan, err := s.beginRSLRecording(ctx, repoID, n.String())
	if err != nil {
		return err
	}
	if err := s.applyTrustWriteMode(ctx); err != nil {
		return err
	}
	oldHash, err := s.currentHash(ctx, repoID, n)
	if err != nil {
		return err
	}
	if err := s.guardGittufFastForward(ctx, repoID, n.String(), oldHash, plumbing.ZeroHash); err != nil {
-----
	}
	span.SetAttributes(attribute.String("rsl.recording", plan.state.String()))
	s.rslTel.recordRSLOverhead(ctx, "acquire", time.Since(acquireStart))
	return plan, nil
}

// record appends RSL entries for gated repos (RSL ref and policy-staging
// excluded), then records universal NATS events (all repos, RSL ref excluded)
// on the events sink. RefEventsSuppressed(ctx) skips only the events step (the
// refs and RSL still record): a worker-synced repo's initial import holds its
// per-ref flood back until MarkMirrorInitialSyncDone emits the final-tips
// snapshot.
//
// In production the sink is the transactional refevents.Outbox: it enqueues
// the events on the same transaction as the ref CAS, and the post-commit
// relay publishes them to NATS — so an event ships iff the push committed,
// at least once. A sink error here fails the push (the wrapping TxStore
// rolls everything back); swallowing it would commit a ref change whose
// event can never be delivered.
func (s *RecordingStore) record(ctx context.Context, repoID repositories.ID, changes []refChange, clientRSLPreTip *plumbing.Hash, plan rslPlan, eventsFused bool) error {
	// recording was decided (and the advisory lock taken) up front by
	// beginRSLRecording. When set, write the RSL entries, collect a push
	// receipt carrying each ref's RSL entry number, and emit the write's final
	// coverage decision. Skipped refs are categorized so the push span can say
	// why a partial write was partial; coverage keys on the eligible-ref count
	// rather than the stored count, because the writer legitimately dedups
	// entries a gittuf client already recorded.
	if plan.state != rslOff {
		scope := s.recordScope()
		decision := RSLDecision{}
		// Assert the lifecycle admits ordinary writes BEFORE any filtering.
		//
		// The RSL writer owns this rule, but it only runs when the filtered set
		// is non-empty, and a push whose every ref is filtered out skips it.
		// That was already reachable for an all-carved-out push. Coverage makes
		// it routine, because a narrow-coverage repo filters most pushes down to
		// nothing. Without this check a bootstrap_pending repo would quietly
		// ACCEPT an ordinary push instead of rejecting it, which is the
		// fail-closed guarantee inverted. Checking here costs nothing: the
		// lifecycle is already cached for this push.
		if err := s.ensureLifecycleAdmitsWrite(ctx, repoID); err != nil {
			decision.Coverage = coverageForFailure(err, RSLCoverageGateError)
			failRSLClosed(ctx, &s.rslTel, repoID, decision, err)
			return err
		}
		// For an rslUnlocked write that touches a branch this is the second HEAD
		// read. It runs after the ref CAS, so it sees any default-branch move
		// that committed while the CAS waited on a branch row lock. An
		// rslFenced write holds HEAD in share mode, so the value it fenced is
		// still the value, and it classifies from that instead.
		mode, defaultRef, err := s.coverageForRecord(ctx, repoID, changes, plan)
		if err != nil {
			// An unreadable or unrecognized coverage mode fails the push closed,
			// exactly as an unreadable lifecycle does. Recording under a guess
			// would either omit entries a policy requires, invisibly, because
			// the entry-number chain keeps advancing on the covered refs, or
			// write entries under a policy the repo never asked for.
			decision.Coverage = coverageForFailure(err, RSLCoverageGateError)
			failRSLClosed(ctx, &s.rslTel, repoID, decision, err)
			return fmt.Errorf("rsl coverage: %w", err)
		}
		rslChanges := make([]rslstore.RefChange, 0, len(changes))
		for _, c := range changes {
			reason, err := scope.RecordSkipReasonUnder(mode, defaultRef, c.name)
			if err != nil {
				decision.Coverage = coverageForFailure(err, RSLCoverageGateError)
				failRSLClosed(ctx, &s.rslTel, repoID, decision, err)
				return fmt.Errorf("rsl coverage for %s: %w", c.name, err)
			}
			switch reason {
			case refpolicy.RecordSkipHidden:
				decision.RefsSkippedHidden++
				continue
			case refpolicy.RecordSkipReserved:
				decision.RefsSkippedReserved++
				continue
			case refpolicy.RecordSkipUnmirrored:
				decision.RefsSkippedUnmirrored++
				continue
			case refpolicy.RecordSkipScaffold:
				decision.RefsSkippedScaffold++
				continue
			case refpolicy.RecordSkipOutsideCoverage:
				decision.RefsSkippedOutsideCoverage++
				continue
			case refpolicy.RecordSkipNone:
			}
			action := packp.Update
			switch c.op {
			case refevents.RefOpCreate:
				action = packp.Create
			case refevents.RefOpDelete:
				action = packp.Delete
			}
			rslChanges = append(rslChanges, rslstore.RefChange{
				RefName:     c.name,
				NewCommit:   c.new,
				Action:      action,
				ForceUpdate: c.op == refevents.RefOpForceUpdate,
			})
		}
		if (plan.state == rslUnlocked || plan.state == rslFenced) && len(rslChanges) > 0 {
			err := fmt.Errorf("%w: %s now covers %s", ErrDefaultBranchMoved, defaultRef, rslChanges[0].RefName)
			decision.Coverage = RSLCoverageGateError
			failRSLClosed(ctx, &s.rslTel, repoID, decision, err)
			return err
		}
		if len(rslChanges) > 0 {
			writeStart := time.Now()
			writeCtx, span := entireotel.Tracer().Start(ctx, "refstore.rsl.write")
			span.SetAttributes(entireotel.RepoIDAttr(repoID.Bytes()))
			stored, err := s.rslStore.WriteRefChanges(writeCtx, repoID, rslChanges, clientRSLPreTip)
			if err != nil {
				coverage := coverageForFailure(err, RSLCoverageWriteError)
				span.SetAttributes(attribute.String("rsl.coverage", string(coverage)))
				span.RecordError(err)
				span.SetStatus(codes.Error, "rsl write failed")
				span.End()
				decision.Coverage = coverage
				emitRSLDecision(ctx, &s.rslTel, decision)
				return fmt.Errorf("rsl write: %w", err)
			}
			span.SetAttributes(attribute.Int("rsl.entries_count", len(stored)))
			span.End()
			s.rslTel.recordRSLOverhead(ctx, "write", time.Since(writeStart))
			decision.EntriesRecorded = len(stored)

