package mirrordone

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"entire.io/core/model"
	"entire.io/slogutil"
)

// PlacementCompletionWriter is the native-mirror half of the composite
// writer: nativemirror.Service's intent-aware ApplyCompletionStatus,
// which honors a completion only for a serving-eligible, active,
// unsuspended placement whose creation has not permanently failed, and
// reports whether a row actually changed. sourcePosition is the worker's
// pre-fetch snapshot of the primary's write position; a ready completion
// advances the placement's applied watermark to at least it (0 stamps
// nothing).
type PlacementCompletionWriter interface {
	ApplyCompletionStatus(ctx context.Context, id model.RepoID, status string, sourcePosition int64) (bool, error)
}

// StatusWriter is the mirror_repos.status surface of the composite writer's
// GitHub-mirror leg. *mirrorrepo.Service satisfies it. Both methods are
// best-effort and idempotent: a no-op (deleted/suspended/already-terminal
// row) returns nil so the message is Acked, not retried.
type StatusWriter interface {
	MarkReady(ctx context.Context, id model.RepoID) error
	MarkFailed(ctx context.Context, id model.RepoID) error
}

// CompletionWriter applies one decoded completion — status plus the worker's
// source-position snapshot — to the status stores. The consumer drives this;
// CompositeStatusWriter is the production implementation.
type CompletionWriter interface {
	ApplyCompletion(ctx context.Context, id model.RepoID, status string, sourcePosition int64) error
}

// CompositeStatusWriter fans one repo_ops_v1 done-event to both status
// stores: mirror_repos (GitHub mirrors) and native_mirrors (native-mirror
// placements). The two ULID spaces are disjoint and neither store can
// tell "not mine" from "mine but nothing to do" (both writers are
// best-effort no-ops on a miss — the mirror writer surfaces no
// ErrNotFound to chain on), so every completion is applied to both and
// at most one row changes.
//
// Both legs run on every completion — a failure in one never skips the
// other — and their errors are joined: any error Naks the message and
// both legs re-run on redelivery, which is safe because each is
// idempotent. The status strings are shared vocabulary: this package's
// StatusReady/StatusFailed match mirrorrepo's and nativemirror's.
type CompositeStatusWriter struct {
	// Mirrors drives mirror_repos.status (*mirrorrepo.Service).
	Mirrors StatusWriter
	// NativeMirrors drives native_mirrors.status (*nativemirror.Service).
	NativeMirrors PlacementCompletionWriter
}

// CompositeMarkStore is the InitialSyncMarkStore over both placement tables.
// Mirrors is *mirrorrepo.Service and NativeMirrors is *nativemirror.Service.
// The ULID spaces are disjoint, so exactly one leg owns a given id.
type CompositeMarkStore struct {
	Mirrors       InitialSyncMarkStore
	NativeMirrors InitialSyncMarkStore
}

// InitialSyncMarked reports whether either placement table records the flag
// as landed. The composite reads the other leg before it returns a leg
// error, so a healthy true still short-circuits the marker.
func (c CompositeMarkStore) InitialSyncMarked(ctx context.Context, id model.RepoID) (bool, error) {
	var errs []error
	for _, leg := range []InitialSyncMarkStore{c.Mirrors, c.NativeMirrors} {
		marked, err := leg.InitialSyncMarked(ctx, id)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		if marked {
			return true, nil
		}
	}
	return false, errors.Join(errs...)
}

// RecordInitialSyncMarked stamps whichever placement table owns the row. Both
// legs run; the one that does not own the ULID is a no-op.
func (c CompositeMarkStore) RecordInitialSyncMarked(ctx context.Context, id model.RepoID) error {
	return errors.Join(
		c.Mirrors.RecordInitialSyncMarked(ctx, id),
		c.NativeMirrors.RecordInitialSyncMarked(ctx, id),
	)
}

func (c CompositeStatusWriter) ApplyCompletion(ctx context.Context, id model.RepoID, status string, sourcePosition int64) error {
	var mirrorErr error
	mirrorStart := time.Now()
	switch status {
	case StatusReady:
		mirrorErr = c.Mirrors.MarkReady(ctx, id)
	case StatusFailed:
		mirrorErr = c.Mirrors.MarkFailed(ctx, id)
	default:
		// decodeEvent has already rejected unknown statuses; defensive.
		return fmt.Errorf("unknown completion status %q", status)
	}
	recordLegDuration(ctx, mirrorStart, legMirrorStatus, mirrorErr)
	if mirrorErr != nil {
		mirrorErr = fmt.Errorf("mirror status write: %w", mirrorErr)
	}

	nativeStart := time.Now()
	applied, nativeErr := c.NativeMirrors.ApplyCompletionStatus(ctx, id, status, sourcePosition)
	recordLegDuration(ctx, nativeStart, legNativeStatus, nativeErr)
	if nativeErr != nil {
		nativeErr = fmt.Errorf("native-mirror status write: %w", nativeErr)
	}
	if applied {
		// The consumer's "mirror-done applied" line fires for every ack;
		// this one fires only when a native_mirrors row actually changed,
		// so completions the intent gate silently drops stay
		// distinguishable from ones that landed.
		//
		// NOTE: since the applied watermark landed, "changed" means EITHER a
		// status transition OR a watermark-only advance, and the two are not
		// distinguishable from here — the store reports one bool. That makes
		// this line once-per-push-per-placement in steady state rather than
		// roughly once per placement lifetime, and it is no longer a reliable
		// marker of processing->ready specifically. Use the status column for
		// transitions; treat this as sync progress.
		slogutil.Info(ctx, "native-mirror completion applied",
			slog.String("placement_id", id.String()),
			slog.String("status", status),
			slog.Int64("source_position", sourcePosition),
		)
	}

	return errors.Join(mirrorErr, nativeErr)
}

