// any stage) and incomplete creations without a permanent failure — BOTH
// legs gated by the retry schedule (a failing teardown backs off like a
// failing creation; oldest-first ordering would otherwise let one poisoned
// teardown spin-starve the whole jurisdiction) and by the lease. Creations
// additionally skip decommissioned clusters (no reconciler will ever
// provision there) and suspended rows; teardowns do not (their rows must
// still be reaped). The suspended_at guard keeps the active leg symmetric
// with AdvanceStage's fenced CAS (which requires suspended_at IS NULL): every
// suspended row today is also desired_state='deleted' (MarkDesiredDeleted
// sets both) so it is reaped via the deleted leg, but without this guard a
// future "suspend an active placement" path would let Claim hand back a row
// AdvanceStage then refuses, and the errStageLost release (no backoff) would
// spin the drain loop.
// A live claim is honored until claimed_at is older than lease; after that
// any executor may reclaim (attempts bumps again — the retry counter
// counts real executions, capping is the caller's policy).
//
// Returns ok=false when nothing is eligible.
func (s *Service) Claim(ctx context.Context, claimedBy, jurisdiction string, lease time.Duration) (NativeMirror, bool, error) {
	if claimedBy == "" || jurisdiction == "" {
		return NativeMirror{}, false, errors.New("nativemirror: claimedBy and jurisdiction are required")
	}
	if lease <= 0 {
		return NativeMirror{}, false, errors.New("nativemirror: lease must be positive")
	}
	r, err := scanNativeMirror(s.pool.QueryRow(ctx,
		`UPDATE native_mirrors
		 SET claimed_by = $1, claimed_at = now(), attempts = attempts + 1
		 WHERE id = (
		     SELECT nr.id
		     FROM native_mirrors nr
		     JOIN clusters c ON c.slug = nr.cluster_slug
		     WHERE c.jurisdiction = $2
		       AND (nr.claimed_at IS NULL
		            OR nr.claimed_at < now() - ($3::INT8 * INTERVAL '1 microsecond'))
		       AND (nr.next_retry_at IS NULL OR nr.next_retry_at <= now())
		       AND (nr.desired_state = 'deleted'
		            OR (nr.desired_state = 'active'
		                AND nr.stage <> 'announced'
		                AND nr.creation_failed_at IS NULL
		                AND nr.suspended_at IS NULL
		                AND c.decommissioned_at IS NULL))
		     ORDER BY nr.created_at, nr.id
		     LIMIT 1
		 )
		 RETURNING `+nativeMirrorColumns,
		claimedBy, jurisdiction, lease.Microseconds()))
	if errors.Is(err, pgx.ErrNoRows) {
		return NativeMirror{}, false, nil
	}
	if err != nil {
		return NativeMirror{}, false, fmt.Errorf("nativemirror: claim: %w", err)
	}
	return r, true, nil
}

// AdvanceStage is the fenced stage CAS: it moves id from → to only while
// the caller still holds the claim, the row is not marked for deletion, and
// it is not suspended. Returns false without error when the guard fails —
// the caller re-reads and decides (deletion intended → teardown leg;
// otherwise another executor won and this one walks away).
//
// A successful transition also clears last_error: forward progress means the
// transient failure that RecordRetry last recorded is resolved, so a healthy
// placement (e.g. one that reaches announced after an earlier retry) doesn't
// keep stale failure text.
func (s *Service) AdvanceStage(ctx context.Context, id model.RepoID, claimedBy, from, to string) (bool, error) {
	tag, err := s.pool.Exec(ctx,
		`UPDATE native_mirrors
		 SET stage = $4, stage_updated_at = now(), last_error = ''
		 WHERE id = $1 AND claimed_by = $2 AND stage = $3
		   AND desired_state = 'active' AND suspended_at IS NULL`,
		id, claimedBy, from, to)
	if err != nil {
		return false, fmt.Errorf("nativemirror: advance %s %s→%s: %w", id, from, to, err)
	}
	return tag.RowsAffected() > 0, nil
}

// CreatedEvent is the fully marshaled native_mirror.created message Announce
// durably enqueues alongside the terminal stage CAS. The executor builds it
// with resourceevents.NewMessage while it has the mirror meta and primaries in
// hand; the relay republishes the stored bytes verbatim, so nothing is
// re-derived at publish time. MsgID is the JetStream deduplication key
// ("native_mirror.created/<repo_id>").
type CreatedEvent struct {
	MsgID   string
	Subject string
	Payload []byte
}

// Announce is the seeded→announced arm of AdvanceStage fused with the durable
// enqueue of the placement's native_mirror.created event: one transaction runs
// the fenced stage CAS (same guard as AdvanceStage, including the last_error
// clear) and inserts the outbox row, so the event is queued iff the placement
// actually announced. The relay (CreatedOutboxRelay) publishes it with PubAck
// and deletes the row only after the ack — a crash anywhere between this
// commit and the publish re-delivers, and the stream's msg-id dedup plus the
// consumer's idempotence absorb duplicates. Returns false without error when
// the guard fails, exactly like AdvanceStage.
//
// CockroachDB can abort the commit with SQLSTATE 40001 even without a
// competing writer: the outbox INSERT is a pipelined write, and a lease
// transfer or range split under it surfaces at COMMIT as
// RETRY_ASYNC_WRITE_FAILURE. Nothing is committed, so the transaction
// replays like Register instead of costing the placement an executor
// backoff.
func (s *Service) Announce(ctx context.Context, id model.RepoID, claimedBy, jurisdiction string, ev CreatedEvent) (bool, error) {
	if ev.MsgID == "" || ev.Subject == "" || len(ev.Payload) == 0 || jurisdiction == "" {
		return false, errors.New("nativemirror: announce requires a jurisdiction and a fully built created event")
	}
	return retryOnSerializationFailure(ctx, "announce "+id.String(), func() (bool, error) {
		return s.announceTx(ctx, id, claimedBy, jurisdiction, ev)
	})
}

func (s *Service) announceTx(ctx context.Context, id model.RepoID, claimedBy, jurisdiction string, ev CreatedEvent) (bool, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return false, fmt.Errorf("nativemirror: begin announce %s: %w", id, err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after commit
	tag, err := tx.Exec(ctx,
		`UPDATE native_mirrors
		 SET stage = $3, stage_updated_at = now(), last_error = ''
		 WHERE id = $1 AND claimed_by = $2 AND stage = $4
		   AND desired_state = 'active' AND suspended_at IS NULL`,
		id, claimedBy, StageAnnounced, StageSeeded)
	if err != nil {
		return false, fmt.Errorf("nativemirror: announce %s: %w", id, err)
	}
	if tag.RowsAffected() == 0 {
		return false, nil
	}
	// Plain INSERT, deliberately no ON CONFLICT: the fenced CAS above fires at
	// most once per placement (announced rows are never re-claimed and
	// ResetForRetry cannot reach an announced row), repo ULIDs are never
	// reused, and teardown-vs-announce serializes through the native_mirrors
	// row guard — so a conflicting row is an invariant break that must surface
	// as an error, not be silently kept with a stale payload.
	if _, err := tx.Exec(ctx,
		`INSERT INTO `+createdOutboxTable+` (repo_id, subject, msg_id, payload, jurisdiction)
		 VALUES ($1, $2, $3, $4, $5)`,
		id, ev.Subject, ev.MsgID, ev.Payload, jurisdiction); err != nil {
		return false, fmt.Errorf("nativemirror: enqueue created event %s: %w", id, err)
	}
	if err := tx.Commit(ctx); err != nil {
		return false, fmt.Errorf("nativemirror: commit announce %s: %w", id, err)
	}
	return true, nil
}

// Register fuses the fenced provisioned->registered CAS with the placement's
// repo_registry publish, so a registration cannot outlive its intent
// (COR-1698). False without error on a lost guard, like AdvanceStage. The CAS
// runs first: native_mirrors before repo_group, the order deleteTx takes them.
func (s *Service) Register(ctx context.Context, id model.RepoID, claimedBy string, reg model.RepoRegistration) (bool, error) {
	if s.registry == nil {
		return false, errors.New("nativemirror: register requires a registry publisher")
	}
	return retryOnSerializationFailure(ctx, "register "+id.String(), func() (bool, error) {
		return s.registerTx(ctx, id, claimedBy, reg)
	})
}

func (s *Service) registerTx(ctx context.Context, id model.RepoID, claimedBy string, reg model.RepoRegistration) (bool, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return false, fmt.Errorf("nativemirror: begin register %s: %w", id, err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after commit

	tag, err := tx.Exec(ctx,
		`UPDATE native_mirrors
		 SET stage = $3, stage_updated_at = now(), last_error = ''
		 WHERE id = $1 AND claimed_by = $2 AND stage = $4
		   AND desired_state = 'active' AND suspended_at IS NULL`,
		id, claimedBy, StageRegistered, StageProvisioned)
	if err != nil {
		return false, fmt.Errorf("nativemirror: register %s: %w", id, err)
	}
	if tag.RowsAffected() == 0 {
		return false, nil
	}
	if _, err := s.registry.PublishRepoInTx(ctx, tx, reg); err != nil {
		return false, fmt.Errorf("nativemirror: publish placement registration %s: %w", id, err)
	}
	if err := tx.Commit(ctx); err != nil {
		return false, fmt.Errorf("nativemirror: commit register %s: %w", id, err)
	}
	return true, nil
}

// Release drops the claim without touching anything else (fenced). Used
// when an executor walks away from a lost race or a completed leg.
func (s *Service) Release(ctx context.Context, id model.RepoID, claimedBy string) error {
	_, err := s.pool.Exec(ctx,
		`UPDATE native_mirrors SET claimed_by = NULL, claimed_at = NULL
		 WHERE id = $1 AND claimed_by = $2`, id, claimedBy)
	if err != nil {
		return fmt.Errorf("nativemirror: release %s: %w", id, err)
	}
	return nil
}

