// ApplyCompletionStatus applies a worker completion (ready/failed) to a
// placement's SYNC status and, on ready, advances its applied write
// watermark. It is the intent-aware half of the composite done-event writer:
// a completion is honored only for a serving-eligible, active, unsuspended
// placement whose creation has not permanently failed — a half-created,
// deleting, or dead placement must never change state off a completion that
// raced its lifecycle. Twin-parity semantics with mirrorrepo: 'ready' heals a
// prior sync failure but never resurrects a permanent creation failure;
// 'failed' applies only to a processing row (a retry-exhausted sync can never
// regress a placement that has already gone ready). Best-effort and
// idempotent: matching nothing returns applied=false with no error, and the
// consumer acks either way.
//
// sourcePosition is the primary write-position ordinal the worker snapshotted
// before fetching (ADR 20260818-native-mirror-resync-sweep); a converging
// sync holds at least everything up to it, so 'ready' stamps
// applied_position = GREATEST(applied_position, sourcePosition) — monotonic,
// and conservative under redelivery or out-of-order completions. The ready
// guard admits an already-ready row whose watermark would advance, so every
// event-driven sync keeps the watermark current after the first ready; 0
// (an old worker's omitted field) can never match that arm and degrades to
// the pure status transition. A 'failed' completion proves nothing about
// applied state and stamps nothing.
func (s *Service) ApplyCompletionStatus(ctx context.Context, id model.RepoID, status string, sourcePosition int64) (bool, error) {
	if status != StatusReady && status != StatusFailed {
		return false, fmt.Errorf("nativemirror: invalid completion status %q", status)
	}
	if status == StatusFailed {
		tag, err := s.pool.Exec(ctx,
			`UPDATE native_mirrors
			 SET status = $2
			 WHERE id = $1 AND `+completionEligible+`
			   AND status = 'processing'`,
			id, status)
		if err != nil {
			return false, fmt.Errorf("nativemirror: apply completion %s: %w", id, err)
		}
		return tag.RowsAffected() > 0, nil
	}
	tag, err := s.pool.Exec(ctx,
		`UPDATE native_mirrors
		 SET status = $2, applied_position = GREATEST(applied_position, $3)
		 WHERE id = $1 AND `+completionEligible+`
		   AND (status <> 'ready' OR applied_position < $3)`,
		id, status, sourcePosition)
	if err != nil {
		return false, fmt.Errorf("nativemirror: apply completion %s: %w", id, err)
	}
	return tag.RowsAffected() > 0, nil
}

// InitialSyncMarked reports whether the consumer has recorded that the data
// plane accepted MarkMirrorInitialSyncDone for this placement (ENT-2340). A
// missing row reads as false: the caller then calls the data plane, which
// tolerates a gone placement.
//
// A follower read: native_mirrors is homed in the primary region and the
// consumer runs in every region, so a current read costs a cross-region hop
// on each ready completion. A stale false costs one redundant data-plane
// call. A stale true needs a manual reset of the column inside the staleness
// window, which the runbook step that resets it accepts.
func (s *Service) InitialSyncMarked(ctx context.Context, id model.RepoID) (bool, error) {
	var marked bool
	err := s.pool.QueryRow(ctx,
		`SELECT initial_sync_marked_at IS NOT NULL FROM native_mirrors `+string(s.reads.AOST())+`WHERE id = $1`, id,
	).Scan(&marked)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("nativemirror: initial-sync marked %s: %w", id, err)
	}
	return marked, nil
}

