package main

import (
	"fmt"
	"strings"

	"github.com/entirehq/mirror-pipeline/pkg/gitjobs"
)

// subscriptionConfig is the single routing contract for the loop, advisory
// backstop, readiness, metrics and Fleet's durable-bound scaler.
type subscriptionConfig struct {
	subject      string
	durable      string
	role         string
	kind         gitjobs.SourceKind
	jurisdiction string
	clusterID    string
}

func resolveSubscription(jurisdiction, cluster string, kind gitjobs.SourceKind) (subscriptionConfig, error) {
	cfg := subscriptionConfig{kind: kind, jurisdiction: jurisdiction, clusterID: cluster}
	for _, token := range []string{jurisdiction, cluster} {
		if token == "" || strings.ContainsAny(token, ".*> /\\\t\r\n") {
			return cfg, fmt.Errorf("invalid mirror routing token %q", token)
		}
	}
	suffix := ""
	switch kind {
	case "":
		cfg.role = "combined"
	case gitjobs.SourceKindGithub:
		cfg.role = "github"
		suffix = ".github"
	case gitjobs.SourceKindEntireDB:
		cfg.role = "native"
		suffix = ".entiredb"
	case gitjobs.SourceKindEntireDBNamespace:
		// Its own durable, not a second filter on the native one: the worker
		// builds a single-filter-subject consumer and autoscaling is keyed per
		// durable.
		cfg.role = "native-ns"
		suffix = ".entiredb_ns"
	default:
		return cfg, fmt.Errorf("ENTIRE_MIRROR_SOURCE_KIND must be empty, github, entiredb, or entiredb_ns; got %q", kind)
	}
	cfg.subject = fmt.Sprintf("%s%s.%s%s.>", gitjobs.SubjectPrefix, jurisdiction, cluster, suffix)
	cfg.durable = mirrorConsumerDurable(jurisdiction, cluster)
	if kind != "" {
		cfg.durable = fmt.Sprintf("mirror-git-v1-%s-%s-%s", kind, jurisdiction, cluster)
	}
	return cfg, nil
}

// needsGitHub is false for every entiredb-sourced role: those fetch from a
// sibling cluster cert-only and never mint an installation token.
func (cfg subscriptionConfig) needsGitHub() bool {
	return cfg.kind != gitjobs.SourceKindEntireDB && cfg.kind != gitjobs.SourceKindEntireDBNamespace
}
func (cfg subscriptionConfig) acceptsKind(kind gitjobs.SourceKind) bool {
	return cfg.kind == "" || cfg.kind == kind
}
func (cfg subscriptionConfig) owns(parsed gitjobs.ParsedSubject) bool {
	return parsed.Placement.Jurisdiction == cfg.jurisdiction && parsed.Placement.ClusterID == cfg.clusterID && cfg.acceptsKind(parsed.SourceKind) && parsed.Op == gitjobs.OpSyncRepo && knownSourceKind(parsed.SourceKind)
}

// knownSourceKind gates owns() on the kinds this binary can actually sync, so
// a future kind on the wire is left for a worker that understands it.
func knownSourceKind(kind gitjobs.SourceKind) bool {
	switch kind {
	case gitjobs.SourceKindGithub, gitjobs.SourceKindEntireDB, gitjobs.SourceKindEntireDBNamespace:
		return true
	}
	return false
}

func (cfg subscriptionConfig) advisorySubjects() (string, string, string) {
	return strings.TrimSuffix(advisoryMaxDeliverySubject, ">") + cfg.durable,
		strings.TrimSuffix(advisoryTerminatedSubject, ">") + cfg.durable,
		advisoryQueueGroup + "-" + cfg.durable
}

func resolveCoreInternalURL(cfg subscriptionConfig, getenv func(string) string) (string, error) {
	if !cfg.needsGitHub() {
		return "", nil
	}
	url := getenv("ENTIRE_CORE_INTERNAL_URL")
	if url == "" {
		return "", fmt.Errorf("ENTIRE_CORE_INTERNAL_URL is required for worker role %s", cfg.role)
	}
	return url, nil
}
