	"fmt"
	"net/url"
	"strings"
)

// deriveSourceClusterDomain turns the trusted local target parent
// (<cluster>.<environment-internal-domain>) into the environment-wide suffix
// used to admit native-mirror sources. Fleet already configures the target
// parent through ENTIRE_TARGET_INTERNAL_URL, so adding another entiredb cluster
// in the same environment does not require updating every worker.
//
// Local dev is the one topology without that DNS shape: both target listeners
// use localhost on different ports. It has no environment-wide source suffix,
// so return the empty (fail-closed) admission domain for the explicit local
// placement while still allowing GitHub mirroring to start.
func deriveSourceClusterDomain(targetClusterParent, targetClusterID string) (string, error) {
	if targetClusterParent == "localhost" && targetClusterID == "local" {
		return "", nil
	}
	if !validDNSLabel(targetClusterID) {
		return "", fmt.Errorf("ENTIRE_MIRROR_CLUSTER_ID %q must be a lowercase valid DNS label", targetClusterID)
	}
	if targetClusterParent != strings.ToLower(targetClusterParent) {
		return "", fmt.Errorf("target cluster parent %q must be lowercase", targetClusterParent)
	}
	prefix := targetClusterID + "."
	domain, ok := strings.CutPrefix(targetClusterParent, prefix)
	if !ok || domain == "" {
		return "", fmt.Errorf("target cluster parent %q must begin with target cluster %q followed by a dot", targetClusterParent, targetClusterID)
	}
	if !validDNSSuffix(domain) {
		return "", fmt.Errorf("target cluster parent %q yields invalid DNS suffix %q", targetClusterParent, domain)
	}
	return domain, nil
}

// admitEntireDBSourceURL validates the part of an entiredb job URL that grants
// access to the worker's client certificate. gitjobs.UnmarshalFor has already
// bounded the rest of the URL (https, literal /git/repo/<ULID>, and no
// userinfo/query/fragment); this check additionally requires the production
// svctok port and an exact environment-wide host shape:
//
//	https://svctok.<single-cluster-label>.<allowed-domain>:8281
//
// It returns the admitted cluster parent, which covers both that svctok host
// and the node hosts an entiredb info/refs request may redirect to. Downstream
// transport selection uses this value rather than re-deriving trust from the
// raw job URL.
func admitEntireDBSourceURL(rawURL, allowedDomain string) (string, error) {
	if allowedDomain == "" {
		return "", fmt.Errorf("entiredb source admission is not configured: ENTIRE_TARGET_INTERNAL_URL is required")
	}
	if !validDNSSuffix(allowedDomain) || allowedDomain != strings.ToLower(allowedDomain) {
		return "", fmt.Errorf("configured entiredb source domain %q is not a lowercase valid DNS suffix", allowedDomain)
	}

